def hydrate_time(nanoseconds, tz=None):
    """Hydrator for `Time` and `LocalTime` values.

    :param nanoseconds: number of nanoseconds since midnight
    :param tz: optional timezone or tzinfo
    :return: instance of datetime.time
    """
    import datetime

    if nanoseconds is None:
        raise ValueError("nanoseconds argument must not be None")

    try:
        nanos = int(nanoseconds)
    except Exception as exc:
        raise TypeError("nanoseconds must be an int or convertible to int") from exc

    # Nanoseconds represent a point within a single day (0 <= nanos < 24h)
    one_day_nanos = 24 * 60 * 60 * 10**9
    if not (0 <= nanos < one_day_nanos):
        raise ValueError(f"nanoseconds value {nanos} is out of range for a single day")

    # Convert to hour, minute, second, microsecond
    seconds, nano_rem = divmod(nanos, 10**9)
    microseconds = nano_rem // 1000

    hour, rem = divmod(seconds, 3600)
    minute, second = divmod(rem, 60)

    # Handle tzinfo if provided
    if tz is not None:
        # If tz is a string like '+02:00' or '-05:30', convert to a datetime.timezone
        if isinstance(tz, str):
            try:
                sign = 1 if tz.startswith('+') else -1 if tz.startswith('-') else 0
                if sign != 0:
                    parts = tz.lstrip('+-').split(':')
                    hours = int(parts[0]) if len(parts) > 0 else 0
                    minutes = int(parts[1]) if len(parts) > 1 else 0
                    offset = datetime.timedelta(hours=hours, minutes=minutes)
                    tzinfo = datetime.timezone(sign * offset)
                else:
                    tzinfo = None
            except Exception:
                tzinfo = None
        else:
            tzinfo = tz

        if tzinfo is not None:
            return datetime.time(hour=hour, minute=minute, second=second,
                                 microsecond=microseconds, tzinfo=tzinfo)

    # Return naive time if tzinfo was not handled
    return datetime.time(hour=hour, minute=minute, second=second,
                         microsecond=microseconds)

