    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Try to determine the underlying data representations.
    # Prefer attributes `keys` and `values` if they exist (e.g. a table row).
    # Fall back to treating the object itself as a mapping.
    if hasattr(self, "keys") and hasattr(self, "values"):
        _keys = list(self.keys)
        _values = list(self.values)
    else:
        # Assume a mapping (dict-like) interface
        _keys = list(self)
        _values = [self[k] for k in _keys]

    # If no keys were provided, return a dictionary mapping every key to its value.
    if not keys:
        return dict(zip(_keys, _values))

    result = {}
    for key in keys:
        if isinstance(key, int):
            # treat as an index into the underlying list of values
            try:
                idx = key
                if idx < 0:
                    # support negative indices
                    if -len(_values) <= idx:
                        idx = len(_values) + idx
                    else:
                        raise IndexError(f"index {key} out of range")
                if 0 <= idx < len(_values):
                    name = _keys[idx]
                    result[name] = _values[idx]
                else:
                    raise IndexError(f"index {key} out of range")
            except IndexError as exc:
                raise exc
        else:
            # treat as a key name
            if key in _keys:
                idx = _keys.index(key)
                result[key] = _values[idx]
            else:
                # key not present -> value is None
                result[key] = None
    return result

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Try to locate a backing dictionary of field values
    if hasattr(self, "_data") and isinstance(getattr(self, "_data"), dict):
        full = getattr(self, "_data")
    elif hasattr(self, "_values") and hasattr(self, "_field_names"):
        try:
            full = dict(zip(getattr(self, "_field_names"), getattr(self, "_values")))
        except TypeError:
            full = {}
    else:
        # Fallback: use public attributes of the object
        full = {k: v for k, v in vars(self).items()
                if not k.startswith("_") and not callable(v)}

    if not keys:
        return dict(full)

    result = {}
    items = list(full.items())
    for key in keys:
        if isinstance(key, int):
            if key < 0 or key >= len(items):
                raise IndexError(f"Index {key} out of bounds for record with {len(items)} items")
            field, value = items[key]
            result[field] = value
        else:
            result[key] = full.get(key, None)
    return result

def data(self, *keys):
    """Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Retrieve all items as a list of (key, value) tuples.
    try:
        all_items = list(self.items())
    except AttributeError:
        raise AttributeError("The object does not provide an 'items()' method")

    # If no keys specified, return a mapping of all key/value pairs.
    if not keys:
        return dict(all_items)

    result = {}
    for k in keys:
        # Handle integer keys as list indices.
        if isinstance(k, int):
            # Support Python-style negative indices.
            idx = k
            if idx < 0:
                idx += len(all_items)
            if idx < 0 or idx >= len(all_items):
                raise IndexError(f"Index {k} out of the range [0, {len(all_items)-1}]")
            key, value = all_items[idx]
            result[key] = value
        else:
            # Treat non-integer keys as literal keys.
            for key, value in all_items:
                if key == k:
                    result[k] = value
                    break
            else:
                # Key not found; insert with None.
                result[k] = None
    return result

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
        """
        Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to dehydration function).
            Dehydration functions receive the value of type understood by packstream
            and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # Validate inputs
        if mode is not None:
            if not isinstance(mode, str):
                raise TypeError(f"mode must be a string, got {type(mode)}")
            mode_upper = mode.upper()
            if mode_upper not in {"READ", "WRITE"}:
                raise ValueError("mode must be 'READ' or 'WRITE'")
            mode = mode_upper

        if bookmarks is not None:
            try:
                iter(bookmarks)
            except TypeError:
                raise TypeError("bookmarks must be an iterable of bookmark strings")
            bookmarks = [b for b in bookmarks]
            for b in bookmarks:
                if not isinstance(b, str):
                    raise TypeError("each bookmark must be a string")

        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError("metadata must be a dict if provided")

        if timeout is not None:
            if not isinstance(timeout, (int, float)):
                raise TypeError("timeout must be a number")
            if timeout <= 0:
                raise ValueError("timeout must be positive")

        if db is not None and not isinstance(db, str):
            raise TypeError("db must be a string if provided")

        if imp_user is not None and not isinstance(imp_user, str):
            raise TypeError("imp_user must be a string if provided")

        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict if provided")

        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict if provided")

        # Build transaction options
        options = {}
        if mode is not None:
            options['mode'] = mode
        if bookmarks:
            options['bookmarks'] = bookmarks
        if metadata:
            options['metadata'] = metadata
        if timeout is not None:
            options['timeout'] = timeout
        if db is not None:
            options['database'] = db
        if imp_user is not None:
            options['impUser'] = imp_user

        # Store hooks on self (used later during packstream handling)
        # If hooks are not provided, ensure we have empty dicts to avoid attribute errors.
        self._dehydration_hooks = dehydration_hooks or {}
        self._hydration_hooks = hydration_hooks or {}

        # Append the BEGIN message to the output queue.
        # The actual representation may vary; we use a simple tuple here.
        if not hasattr(self, '_output_queue'):
            # fall back to a simple list if attribute not present
            self._output_queue = []
        self._output_queue.append(('BEGIN', options))

        # Return a Response instance. We assume a Response class exists that
        # can be constructed with the current transaction instance, the user
        # supplied handlers, and any hydration/dehydration hooks.
        # The exact constructor signature can be adapted if needed.
        return Response(self, handlers=handlers,
                        hydration_hooks=self._hydration_hooks,
                        dehydration_hooks=self._dehydration_hooks)

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
              db=None, imp_user=None, dehydration_hooks=None,
              hydration_hooks=None, **handlers):
        """Appends a BEGIN message to the output queue.

        :param mode: access mode for routing - "READ" or "WRITE" (default)
        :param bookmarks: iterable of bookmark values after which this transaction should begin
        :param metadata: custom metadata dictionary to attach to the transaction
        :param timeout: timeout for transaction execution (seconds)
        :param db: name of the database against which to begin the transaction
            Requires Bolt 4.0+.
        :param imp_user: the user to impersonate
            Requires Bolt 4.4+
        :param dehydration_hooks:
            Hooks to dehydrate types (dict from type (class) to dehydration
            function). Dehydration functions receive the value and returns an
            object of type understood by packstream.
        :param hydration_hooks:
            Hooks to hydrate types (mapping from type (class) to
            hydration function). Hydration functions receive the value of
            type understood by packstream and are free to return anything.
        :param handlers: handler functions passed into the returned Response object
        :return: Response object
        """
        # --- Validation ----------------------------------------------------
        if mode is not None and mode not in ("READ", "WRITE"):
            raise ValueError("mode must be either 'READ' or 'WRITE'")
        if bookmarks is not None:
            try:
                bookmarks = list(bookmarks)
            except TypeError:
                raise TypeError("bookmarks must be an iterable")
        if metadata is not None and not isinstance(metadata, dict):
            raise TypeError("metadata must be a dict")
        if timeout is not None and not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be a numeric type")
        if dehydration_hooks is not None and not isinstance(dehydration_hooks, dict):
            raise TypeError("dehydration_hooks must be a dict")
        if hydration_hooks is not None and not isinstance(hydration_hooks, dict):
            raise TypeError("hydration_hooks must be a dict")
        for name, h in handlers.items():
            if not callable(h):
                raise TypeError(f"handler '{name}' must be callable")
        # --- Build payload --------------------------------------------------
        payload = {}
        if mode is not None:
            payload["mode"] = mode
        if db is not None:
            payload["database"] = db
        if imp_user is not None:
            payload["impersonated-user"] = imp_user
        if timeout is not None:
            payload["timeout"] = timeout
        if bookmarks:
            payload["bookmarks"] = bookmarks
        if metadata:
            payload["metadata"] = metadata
        if dehydration_hooks:
            payload["dehydration-hooks"] = dehydration_hooks
        if hydration_hooks:
            payload["hydration-hooks"] = hydration_hooks
        # --- Send message ---------------------------------------------------
        msg = {"type": "BEGIN", "payload": payload}
        try:
            # Typical driver implementation uses a queue; fall back to list
            q = getattr(self, "_out_q", None) or getattr(self, "queue", None)
            if q is not None and hasattr(q, "put"):
                q.put(msg)
            elif q is not None and hasattr(q, "append"):
                q.append(msg)
            else:
                # No queue – store in a local list if possible
                if hasattr(self, "_messages"):
                    self._messages.append(msg)
                else:
                    self._messages = [msg]  # pragma: no cover
        except Exception:  # pragma: no cover
            # If something unexpected happens we silently ignore
            pass
        # --- Return Response object -----------------------------------------
        return Response(handlers)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass.
    """
    # Validate arguments
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not isinstance(fields, (list, tuple)):
        raise TypeError("fields must be a list or tuple of (field_name, default)")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")

    # Prepare class attributes
    class_attrs = {"SRID_MAP": srid_map}
    for field_name, default_value in fields:
        if not isinstance(field_name, str):
            raise TypeError("field names must be strings")
        class_attrs[field_name] = default_value

    # Dynamically create and return the new subclass
    return type(name, (Point,), class_attrs)

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    # Validate inputs
    if not isinstance(name, str):
        raise TypeError("name must be a string")
    if not hasattr(fields, "__iter__") or isinstance(fields, (str, bytes)):
        raise TypeError("fields must be an iterable of field names")
    if not isinstance(srid_map, dict):
        raise TypeError("srid_map must be a dictionary")
    field_list = list(fields)
    # Build class attributes
    attrs = {
        "__slots__": field_list,
        "SRID_MAP": srid_map,
        "__module__": __name__,
    }

    def __init__(self, *args, **kwargs):
        if len(args) > len(field_list):
            raise TypeError(f"Expected at most {len(field_list)} positional arguments")
        # Assign positional args
        for i, value in enumerate(args):
            setattr(self, field_list[i], value)
        # Assign keyword args
        for key, value in kwargs.items():
            if key not in field_list:
                raise TypeError(f"Unexpected keyword argument: {key}")
            setattr(self, key, value)
        # Ensure all fields are set
        for f in field_list:
            if not hasattr(self, f):
                raise TypeError(f"Missing required field: {f}")

    def __repr__(self):
        values = (f"{f}={getattr(self, f)!r}" for f in field_list)
        return f"{name}({', '.join(values)})"

    attrs["__init__"] = __init__
    attrs["__repr__"] = __repr__

    # Create and return the new subclass
    cls = type(name, (object,), attrs)
    cls.__doc__ = f"Auto-generated {name} point type with fields {field_list}"
    return cls

def point_type(name, fields, srid_map):
    """ Dynamically create a Point subclass. """
    if not isinstance(name, str):
        raise TypeError('name must be a string')
    if not isinstance(fields, dict):
        raise TypeError('fields must be a dict')
    if not isinstance(srid_map, dict):
        raise TypeError('srid_map must be a dict')

    attrs = {
        '__module__': __name__,
        '__doc__': f'{name} dynamic Point subclass.',
        'SRID_MAP': srid_map
    }

    # Add default values or placeholders for the specified fields
    for key, default in fields.items():
        attrs[key] = default

    # Define an __init__ that accepts values for the fields
    def __init__(self, *args, **kwargs):
        # Positional arguments are assigned in the order of fields
        for key, value in zip(fields.keys(), args):
            setattr(self, key, value)
        # Keyword arguments override positional or default values
        for key, value in kwargs.items():
            if key in fields:
                setattr(self, key, value)
            else:
                raise TypeError(f"Unexpected keyword argument: {key}")
    attrs['__init__'] = __init__

    # Create the new class dynamically
    return type(name, (Point,), attrs)

def deprecated(message):
    """Decorator for deprecating functions and methods.

    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """
    def decorator(func):
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            import warnings
            warnings.warn(message, category=DeprecationWarning, stacklevel=2)
            return func(*args, **kwargs)
        return wrapper
    return decorator

