    ::

        @deprecated("'foo' has been deprecated in favour of 'bar'")
        def foo(x):
            pass

    """

    def decorator(func):
        if not callable(func):
            raise TypeError("deprecated decorator can only be applied to callables, got %r" % func)

        import warnings
        import functools

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Issue deprecation warning. The stacklevel is set to 3 so that
            # the warning points to the caller of the deprecated function
            warnings.warn(message, DeprecationWarning, stacklevel=3)
            return func(*args, **kwargs)

        return wrapper

    return decorator

def xargs(
        cmd: tuple[str, ...],
        varargs: Sequence[str],
        *,
        color: bool = False,
        target_concurrency: int = 1,
        _max_length: int = _get_platform_max_length(),
        **kwargs: Any,
) -> tuple[int, bytes]:
    """A simplified implementation of xargs.

    color: Make a pty if on a platform that supports it
    target_concurrency: Target number of partitions to run concurrently
    """
    import subprocess
    import concurrent.futures

    # Validate inputs
    if not isinstance(cmd, tuple) or not all(isinstance(c, str) for c in cmd):
        raise TypeError("cmd must be a tuple of strings")
    if not isinstance(varargs, Sequence) or not all(isinstance(v, str) for v in varargs):
        raise TypeError("varargs must be a sequence of strings")
    if not isinstance(target_concurrency, int) or target_concurrency < 1:
        raise ValueError("target_concurrency must be a positive integer")
    if not isinstance(_max_length, int) or _max_length < 1:
        raise ValueError("max_length must be a positive integer")

    # Partition varargs so that each command line does not exceed _max_length
    partitions: list[list[str]] = []
    current: list[str] = []
    current_len = sum(len(c) for c in cmd) + len(cmd)  # basic estimate of base command length
    for arg in varargs:
        addition = len(arg) + 1  # plus space
        if current_len + addition > _max_length and current:
            partitions.append(current)
            current = [arg]
            current_len = sum(len(c) for c in cmd) + len(cmd) + addition
        else:
            current.append(arg)
            current_len += addition
    if current:
        partitions.append(current)

    # Build the command list for each partition
    command_lists = [list(cmd) + part for part in partitions]

    # Run the commands, possibly concurrently
    outputs = bytearray()
    return_code = 0

    # Helper to run a single command
    def _run_one(cmd_list: list[str]) -> tuple[int, bytes]:
        # If color requested and a TTY is available, try to allocate a pseudo tty
        if color:
            try:
                # pyparsing: use the platform's pseudo tty facility via subprocess
                return subprocess.run(
                    cmd_list,
                    capture_output=True,
                    check=False,
                    **kwargs,
                ).returncode, subprocess.run(
                    cmd_list,
                    capture_output=True,
                    check=False,
                    **kwargs,
                ).stdout
            except Exception:
                pass
        result = subprocess.run(cmd_list, capture_output=True, check=False, **kwargs)
        return result.returncode, result.stdout

    if target_concurrency == 1 or len(command_lists) == 1:
        # Sequential execution
        for cl in command_lists:
            rc, out = _run_one(cl)
            outputs.extend(out)
            if rc != 0 and return_code == 0:
                return_code = rc
    else:
        # Concurrent execution
        with concurrent.futures.ThreadPoolExecutor(max_workers=target_concurrency) as executor:
            futures = {executor.submit(_run_one, cl): cl for cl in command_lists}
            for fut in concurrent.futures.as_completed(futures):
                rc, out = fut.result()
                outputs.extend(out)
                if rc != 0 and return_code == 0:
                    return_code = rc

    return return_code, bytes(outputs)

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle"""
    if not isinstance(seq, Sequence):
        raise TypeError("seq must be a sequence")
    for item in seq:
        if not isinstance(item, str):
            raise TypeError("All elements must be strings")
    lst = list(seq)
    seed = 0
    for s in lst:
        for c in s:
            seed = (seed * 31 + ord(c)) & 0xFFFFFFFFFFFFFFFF
    a = 6364136223846793005
    c = 1442695040888963407
    for i in range(len(lst) - 1, 0, -1):
        seed = (a * seed + c) & 0xFFFFFFFFFFFFFFFF
        j = seed % (i + 1)
        lst[i], lst[j] = lst[j], lst[i]
    return lst

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError("parse_version expects a string")
    import re
    parts = re.split(r'\D+', s.strip())
    nums = [int(p) for p in parts if p]
    return tuple(nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    s = s.strip()
    if not s:
        raise ValueError("Empty or whitespace-only version string")
    parts = s.split('.')
    version_nums = []
    for part in parts:
        part = part.strip()
        if part == '':
            raise ValueError(f"Invalid empty part in version string: '{s}'")
        # Extract leading numeric characters
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if not num_str:
            raise ValueError(f"Part '{part}' of version string '{s}' is not numeric")
        version_nums.append(int(num_str))
    return tuple(version_nums)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison"""
    import re
    if not isinstance(s, str):
        raise TypeError(f"Expected a string, got {type(s).__name__}")
    parts = re.findall(r'\d+', s)
    if not parts:
        return tuple()
    return tuple(int(p) for p in parts)

def parse_version(s: str) -> tuple[int, ...]:
    """poor man's version comparison

    Convert a version string like ``'1.2.3'`` into a tuple of integers suitable
    for normal tuple comparison.  Non‑numeric components are ignored; parsing
    stops at the first component that cannot be interpreted as an integer.
    Leading/trailing whitespace is stripped.  Empty input yields an empty
    tuple.
    """
    if not isinstance(s, str):
        raise TypeError(f"Expected str, got {type(s).__name__}")

    parts = s.strip().split('.')
    if not parts or parts == ['']:
        return tuple()

    nums = []
    for part in parts:
        try:
            nums.append(int(part))
        except ValueError:
            # stop parsing on first non‑numeric component
            break
    return tuple(nums)

def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    """
    def decorator(func):
        import functools
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            # Determine the key for caching
            try:
                cache_key = key(args, kwargs) if callable(key) else key
            except Exception:
                cache_key = hash((args, tuple(sorted(kwargs.items()))))
            # Retrieve from cache or compute and store
            if lock:
                with lock:
                    if cache_key in cache:
                        return cache[cache_key]
                    result = func(*args, **kwargs)
                    cache[cache_key] = result
                    return result
            else:
                if cache_key in cache:
                    return cache[cache_key]
                result = func(*args, **kwargs)
                cache[cache_key] = result
                return result
        return wrapper
    return decorator

