def _reset_logging(cls):
    """Reset logging configuration to defaults."""
    import logging
    try:
        root = logging.getLogger()
        # Remove all handlers attached to the root logger
        while root.handlers:
            handler = root.handlers[0]
            root.removeHandler(handler)
            # Attempt to close the handler to release resources
            try:
                handler.close()
            except Exception:
                pass
        # Restore the root logger to a sane default state
        root.setLevel(logging.WARNING)
        root.propagate = True
    except Exception:
        # Ignore any errors (e.g. logging module not available)
        pass

def _reset_logging(cls):
    """
    Reset all logging handlers and configuration to the default state.

    This method clears any existing handlers, removes them from their
    respective loggers, sets the root logger level to WARNING, and adds a
    ``logging.NullHandler`` to prevent "No handler found" warnings.
    """
    import logging

    # Clear handlers for all loggers in the logging manager
    for logger in logging.root.manager.loggerDict.values():
        # `loggerDict` may contain non-Logger objects (e.g., Mock objects in tests),
        # so guard the call
        if isinstance(logger, logging.Logger):
            for handler in logger.handlers[:]:
                try:
                    logger.removeHandler(handler)
                except Exception:
                    # Skip any handlers that raise during removal
                    pass

    # Clear handlers for the root logger
    root = logging.getLogger()
    for handler in root.handlers[:]:
        try:
            root.removeHandler(handler)
        except Exception:
            pass

    # Set a sane default level
    root.setLevel(logging.WARNING)

    # Ensure the root logger has at least one handler to avoid "No handler found" messages
    if not root.handlers:
        root.addHandler(logging.NullHandler())

