        for item in ordering:
            if item not in seen:
                seen.add(item)
                order.append(item)

    # Build adjacency lists and indegree counts
    neighbors = {item: set() for item in order}
    indegree = {item: 0 for item in order}

    for ordering in orderings:
        for u, v in zip(ordering, ordering[1:]):
            # Ensure both nodes are in the graph
            if u not in neighbors:
                neighbors[u] = set()
                indegree[u] = 0
            if v not in neighbors:
                neighbors[v] = set()
                indegree[v] = 0
            # Add edge u -> v if not already present
            if v not in neighbors[u]:
                neighbors[u].add(v)
                indegree[v] += 1

    result = []
    # Keep iterating until all items are placed
    while len(result) < len(order):
        progress = False
        for item in order:
            if item in result:
                continue
            if indegree[item] == 0:
                result.append(item)
                # Reduce indegree of successors
                for nxt in neighbors[item]:
                    indegree[nxt] -= 1
                progress = True
        if not progress:
            # No progress means there is a cycle or unsatisfiable constraints
            raise ValueError("Cannot merge orderings due to cyclic dependencies")
    return result

def _legacy_mergeOrderings(orderings):
    """Merge multiple orderings so that within-ordering order is preserved

    Orderings are constrained in such a way that if an object appears
    in two or more orderings, then the suffix that begins with the
    object must be in both orderings.

    For example:

    >>> _mergeOrderings([
    ... ['x', 'y', 'z'],
    ... ['q', 'z'],
    ... [1, 3, 5],
    ... ['z']
    ... ])
    ['x', 'y', 'q', 1, 3, 5, 'z']

    """

    if not orderings:
        return []

    # Build graph
    successors = {}
    indegree = {}
    first_seen = {}

    idx = 0
    for seq in orderings:
        for item in seq:
            if item not in successors:
                successors[item] = set()
            if item not in indegree:
                indegree[item] = 0
            if item not in first_seen:
                first_seen[item] = idx
                idx += 1
        # Add edges
        for a, b in zip(seq, seq[1:]):
            if b not in successors[a]:
                successors[a].add(b)
                indegree[b] = indegree.get(b, 0) + 1

    # Kahn's algorithm
    zero = [node for node, deg in indegree.items() if deg == 0]
    # Sort zero list by first seen to have deterministic order
    zero.sort(key=lambda x: first_seen[x])

    result = []
    while zero:
        # pop the node with smallest first_seen
        node = zero.pop(0)
        result.append(node)
        for succ in successors.get(node, ()):
            indegree[succ] -= 1
            if indegree[succ] == 0:
                # insert succ in sorted position
                inserted = False
                for i, existing in enumerate(zero):
                    if first_seen[succ] < first_seen[existing]:
                        zero.insert(i, succ)
                        inserted = True
                        break
                if not inserted:
                    zero.append(succ)

    if len(result) != len(successors):
        # cycle detected
        raise ValueError("Orderings contain a cycle")
    return result

