def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    if classes is None:
        return []

    # Convert iterable to list and validate elements
    try:
        classes_list = list(classes)
    except TypeError:
        raise TypeError("classes must be an iterable of class types")

    for c in classes_list:
        if not isinstance(c, type):
            raise TypeError(f"Element {c!r} is not a class type")

    # Remove duplicates while preserving order
    seen = set()
    unique = []
    for c in classes_list:
        if c not in seen:
            seen.add(c)
            unique.append(c)

    # Keep only minimal classes (those that are not superclasses of any other in the list)
    minimal = []
    for c in unique:
        if not any(c is not d and issubclass(d, c) for d in unique):
            minimal.append(c)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Convert to list to allow multiple passes
    try:
        base_list = list(classes)
    except TypeError:
        raise TypeError("minimalBases expects an iterable of class objects")

    # Ensure each element is a class type
    for cls in base_list:
        if not isinstance(cls, type):
            raise TypeError(f"Item {cls!r} is not a class type")

    minimal = []
    seen = set()

    for cls in base_list:
        # Skip duplicates
        if cls in seen:
            continue
        # If any other class in the original list is a subclass of this one,
        # then this class is redundant (a superclass) and can be omitted.
        if any(issubclass(other, cls) and other is not cls for other in base_list):
            continue
        minimal.append(cls)
        seen.add(cls)

    return minimal

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate that input is a sequence of class types
    if not isinstance(classes, (list, tuple)):
        raise TypeError("classes must be a list or tuple of classes")

    for cls in classes:
        if not isinstance(cls, type):
            raise TypeError(f"All items in classes must be type objects, got {type(cls).__name__}")

    # Preserve original order without duplicates
    unique = []
    for cls in classes:
        if cls not in unique:
            unique.append(cls)

    # Keep only those classes that are not superclasses of any other in unique
    minimal = []
    for cls in unique:
        # If any other class in unique inherits from cls, skip cls
        if any(issubclass(other, cls) and other is not cls for other in unique):
            continue
        minimal.append(cls)

    return minimal

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Get the interface definition defined on the class
    interface = getattr(self.__class__, "INTERFACE", {})
    result = {}
    for name, meta in interface.items():
        # Support either a dict with a 'description' entry or a tuple/list
        if isinstance(meta, dict):
            desc = meta.get("description", "")
        elif isinstance(meta, (list, tuple)) and len(meta) > 1:
            desc = meta[1]
        else:
            desc = ""
        result[name] = desc
    if all:
        # Include any attributes present on the instance that aren't part of the interface
        for attr in vars(self):
            if attr not in result:
                result[attr] = ""
    return result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    import inspect

    descriptions = {}
    try:
        members = inspect.getmembers(self.__class__)
        for name, obj in members:
            # Skip private/internal attributes unless all is True
            if not all and name.startswith("_"):
                continue
            # We are only interested in non-callable attributes
            if inspect.isroutine(obj):
                continue
            # Use the attribute's __doc__ if available; otherwise None
            descriptions[name] = getattr(obj, "__doc__", None)
    except Exception as exc:
        # In unexpected cases, provide a clear error message
        raise RuntimeError(f"Failed to gather attribute names and descriptions: {exc}") from exc

    return descriptions

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    names_desc = {}

    # Include instance attributes (they cannot have descriptions)
    for name in self.__dict__:
        if not all and name.startswith('_'):
            continue
        if name not in names_desc:
            names_desc[name] = ''  # no docstring available for instance vars

    # Include class attributes and properties
    for cls in self.__class__.__mro__:
        for name, member in cls.__dict__.items():
            if not all and name.startswith('_'):
                continue
            if name in names_desc:  # already recorded (e.g., from instance)
                continue
            if callable(member):
                continue  # skip methods
            if isinstance(member, property):
                desc = member.__doc__ or ''
            else:
                desc = getattr(member, '__doc__', '')
            names_desc[name] = desc or ''
    return names_desc

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # Retrieve the required attribute definitions if they exist.
    interface = getattr(self.__class__, 'ATTRIBUTE_DESCRIPTIONS', {})
    # Merge in optional definitions when requested.
    if all:
        optional = getattr(self.__class__, 'OPTIONAL_ATTRIBUTE_DESCRIPTIONS', {})
        if isinstance(optional, dict):
            interface = {**interface, **optional}
    return interface

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # First attempt to use a class attribute that lists allowed names
    attr_names = []
    candidate_attrs = ('ATTRIBS', 'ATTRS', 'ATTRIB', 'ATTRIBUTES', 'PRED')
    for name in candidate_attrs:
        if hasattr(self.__class__, name):
            val = getattr(self.__class__, name)
            if isinstance(val, (list, tuple, set)):
                attr_names.extend(val)
            elif isinstance(val, dict):
                attr_names.extend(val.keys())
    # If no explicit list provided, fall back to inspecting the instance dictionary
    if not attr_names:
        for key, value in self.__dict__.items():
            if not key.startswith('_') and not callable(value):
                attr_names.append(key)
    # The `all` flag expands the namespace to include all visible attributes
    if all:
        all_attrs = set(attr_names)
        # Include all non-private, non-callable attributes from the class hierarchy
        for cls in self.__class__.__mro__:
            for key, value in cls.__dict__.items():
                if not key.startswith('_') and not callable(value):
                    all_attrs.add(key)
        # Include instance attributes as well
        for key in self.__dict__:
            if not key.startswith('_'):
                all_attrs.add(key)
        return sorted(all_attrs)
    return sorted(set(attr_names))

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    attr_names = set()
    for klass in self.__class__.__mro__:
        # Iterate over the class's dictionary to find attributes that are not
        # callable and (optionally) not private
        for name, value in klass.__dict__.items():
            if not all and name.startswith('_'):
                continue
            # Filter out methods, properties, descriptors, etc.
            if callable(value) or isinstance(value, (property, staticmethod, classmethod)):
                continue
            attr_names.add(name)
    # Try to include instance-specific attributes that were added to the
    # instance during runtime
    if isinstance(self, dict):
        # If the instance behaves like a dict of attributes
        attr_names.update(self.keys())
    elif hasattr(self, '__dict__'):
        attr_names.update(self.__dict__.keys())
    # Return a sorted list of unique names for consistency
    return sorted(attr_names)

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    attrs = []
    for name, val in vars(self.__class__).items():
        if callable(val):
            continue
        if not all and name.startswith('_'):
            continue
        attrs.append(name)
    return attrs

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments.

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individual interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if sequence is None:
        return output

    if not hasattr(sequence, "__iter__") or isinstance(sequence, (str, bytes)):
        raise ValueError("sequence must be an iterable of arguments")

    for item in sequence:
        if isinstance(item, (list, tuple)):
            # Recursively expand nested lists/tuples
            _normalizeargs(item, output)
        else:
            # Treat individual interfaces or implements specs as atomic
            # and do not expand them further.
            output.append(item)

    return output

def _normalizeargs(sequence, output=None):
    """
    Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    out = output if output is not None else []
    if not isinstance(out, list):
        raise TypeError("output must be a list or None")

    def _add(elem):
        if elem is None:
            return
        # Treat string and bytes as indivisible interfaces
        if isinstance(elem, (str, bytes)):
            out.append(elem)
            return
        # Expand tuples/lists (except single-element tuples which may represent a single interface)
        if isinstance(elem, (list, tuple)):
            if len(elem) == 1:
                _add(elem[0])
            else:
                for sub in elem:
                    _add(sub)
        else:
            out.append(elem)

    # If the top-level sequence is itself not iterable or is a string, add it directly
    if isinstance(sequence, (str, bytes)):
        _add(sequence)
    else:
        try:
            iterator = iter(sequence)
        except TypeError:
            _add(sequence)
        else:
            for item in iterator:
                _add(item)

    return out

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    # Ensure we have a list to accumulate results
    if output is None:
        result = []
    else:
        result = output

    # Treat non-iterables as single-element lists
    try:
        iterator = iter(sequence)
    except TypeError:
        iterator = [sequence]

    for item in iterator:
        # If the item is itself an iterable (but not a string/bytes), expand it
        if isinstance(item, (list, tuple)):
            _normalizeargs(item, result)
        else:
            result.append(item)

    return result

def _should_attempt_c_optimizations():
    """Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import os
    import sys
    # Check environment variable that forces pure Python mode
    pure_python = os.environ.get("PURE_PYTHON")
    if pure_python is not None:
        try:
            if str(pure_python).lower() in ("1", "true", "yes", "on"):
                return False
        except Exception:
            # if the value cannot be interpreted, fail safe and disable C optimizations
            return False

    # Detect PyPy implementation
    try:
        # The attribute sys.implementation.name is available on CPython >= 3.3
        # PyPy defines implementation.name as "pypy".
        if getattr(sys, "implementation", None) and sys.implementation.name == "pypy":
            return False
    except Exception:
        # If we cannot reliably detect, fall back to checking for pypy_version_info
        if hasattr(sys, "pypy_version_info"):
            return False

    return True

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not _c_optimizations_required()
    except NameError:
        # If the required function is not defined, assume default False and return its opposite
        return True

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    # Return the logical negation of the required optimizations flag.
    # If the underlying function raises an exception, we surface a more
    # descriptive error for the caller to handle.
    try:
        return not _c_optimizations_required()
    except Exception as exc:
        raise RuntimeError("Unable to determine if optimizations are ignored") from exc

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    pass

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, assume C optimizations are required
        return True

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the current context if it exists
    if hasattr(self, "context") and isinstance(self.context, dict):
        self.context = {}
    elif hasattr(self, "ctx") and isinstance(self.ctx, dict):
        self.ctx = {}
    else:
        # If no obvious context attribute, simply clear any dict‑like storage
        for name, value in list(vars(self).items()):
            if isinstance(value, dict):
                setattr(self, name, {})

    # Reinitialize the bins
    # Prefer a make_bins() method – if it exists and works, use it
    if hasattr(self, "make_bins") and callable(self.make_bins):
        try:
            self.bins = self.make_bins()
            return
        except Exception:
            # Fallback to initial_value if make_bins fails
            pass

    # Retrieve the initial value for bins
    init_val = getattr(self, "initial_value", 0)

    if hasattr(self, "bins"):
        if isinstance(self.bins, dict):
            # Reset each bin count to the initial value
            self.bins = {k: init_val for k in self.bins}
        elif isinstance(self.bins, (list, tuple)):
            # Replace list/tuple with a copy filled with the initial value
            self.bins = [init_val] * len(self.bins)
        else:
            # For any other type, attempt a direct re‑assignment
            self.bins = init_val

def reset(self):
