    # Prepare a new bins dictionary
    try:
        # If initial_value is set, use it to reset existing bins
        if hasattr(self, 'initial_value') and self.initial_value is not None:
            # Ensure bins exists and is a dict-like structure
            bins = getattr(self, 'bins', {})
            if isinstance(bins, dict):
                for key in bins:
                    bins[key] = self.initial_value
            else:
