                    # Take keys, initialize values to 0
                    self.bins = {k: 0 for k in result}
                elif isinstance(result, (list, tuple)):
                    self.bins = {k: 0 for k in result}
                else:
                    # Unknown type: fall back to empty dict
                    self.bins = {}
            else:
                # No make_bins; default to empty bins
                self.bins = {}
    except Exception as exc:
        # In case anything goes wrong, make sure we have a sane state
        self.bins = {}
        raise ResetError(f"Failed to reset histogram: {exc}") from exc"""

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset current context
    try:
        self.context = {}
    except Exception as exc:
        # If context attribute missing or not writable
        raise AttributeError(f"Cannot reset context: {exc}") from exc

    # Reinitialize bins
    try:
        # Determine if an initial value is available
        initial = getattr(self, 'initial_value', None)
        if initial is not None:
            # Use existing bins if present
            bins = getattr(self, 'bins', None)
            if bins is not None:
                # Set every bin to the initial value
                if isinstance(bins, dict):
                    for k in bins:
                        bins[k] = initial
                elif isinstance(bins, (list, tuple)):
                    self.bins = [initial] * len(bins)
                else:
                    # Unknown bin type; attempt to recreate
                    if callable(getattr(self, 'make_bins', None)):
                        self.bins = self.make_bins()
                    else:
                        self.bins = {}
            else:
                # No existing bins; try to create them
                if callable(getattr(self, 'make_bins', None)):
                    self.bins = self.make_bins()
                else:
                    self.bins = {}
        else:
            # No initial_value; use make_bins if available
            if callable(getattr(self, 'make_bins', None)):
                self.bins = self.make_bins()
            else:
                # Fallback to empty bins
                self.bins = {}
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Ensure the separator is a string
    try:
        sep = str(separator)
    except Exception:
        sep = ","

    lines = []

    # Optional header
    if header is not None:
        lines.append(str(header))

    # Helper function to turn a value into a CSV string
    def _to_csv_value(val):
        if isinstance(val, (list, tuple)):
            return sep.join(map(str, val))
        else:
            return str(val)

    # Attempt to iterate over points in a flexible way
    try:
        iterable = iter(self)
    except Exception:
        # Fallback: use a 'points' attribute if available
        iterable = getattr(self, "points", [])

    for item in iterable:
        # Try to unpack into coordinate and value
        try:
            coord, value = item
        except Exception:
            # Treat the whole item as coordinate, no value
            coord = item
            value = None

        # Process coordinate
        if isinstance(coord, (list, tuple)):
            coord_str = sep.join(map(str, coord))
        else:
            coord_str = str(coord)

        # Process value
        if value is None:
            line = coord_str
        else:
            val_str = _to_csv_value(value)
            line = f"{coord_str}{sep}{val_str}"
        lines.append(line)

    return "\n".join(lines)

def to_csv(self, separator=",", header=None):
        """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
              Iterables are converted to tables.

        Convert graph's points to CSV.

        *separator* delimits values, the default is comma.

        *header*, if not ``None``, is the first string of the output
        (new line is added automatically).

        Since a graph can be multidimensional,
        for each point first its coordinate is converted to string
        (separated by *separator*), then each part of its value.

        To convert :class:`Graph` to CSV inside a Lena sequence,
        use :class:`lena.output.ToCSV`.
        """
        lines = []

        if header is not None:
            lines.append(str(header))

        # Iterate over points; try to access commonly used attributes
        for point in getattr(self, "points", self):
            # Handle coordinate extraction
            if hasattr(point, "coordinates"):
                coords = point.coordinates
            elif hasattr(point, "coord"):
                coords = point.coord
            elif hasattr(point, "__iter__"):
                # assume first element(s) are coordinates
                try:
                    coords = point[0] if len(point) == 2 else point[:-1]
                except Exception:
                    coords = point
            else:
                coords = point

            # Handle value extraction
            if hasattr(point, "value"):
                vals = point.value
            elif hasattr(point, "values"):
                vals = point.values
            elif hasattr(point, "__iter__") and len(point) > 1:
                try:
                    vals = point[1]
                except Exception:
                    vals = []
            else:
                vals = []

            # Ensure coords and vals are iterable
            try:
                coord_parts = [str(c) for c in coords]
            except TypeError:
                coord_parts = [str(coords)]

            if not hasattr(vals, "__iter__") or isinstance(vals, str):
                vals = (vals,) if vals is not None else ()

            line_parts = coord_parts + [str(v) for v in vals]
            lines.append(separator.join(line_parts))

        return "\n".join(lines) + ("\n" if lines else "")

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Validate type of argument
    if not isinstance(coord_name, str):
        raise TypeError(f"coord_name must be a string, got {type(coord_name).__name__}")

    # Ensure the object has the expected dictionary of error indices
    if not hasattr(self, "_err_indices"):
        raise AttributeError("Missing '_err_indices' attribute on the instance.")

    # Attempt to fetch the indices for the requested coordinate
    indices = self._err_indices.get(coord_name)
    if indices is None:
        raise KeyError(f"No errors registered for coordinate '{coord_name}'.")

    # Ensure we return a mutable but non‑directly editable sequence
    try:
        # If indices is already a list/tuple, cast to list; otherwise, try to iterate
        return list(indices)
    except TypeError:
        # In case indices is not iterable (unlikely), wrap it in a list
        return [indices]

def _get_err_indices(self, coord_name):
