    # The mapping is expected to be a dict where keys are coordinate names
    # and values are lists (or sets/tuples) of indices indicating errors.
    errors_map = getattr(self, "errors", None)
    if errors_map is None:
        # If the instance does not provide an errors mapping, assume no errors.
        return []
    # Retrieve the entry for the requested coordinate.
    entry = errors_map.get(coord_name, [])
    # Normalise the entry to an iterable of indices.
    if entry is None:
        return []
    if isinstance(entry, (list, tuple, set)):
        indices = list(entry)
    else:
        # If a single non-iterable value is stored, treat it as a single index.
        indices = [entry]
    # Validate and convert indices to integers, ignoring invalid entries.
    cleaned = []
    for idx in indices:
        try:
            cleaned.append(int(idx))
        except (TypeError, ValueError):
            # Skip values that cannot be coerced to an integer.
            continue
    # Return a sorted list of unique indices to avoid duplicates and provide order.
    return sorted(set(cleaned))

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate.

    Arguments:
        coord_name: The coordinate name (string or iterable of integers).

    Returns:
        list: List of error indices for that coordinate, or an empty list if none are found.

    Raises:
        ValueError: If ``coord_name`` is ``None`` or cannot be interpreted as a coordinate.
    """
    if coord_name is None:
        raise ValueError("Coordinate name cannot be None")

    # Normalise the key for lookup.
    # If the key is an iterable (e.g. list or tuple), convert it to a tuple.
    # If it's a string, strip whitespace.
    if isinstance(coord_name, (list, tuple)):
        key = tuple(coord_name)
    elif isinstance(coord_name, str):
        key = coord_name.strip()
        # Try to interpret a hyphen-separated string as a tuple of ints.
        if all(part.isdigit() for part in key.split('-')):
            try:
                key = tuple(int(part) for part in key.split('-'))
            except Exception:
                pass
    else:
        raise ValueError("Coordinate name must be a string or an iterable of integers")

    # Retrieve the mapping dictionary; use an empty dict if not present.
    # The mapping is expected to be available as ``self._err_indices`` or ``self._error_indices``.
    mapping = getattr(self, "_err_indices", None)
    if mapping is None:
        mapping = getattr(self, "_error_indices", {})

    # If the key is still a string, attempt to fallback to a tuple key.
    if key in mapping:
        result = mapping[key]
    else:
        # If we still haven't found it with a string key, try the alternate representation
        if isinstance(key, str):
            # Attempt to parse into tuple if it looks like a coordinate string.
            toks = [tok for tok in key.replace(" ", "").split('-') if tok]
            if toks and all(tok.isdigit() for tok in toks):
                alt_key = tuple(int(tok) for tok in toks)
                result = mapping.get(alt_key, [])
            else:
                result = []
        else:
            result = mapping.get(key, [])

    # Ensure we return a list copy to avoid accidental mutation.
    return list(result) if result is not None else []

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")

    try:
        errors = getattr(self, "errors", None)
    except Exception:
        return []

    if not errors:
        return []

    key = coord_name.lower()
    if isinstance(errors, dict):
        indices = errors.get(key)
    else:
        indices = None

    if indices is None:
        return []

    if isinstance(indices, (list, tuple)):
        return list(indices)
    raise ValueError(f"Error indices for coordinate '{coord_name}' are not in a list or tuple")

