    return list(coord_errors.get(coord_name, []))

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    if not isinstance(bins, (list, tuple)):
        raise TypeError("`bins` must be a list or tuple.")
    if not isinstance(edges, (list, tuple)):
        raise TypeError("`edges` must be a list or tuple.")
    if len(edges) - 1 != len(bins):
        raise ValueError(
            f"Number of edges ({len(edges)}) must be one more than number of bins ({len(bins)})."
        )
    if len(bins) == 0:
        return 0.0

    # Ensure edges are sorted non-decreasingly
    for i in range(len(edges) - 1):
        if edges[i] > edges[i + 1]:
            raise ValueError(
                f"Edges must be non-decreasing; edge[{i}] ({edges[i]}) > edge[{i+1}] ({edges[i+1]})."
            )

    total = 0.0
    for bin_val, left, right in zip(bins, edges, edges[1:]):
        try:
            w = float(right) - float(left)
            v = float(bin_val)
        except Exception as exc:
            raise TypeError(
                f"Bins and edges must be numeric. Problem with bin={bin_val}, left={left}, right={right}."
            ) from exc
        total += v * w
    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh for
    the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Validate inputs
    try:
        bin_list = list(bins)
    except Exception as exc:
        raise TypeError(f"bins must be an iterable, got {type(bins)}") from exc

    try:
        edge_list = list(edges)
    except Exception as exc:
        raise TypeError(f"edges must be an iterable, got {type(edges)}") from exc

    n_bins = len(bin_list)
    n_edges = len(edge_list)

    if n_edges != n_bins + 1:
        raise ValueError(f"Number of edges ({n_edges}) must be one more than number of bins ({n_bins})")

    if n_bins == 0:
        return 0.0

    total = 0.0
    for b, start, end in zip(bin_list, edge_list, edge_list[1:]):
        try:
            width = float(end) - float(start)
        except Exception as exc:
            raise ValueError(f"Edge values must be numeric: {start} -> {end}") from exc

        if width < 0:
            raise ValueError(f"Edges must be monotonically increasing: {start} to {end}")

        try:
            bin_val = float(b)
        except Exception as exc:
            raise ValueError(f"Bin values must be numeric, got {b}") from exc

        total += bin_val * width

    return total

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic sanity checks
    if not isinstance(bins, (list, tuple)):
        raise TypeError("bins must be a list or tuple")
    if not isinstance(edges, (list, tuple)):
        raise TypeError("edges must be a list or tuple")
    if len(edges) != len(bins) + 1:
        raise ValueError("Number of edges must be one more than number of bins")
    # Compute integral
    total = 0.0
    for bin_val, left, right in zip(bins, edges[:-1], edges[1:]):
        try:
            width = float(right) - float(left)
            total += float(bin_val) * width
        except Exception as exc:
            raise ValueError(f"Invalid numeric values in bins/edges: {exc}") from exc
    return total

