def is_fill_request_seq(seq):
    """Test whether *seq* can be converted to a FillRequestSeq.

    True only if it is a FillRequest element
    or contains at least one such,
    and it is not a Source sequence.
    """
    # Helper to recursively search for a FillRequest instance
    def _contains_fill_request(obj):
        if isinstance(obj, FillRequest):
            return True
        # If it's a collection, inspect each item
        if isinstance(obj, (list, tuple, set)):
            for item in obj:
                if _contains_fill_request(item):
                    return True
        # If it's an element that yields children (e.g., XML element)
        # Assume a 'children' or iterable interface
        try:
            # Avoid treating strings as collections
            if isinstance(obj, str):
                return False
            for child in obj:
                if _contains_fill_request(child):
                    return True
        except TypeError:
            # obj is not iterable
            pass
        return False

    try:
        # If seq itself is a Source, it's not a FillRequestSeq candidate
        if isinstance(seq, Source):
            return False
        # If seq is a direct FillRequest
        if isinstance(seq, FillRequest):
            return True
        # If seq contains at least one FillRequest somewhere
        if _contains_fill_request(seq):
            return True
    except Exception:
        # Any error in checking is treated as not a valid seq
        return False
    return False

