def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.
    Coordinates outside the histogram edges are ignored.
    """
    # Ensure coordinates can be indexed
    try:
        indices = [int(c) for c in coord]
    except Exception:
        # Invalid coordinate format; ignore
        return

    # Obtain the shape of the histogram data structure
    try:
        shape = self.shape
    except AttributeError:
        try:
            shape = len(self)
        except Exception:
            shape = None

    if shape is None or len(indices) != len(shape):
        return

    # Check bounds for each dimension
    for idx, dim in zip(indices, shape):
        if idx < 0 or idx >= dim:
            return

    # Add the weight to the corresponding bin
    try:
        self[tuple(indices)] += weight
    except Exception:
        # Fallback for array-like structures that support __setitem__
        try:
            current = self[tuple(indices)]
            self[tuple(indices)] = current + weight
        except Exception:
            # If addition is not supported, silently ignore
            return

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Convert coordinate to a list and check dimensionality
    try:
        coords = list(coord)
    except TypeError:
        raise TypeError("coord must be an iterable of numbers")

    if len(coords) != len(self.edges):
        raise ValueError(f"Expected {len(self.edges)} dimensions, got {len(coords)}")

    # Helper function to find the bin index for a single dimension
    def _find_bin(edges, value):
        for i in range(1, len(edges)):
            if edges[i-1] <= value < edges[i]:
                return i - 1
        return None

    # Determine bin indices for all dimensions
    indices = []
    for dim, (edge, value) in enumerate(zip(self.edges, coords)):
        idx = _find_bin(edge, value)
        if idx is None:
            # Coordinate is outside the histogram bounds; ignore
            return
        indices.append(idx)

    # Increment the bin by the specified weight
    self.bins[tuple(indices)] += weight

def fill(self, coord, weight=1):
        """Fill histogram at *coord* with the given *weight*.

        Coordinates outside the histogram edges are ignored.
        """
        # Ensure numpy is available
        try:
            import numpy as np
        except ImportError:
            raise RuntimeError("numpy is required for histogram operations")

        # Validate input coordinates
        if not hasattr(self, 'edges') or not hasattr(self, 'data'):
            raise AttributeError("Histogram object is missing 'edges' or 'data' attributes")

        if isinstance(coord, (int, float)):
            coord = (coord,)
        elif isinstance(coord, (list, tuple)):
            coord = tuple(coord)
        else:
            raise TypeError(f"coordinate must be an int, float, list, or tuple, got {type(coord).__name__}")

        if len(coord) != len(self.edges):
            raise ValueError(f"Coordinate dimensionality {len(coord)} does not match histogram {len(self.edges)}")

        # Prepare list of bin indices
        bin_indices = []
        for dim, (c, edge) in enumerate(zip(coord, self.edges)):
            # Ensure edge is a numpy array for comparison
            edge = np.asarray(edge)
            if c < edge[0] or c >= edge[-1]:
                # Coordinate is outside bounds, ignore the filling
                return
            idx = np.searchsorted(edge, c, side='right') - 1
            bin_indices.append(idx)

        # Increment the histogram bin by the specified weight
        try:
            self.data[tuple(bin_indices)] += weight
        except Exception as e:
            raise RuntimeError(f"Failed to increment histogram bin: {e}")

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Import numpy only when needed
    try:
        import numpy as np
    except ImportError as exc:
        raise RuntimeError("The histogram 'fill' method requires NumPy") from exc

    # Allow scalar coordinates for 1‑dimensional histograms
    coord = np.asarray(coord)
    if coord.ndim == 0:
        coord = coord.reshape(1)

    # If the histogram is already initialized, fill it
    if hasattr(self, 'data') and hasattr(self, 'edges'):
        # Ensure the number of dimensions matches the histogram
        if len(coord) != len(self.edges):
            raise ValueError(f"Coordinate dimensionality ({len(coord)}) does not match histogram dimensionality ({len(self.edges)})")

        try:
            indices = []
            for dim, val in enumerate(coord):
                edges = self.edges[dim]
                # Determine the appropriate bin index
                idx = np.searchsorted(edges, val, side='right') - 1
                # Outside the range: ignore
                if idx < 0 or idx >= len(edges) - 1:
                    return
                indices.append(idx)

            # Increment the histogram count
            self.data[tuple(indices)] += weight
        except Exception as exc:
            raise RuntimeError("Error while filling histogram") from exc
    # Fallback: if the histogram hasn't been built yet, store actual entries
    else:
        if not hasattr(self, '_entries'):
            self._entries = []
        self._entries.append((tuple(coord), weight))
        return

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    # Validate that `labels` is a mapping
    if not isinstance(labels, dict):
        raise ValidationError(f"labels must be a dict, got {type(labels).__name__}")

    errors = []

    # Helper to test a single string against a regex
    def _match_regex(value, regex, value_desc):
        """
        Returns None if value matches regex, otherwise an error message.
        `regex` is expected to be a compiled regular expression object.
        """
        try:
            # use fullmatch to ensure the whole string matches the pattern
            if not regex.fullmatch(value):
                return f"{value_desc} '{value}' does not match the regex [{regex.pattern}]"
        except Exception as exc:
            # In case the regex object is invalid or the match operation fails
            return f"Failed to validate {value_desc} '{value}': {exc}"
        return None

    # Iterate over keys and values in the label dictionary
    for key, val in labels.items():
        # Check key type
        if not isinstance(key, (str, bytes)):
            errors.append({str(key): "expected string or bytes-like object"})
        else:
            # Try to validate key against key regex (if defined)
            if 'LABEL_KEY_REGEX' in globals():
                err_msg = _match_regex(key, globals()['LABEL_KEY_REGEX'], "Label key")
                if err_msg:
                    errors.append({key: err_msg})

        # Validate value(s)
        # If the value is a sequence (list or tuple), validate each elem
        if isinstance(val, (list, tuple)):
            for item in val:
                if not isinstance(item, (str, bytes)):
                    errors.append({str(val): "expected string or bytes-like object"})
                else:
                    if 'LABEL_VALUE_REGEX' in globals():
                        err_msg = _match_regex(item, globals()['LABEL_VALUE_REGEX'], "Label value")
                        if err_msg:
                            errors.append({item: err_msg})
        else:
            if not isinstance(val, (str, bytes)):
                errors.append({str(val): "expected string or bytes-like object"})
            else:
                if 'LABEL_VALUE_REGEX' in globals():
                    err_msg = _match_regex(val, globals()['LABEL_VALUE_REGEX'], "Label value")
                    if err_msg:
                        errors.append({val: err_msg})

    # If any errors were collected, raise a ValidationError
    if errors:
        raise ValidationError(errors)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.
    """
    import re

    # Regular expression that label keys/values must match
    # This is a generic pattern; modify as needed for stricter rules.
    key_value_regex = re.compile(r'^[A-Za-z0-9_-]+$')

    # Ensure labels is a mapping
    if not isinstance(labels, dict):
        raise ValidationError([{'labels': 'Labels must be a dictionary'}])

    messages = []

    for key, val in labels.items():
        # Key type check
        if not isinstance(key, (str, bytes)):
            messages.append({repr(key): 'expected string or bytes-like object'})
            continue  # Skip further checks for this key

        # Key regex check
        try:
            key_str = key.decode() if isinstance(key, bytes) else key
        except Exception:
            key_str = str(key)
        if not key_value_regex.match(key_str):
            messages.append(
                {key_str: f"Label key '{key_str}' does not match the regex [{key_value_regex.pattern}]"}
            )

        # Value processing
        if isinstance(val, (list, tuple)):
            # Validate each element in a list/tuple
            for el in val:
                if not isinstance(el, (str, bytes)):
                    messages.append({repr(el): 'expected string or bytes-like object'})
                else:
                    # Optional: validate element regex
                    try:
                        el_str = el.decode() if isinstance(el, bytes) else el
                    except Exception:
                        el_str = str(el)
                    if not key_value_regex.match(el_str):
                        messages.append(
                            {el_str: f"Label value '{el_str}' does not match the regex [{key_value_regex.pattern}]"}
                        )
        else:
            if not isinstance(val, (str, bytes)):
                messages.append({repr(val): 'expected string or bytes-like object'})
            else:
                # Optional: validate single value regex
                try:
                    val_str = val.decode() if isinstance(val, bytes) else val
                except Exception:
                    val_str = str(val)
                if not key_value_regex.match(val_str):
                    messages.append(
                        {val_str: f"Label value '{val_str}' does not match the regex [{key_value_regex.pattern}]"}
                    )

    if messages:
        raise ValidationError(messages)

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    import re
    # Ensure the key is a string; this also permits bytes for backward compatibility
    if isinstance(key, bytes):
        try:
            key = key.decode("utf-8")
        except Exception as exc:
            raise ValidationError(f"Key must be decodable as UTF‑8, got: {key!r}") from exc
    if not isinstance(key, str):
        raise ValidationError(f"Key must be a string, got {type(key).__name__}")
    # Define the allowed pattern; users may change this if needed
    try:
        pattern = re.compile(r"^[a-zA-Z0-9_-]+$")
    except re.error as exc:
        raise ValidationError(f"Regular expression could not be compiled: {exc}") from exc
    if not pattern.fullmatch(key):
        raise ValidationError(f"Key '{key}' does not match the required pattern.")

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    if key is None:
        raise ValidationError("Key cannot be None")
    if not isinstance(key, str):
        # Attempt to cast to string for further validation
        try:
            key = str(key)
        except Exception as exc:
            raise ValidationError(f"Key must be convertible to a string: {exc}") from exc
    # Assume a global regular expression pattern named KEY_PATTERN is defined elsewhere
    if 'KEY_PATTERN' not in globals():
        raise RuntimeError("KEY_PATTERN is not defined")
    try:
        if not re.fullmatch(KEY_PATTERN, key):
            raise ValidationError(f"Key '{key}' does not conform to the required pattern.")
    except re.error as exc:
        # In case KEY_PATTERN is not a valid regex
        raise RuntimeError(f"Invalid KEY_PATTERN: {exc}") from exc
    return True

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # guard against missing attributes
    try:
        manifest = getattr(app.spec, "manifest", None)
        if manifest is None:
            return  # nothing to do
    except Exception:
        return

    # Ensure we have a dict to store observer schemas.  The actual key
    # where schemas are stored may vary; try a few common names.
    observer_dict = None
    for attr in ("observer_schemas", "observer_schema", "observerSchema",
                 "default_observer_schema", "defaultObserverSchema"):
        if hasattr(app.spec, attr):
            observer_dict = getattr(app.spec, attr)
            break
    if observer_dict is None:
        # If no such attribute exists, create one on the spec
        observer_dict = {}
        setattr(app.spec, "observer_schemas", observer_dict)

    # If the 'manifest' is a list/tuple of resource dicts, handle directly.
    # If it is a dict keyed by name, iterate over its values.
    if isinstance(manifest, (list, tuple, set)):
        resources = list(manifest)
    elif isinstance(manifest, dict):
        resources = list(manifest.values())
    else:
        # Unsupported type – do nothing
        resources = []

    for resource in resources:
        if not isinstance(resource, dict):
            continue

        kind = resource.get("kind")
        if not kind:
            continue

        # Skip if a custom observer schema already exists
        if kind in observer_dict and observer_dict[kind]:
            continue

        # Build a very simple default schema: copy the top-level keys
        # of the resource, treating everything as stringish.  In a real
        # implementation this would be more sophisticated.
        default_schema = {}
        for key, value in resource.items():
            if key == "metadata":
                # Keep the name and namespace
                meta = {}
                for meta_key in ("name", "namespace", "labels", "annotations"):
                    if meta_key in value:
                        meta[meta_key] = value[meta_key]
                default_schema["metadata"] = meta
            else:
                # Treat other fields generically
                default_schema[key] = type(value).__name__

        # Store the generated schema
        observer_dict[kind] = default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Basic sanity checks on the application object
    if not hasattr(app, "spec"):
        raise ValueError("The application object must have a 'spec' attribute.")
    if not hasattr(app.spec, "manifest"):
        raise ValueError("The application spec must have a 'manifest' attribute.")
    manifest = app.spec.manifest

    # The manifest is expected to be an iterable of resources; guard against non‑iterable
    try:
        iter(manifest)
    except TypeError:
        raise ValueError("app.spec.manifest must be an iterable of Kubernetes resources.")

    for resource in manifest:
        # Skip resources that already define an observer schema
        custom_schema = getattr(resource, "observer_schema", None)
        if custom_schema is not None:
            continue

        # Extract required fields from the resource; allow both dicts and objects
        kind = (getattr(resource, "kind", None)
                if not isinstance(resource, dict) else
                resource.get("kind"))
        if not kind:
            # If we cannot determine a kind, we skip this resource
            continue

        api_version = (getattr(resource, "apiVersion", None)
                       if not isinstance(resource, dict) else
                       resource.get("apiVersion"))

        # Attempt to build a sensible name for the observer schema
        metadata = getattr(resource, "metadata", None) if not isinstance(resource, dict) else resource.get("metadata")
        name = None
        if metadata:
            # metadata may be a dict or an object
            if isinstance(metadata, dict):
                name = metadata.get("name")
            else:
                name = getattr(metadata, "name", None)
        if not name:
            # Fallback name if none was found
            name = f"{kind.lower()}-observer"

        # Construct the default observer schema
        default_schema = {
            "kind": kind,
            "apiVersion": api_version,
            "metadata": {
                "name": name,
                "labels": {"krake.defaultObserver": "true"},
            },
        }

        # Attach the schema to the resource
        if isinstance(resource, dict):
            resource["observer_schema"] = default_schema
        else:
            setattr(resource, "observer_schema", default_schema)

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Safely retrieve manifest and existing observer schema
    manifest = getattr(getattr(app, "spec", None), "manifest", [])
    existing_schema = getattr(getattr(app, "spec", None), "observer_schema", {})
    if not isinstance(existing_schema, dict):
        existing_schema = {}
    # Ensure manifest is iterable
    if not isinstance(manifest, (list, tuple)):
        return
    for res in manifest:
        if not isinstance(res, dict):
            continue
        kind = res.get("kind")
        if not kind:
            continue
        # Skip if custom schema already defined
        if kind in existing_schema:
            continue
        # Create a minimal default schema:
        default = {
            "kind": kind,
            "enabled": True,
            # Commonly observed fields – can be expanded if needed
            "fields": ["metadata.name", "metadata.namespace"],
        }
        existing_schema[kind] = default
    # Persist the updated schema back to the application spec
    if hasattr(app, "spec"):
        app.spec.observer_schema = existing_schema
    return

