        observer_schema = None

    if observer_schema is None:
        observer_schema = {}
        try:
            setattr(spec, "observer_schema", observer_schema)
        except Exception:
            # If we cannot set the attribute, give up.
            return

    # Helper to construct a key that uniquely identifies a resource.
    def _key(res_obj):
        kind = res_obj.get("kind")
        if not kind:
            return None
        metadata = res_obj.get("metadata", {})
        name = metadata.get("name")
        return f"{kind}:{name}" if name else kind

    # Iterate over each resource in the manifest.
    for resource in manifest:
        try:
            k = _key(resource)
        except Exception:
            continue

        if not k:
            continue

        # If a schema for this resource already exists, skip it.
        if k in observer_schema:
            continue

        # The default schema is a very permissive object schema that accepts any keys.
        # This can be replaced by more specific logic if required.
        observer_schema[k] = {"type": "object"}

def formatmany(
        self,
        sql,
        many_params,
    ):
        """Convert the SQL query to use the out‑style parameters instead of the
        in‑style parameters.

        *sql* (:class:`str` or :class:`bytes`) is the SQL query.

        *many_params* (:class:`~collections.abc.Iterable`) contains each set
        of in‑style parameters (*params*).

        Returns a :class:`tuple` containing:

        * The formatted SQL query (:class:`str` or :class:`bytes`).
        * A :class:`list` containing each set of converted out‑style
          parameters.
        """
        # Detect byte or string input
        is_bytes = isinstance(sql, (bytes, bytearray))

        # Work with string for placeholder extraction
        sql_str = sql.decode('utf-8') if is_bytes else str(sql)

        # Extract named placeholders (e.g. :name)
        placeholders = []
        i = 0
        while i < len(sql_str):
            if sql_str[i] == ':':
                j = i + 1
                # Allow alphanumerics and underscore in placeholder name
                while j < len(sql_str) and (sql_str[j].isalnum() or sql_str[j] == '_'):
                    j += 1
                if j > i + 1:
                    placeholders.append(sql_str[i:j])
                    i = j
                    continue
            i += 1

        # If we found named placeholders, replace them with positional ones
        if placeholders:
            formatted_sql = sql_str
            for ph in placeholders:
                formatted_sql = formatted_sql.replace(ph, '?', 1)

            formatted_sql = formatted_sql.encode('utf-8') if is_bytes else formatted_sql
        else:
            formatted_sql = sql

        # Convert parameters
        if many_params is None:
            converted = []
        else:
            converted = []
            for param in many_params:
                # Mapping (dict) → list in placeholder order
                if isinstance(param, (dict,)):
                    try:
                        new = [param[ph] for ph in placeholders]
                    except KeyError as exc:
                        raise KeyError(f"Missing placeholder {exc} in parameters {param}") from exc
                    converted.append(new)
                # Sequence (list/tuple) → keep as list
                else:
                    # Treat strings/bytes as scalar, not iterable
                    if isinstance(param, (str, bytes)):
                        converted.append(param)
                    else:
                        try:
                            converted.append(list(param))
                        except TypeError:
                            # Not iterable; keep as is
                            converted.append(param)

        return formatted_sql, converted

def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        # Import here to avoid top-level imports
        import os
        import json

        # Resolve the actual root path
        # If path has a 'root' attribute (e.g., pyfs root object), use it
        if hasattr(path, "root"):
            root_path = str(getattr(path, "root"))
        else:
            root_path = str(path)

        if not os.path.exists(root_path):
            return False

        # Assume the manifest JSON file is named 'manifest.json' at the root
        manifest_path = os.path.join(root_path, "manifest.json")
        if not os.path.isfile(manifest_path):
            return False

        # Load and parse the JSON manifest
        with open(manifest_path, "r", encoding="utf-8") as f:
            try:
                manifest = json.load(f)
            except json.JSONDecodeError:
                return False

        # Basic structural checks – these are minimal and can be extended
        required_keys = {"ocfl_version", "objects", "distributions"}
        if not required_keys.issubset(manifest):
            return False

        if not isinstance(manifest["objects"], list):
            return False
        if not isinstance(manifest["distributions"], dict):
            return False

        # All checks passed – consider it valid (warnings not raised here)
        return True
    except Exception:
        # Any unexpected error means validation failed
        return False

def validate(self, path):
