def status_str(self, prefix=''):
    """
    Return string representation of validation log, with optional prefix.
    The method inspects the instance for attributes that may contain
    logged validation messages and concatenates them into a single
    string.  Each message is prefixed with the ``prefix`` argument
    (which defaults to an empty string).

    The implementation is tolerant of the following scenarios:

    * The validation log is stored in ``self.log`` as an iterable
      of either tuples, dictionaries, or simple strings.
    * Each item can be a tuple where the message is the second element,
      a dictionary with a ``'message'`` or ``'text'`` key, or an object
      with a ``message`` or ``text`` attribute.
    * If no recognised attribute or log exists, an empty string is returned.
    * Empty or non‑string messages are ignored.
    """
    messages = []

    # Identify a candidate log container
    log_container = None
    for attr in ('log', 'entries', 'messages'):
        if hasattr(self, attr):
            log_container = getattr(self, attr)
            break

    if not log_container:
        return ''  # nothing to display

    try:
        for item in log_container:
            # Skip if item is not iterable/tuple
            if isinstance(item, tuple):
                # Search the most probable message location
                if len(item) > 1:
                    msg = item[1]
                else:
                    msg = item[0]
            elif isinstance(item, dict):
                msg = item.get('message') or item.get('text')
            else:
                msg = getattr(item, 'message', None) or getattr(item, 'text', None) or str(item)

            if msg is None:
                continue

            msg = str(msg).strip()
            if msg:
                messages.append(prefix + msg)
    except Exception as exc:
        # Fall back to string representation of the whole container
        messages.append(f"Error while processing log: {exc}")

    return '\n'.join(messages)

def validate(self, inventory, extract_spec_version=False):
        """Validate a given inventory.

        If extract_spec_version is True then will look at the type value to determine
        the specification version. In the case that there is no type value or it isn't
        valid, then other tests will be based on the version given in self.spec_version.
        """
        # Helper to get the type attribute from inventory
        def _get_type(inv):
            if isinstance(inv, dict):
                return inv.get("type")
            return getattr(inv, "type", None)

        # --- Step 1: Extract spec_version if requested ---------------------------------
        if extract_spec_version:
            inv_type = _get_type(inventory)
            if isinstance(inv_type, str):
                # attempt to capture a version number fragment
                # common patterns: "sf/foiliapst/1.0.0", "foiliapst-1.0.0", "1.0.0"
                parts = inv_type.replace("-", "/").split("/")
                for part in reversed(parts):
                    if part.count(".") >= 1 and part.replace(".", "", 1).isdigit():
                        potential = part
                        # simple version validation
                        try:
                            # just to ensure compatible format
                            if potential.replace(".", "", 1).isdigit():
                                self.spec_version = potential
                                break
                        except Exception:
                            continue

        # --- Step 2: Perform basic validation -----------------------------------------
        # Ensure self.spec_version is now defined
        if not hasattr(self, "spec_version") or self.spec_version is None:
            raise ValueError("Specification version is not defined")

        # Basic format check (must be X.Y or X.Y.Z)
        sv = str(self.spec_version)
        if sv.count(".") < 1:
            raise ValueError(f"Invalid spec_version format: {sv}")

        parts = sv.split(".")
        for p in parts:
            if not p.isdigit():
                raise ValueError(f"Invalid spec_version component: {p}")

        # Placeholder for additional checks, e.g. inventory type, required fields, etc.
        # These would normally be implemented according to the FoLiA specification.

        return True

def validate(self, inventory, extract_spec_version=False):
    """
    Validate a given inventory.

    If extract_spec_version is True then will look at the type value to determine
    the specification version. In the case that there is no type value or it isn't
    valid, then other tests will be based on the version given in self.spec_version.
    """
    # Basic type checks for the inventory container
    if not isinstance(inventory, (list, tuple)):
        raise ValueError("inventory must be a list or tuple of items.")

    seen_ids = set()
    deduced_version = None

    # Helper to compare spec versions as tuples of ints
    def _ver_tuple(v):
        try:
            return tuple(int(p) for p in str(v).split('.'))
        except Exception:
            return (0,)

    current_ver = _ver_tuple(self.spec_version)

    # Allowed types for the current spec version (optional)
    allowed_types = getattr(self, "ALLOWED_TYPES", None)
    # If the class defines per-version allowed types, try to get the correct list
    if allowed_types is None:
        # try to find attribute named ALLOWED_<VER> e.g. ALLOWED_1_0
        key = f"ALLOWED_{self.spec_version.replace('.', '_')}"
        allowed_types = getattr(self, key, None)

    for idx, item in enumerate(inventory):
        if not isinstance(item, dict):
            raise ValueError(f"Inventory item at index {idx} is not a dict.")

        # Required keys
        for key in ("id", "type"):
            if key not in item:
                raise ValueError(f"Missing required key '{key}' in inventory item at index {idx}.")

        identifier = str(item["id"])
        if identifier in seen_ids:
            raise ValueError(f"Duplicate id '{identifier}' found in inventory at index {idx}.")
        seen_ids.add(identifier)

        typ = str(item["type"])

        # Optionally extract spec version from the type string
        if extract_spec_version:
            # Expect format like "label:1.2" or "label=1.2"
            import re
            m = re.search(r'(?:[:=])(?P<ver>[0-9]+(?:\.[0-9]+)*)', typ)
            if m:
                ver = m.group("ver")
                if deduced_version is None:
                    deduced_version = ver
                elif deduced_version != ver:
                    raise ValueError(
                        f"Inconsistent specification versions in inventory: "
                        f"'{deduced_version}' vs '{ver}'."
                    )

        # Validate the type against allowed types if we have a list
        if allowed_types:
            # type name is the part before any ':' or '='
            base_type = re.split(r'[:=]', typ)[0]
            if base_type not in allowed_types:
                raise ValueError(
                    f"Unknown type '{base_type}' for item id '{identifier}'."
                )

        # Additional checks based on spec version (example: require 'label' in >= 1.1)
        naver = _ver_tuple("1.1")
        if current_ver >= naver:
            if "label" not in item:
                raise ValueError(
                    f"Missing 'label' field for inventory item id '{identifier}' "
                    f"(required for spec version {self.spec_version})."
                )

    # If a spec version was deduced from the type strings, update self.spec_version
    if extract_spec_version and deduced_version:
        self.spec_version = deduced_version

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate input types
    if not isinstance(manifest_files, dict):
        raise TypeError("manifest_files must be a dict mapping file names to digests")
    if not isinstance(digests_used, (set, list, tuple)):
        raise TypeError("digests_used must be an iterable of digests")

    # Coerce to sets for easy comparison
    manifest_digests = set()
    for value in manifest_files.values():
        # In case a file maps to multiple digests (e.g. list or set)
        if isinstance(value, (set, list, tuple)):
            manifest_digests.update(item for item in value if isinstance(item, str))
        elif isinstance(value, str):
            manifest_digests.add(value)
        else:
            raise ValueError(f"Unexpected digest type for file '{value}': {type(value)}")

    digests_used_set = set(digests_used)

    # Check for missing digests in the manifest
    missing = digests_used_set - manifest_digests
    if missing:
        raise ValueError(
            "The following digests are used but missing from the manifest: "
            + ", ".join(sorted(missing))
        )

    # Issue warning for digests present in the manifest but not used
    unused = manifest_digests - digests_used_set
    if unused:
        import warnings
        warnings.warn(
            "The following digests are present in the manifest but not used: "
            + ", ".join(sorted(unused)),
            RuntimeWarning,
        )

    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate arguments
    if not hasattr(digests_used, "__contains__"):
        raise TypeError("digests_used must be a set or a container supporting 'in'")
    if not hasattr(manifest_files, "__iter__"):
        raise TypeError("manifest_files must be an iterable")

    for idx, entry in enumerate(manifest_files):
        # Determine how to extract the digest
        if isinstance(entry, dict):
            digest = entry.get("digest", None)
        else:
            try:
                # Assume tuple/list with at least two elements
                digest = entry[1]
            except Exception:
                digest = None

        if digest is None:
            raise ValueError(f"Manifest entry {idx} does not contain a digest")

        if digest not in digests_used:
            raise ValueError(f"Digest '{digest}' from manifest entry {idx} is not in the set of used digests")

    # All required digests are present and used
    return None

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalise inputs
    if manifest_files is None:
        manifest_files = []
    if digests_used is None:
        digests_used = set()
    else:
        try:
            digests_used = set(digests_used)
        except Exception:
            raise TypeError("digests_used must be a collection of digest strings")

    available = set()
    for f in manifest_files:
        # try dict-style access, then attribute access, otherwise ignore
        digest = None
        if isinstance(f, dict):
            digest = f.get('digest')
        else:
            digest = getattr(f, 'digest', None)
        if digest is not None:
            available.add(digest)

    missing = digests_used - available
    unused = available - digests_used

    if missing or unused:
        messages = []
        if missing:
            messages.append(f"Missing digest(s): {', '.join(sorted(missing))}")
        if unused:
            messages.append(f"Unused digest(s): {', '.join(sorted(unused))}")
        raise ValueError("; ".join(messages))

    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}")

    # Ensure necessary attributes exist
    if not hasattr(self, "inventory") or not hasattr(prior, "inventory"):
        raise AttributeError("Both objects must have an 'inventory' attribute")

    # Optional: check that versions are comparable and that self is newer
    if hasattr(self, "version") and hasattr(prior, "version"):
        try:
            if self.version <= prior.version:
                raise ValueError("Current inventory version must be newer than prior")
        except Exception:
            # If the versions cannot be compared, skip the check
            pass

    # Verify that all items in prior's inventory are present in the current inventory
    missing_items = []
    try:
        for item in prior.inventory:
            if item not in self.inventory:
                missing_items.append(item)
    except TypeError as err:
        raise TypeError("prior.inventory must be iterable") from err

    if missing_items:
        raise ValueError(
            f"Prior inventory contains items not present in current inventory: {missing_items}"
        )

    # If all checks pass, return True
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type checking
    if prior is None:
        raise ValueError("Prior inventory must not be None")
    if not isinstance(prior, type(self)):
        raise TypeError(f"Expected prior to be of type {type(self).__name__}, got {type(prior).__name__}")

    # Ensure that the prior object has the attributes we need to compare
    if not hasattr(self, "version") or not hasattr(prior, "version"):
        # If no version attribute present, there's nothing to compare
        return

    # Prior version should be strictly older
    if prior.version >= self.version:
        raise ValueError(f"Prior inventory version ({prior.version}) must be older than current ({self.version})")

    # Compare inventory contents if a components dictionary is present
    self_components = getattr(self, "components", None)
    prior_components = getattr(prior, "components", None)

    if self_components is None or prior_components is None:
        # If components are not defined we consider the validation passed
        return

    # Ensure all components in the current inventory were present in the prior inventory
    for comp_key in self_components:
        if comp_key not in prior_components:
            raise ValueError(f"Component '{comp_key}' is missing from prior inventory")

    # Validate each component's internal prior version logic if available
    for comp_key, comp_obj in self_components.items():
        prior_comp_obj = prior_components.get(comp_key)
        # Many component objects may expose a validate_as_prior_version method
        validate_method = getattr(comp_obj, "validate_as_prior_version", None)
        if callable(validate_method):
            try:
                validate_method(prior_comp_obj)
            except Exception as exc:
                raise ValueError(
                    f"Component '{comp_key}' failed prior‑version validation: {exc}"
                ) from exc

    # If all checks pass, consider validation successful
    return True

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Ensure prior is of correct type
    if not isinstance(prior, InventoryValidator):
        raise TypeError('prior must be an InventoryValidator instance.')

    # Ensure both inventories expose a comparable version attribute
    if not hasattr(self, 'version') or not hasattr(prior, 'version'):
        raise AttributeError('Both inventories must have a "version" attribute.')

    # Compare version numbers (must be lower for prior)
    try:
        if prior.version >= self.version:
            raise ValueError(
                f'Prior version ({prior.version}) must be less than current version ({self.version}).'
            )
    except TypeError:
        raise TypeError('Inventory "version" attributes must be comparable (e.g., int or float).')

    # Optional chronological check if timestamp/date attributes exist
    timestamp_attrs = ('timestamp', 'date', 'generated_time', 'last_updated')
    for attr in timestamp_attrs:
        if hasattr(self, attr) and hasattr(prior, attr):
            self_value = getattr(self, attr)
            prior_value = getattr(prior, attr)
            try:
                if prior_value >= self_value:
                    raise ValueError(
                        f'Prior {attr} ({prior_value}) must be earlier than current {attr} ({self_value}).'
                    )
            except TypeError:
                # Ignore non-comparable types for this check
                pass

    # Optional subset check for items/entries if both inventories define them
    if hasattr(self, 'items') and hasattr(prior, 'items'):
        try:
            if not set(prior.items).issubset(set(self.items)):
                raise ValueError(
                    'Prior inventory contains items not present in the current inventory.'
                )
        except Exception:
            # If items aren't hashable or comparable, skip the check
            pass

    # If all checks passed, prior is considered a valid prior version
    return True

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to data")
    if not isinstance(version, (str, int)):
        raise TypeError("version must be a string or integer")

    # Gather all versions in sorted order for later comparison
    try:
        sorted_versions = sorted(inventory.keys(), key=lambda v: int(v) if isinstance(v, (str, int)) and str(v).isdigit() else v)
    except Exception:
        # Fallback to simple sorting if conversion fails
        sorted_versions = sorted(inventory.keys())

    # Find starting index of the requested version
    try:
        start_index = sorted_versions.index(version)
    except ValueError:
        # Version not present; return empty mapping
        return {}

    # Helper to normalize content files into a set
    def to_set(val):
        if isinstance(val, (list, set, tuple)):
            return set(val)
        if isinstance(val, str):
            return {val}
        # If it's None or empty, return empty set
        if val is None:
            return set()
        # For any other type, try to wrap in a set
        try:
            return {val}
        except Exception:
            return set()

    result = {}

    # Iterate over all relevant logical paths for the requested version and later ones
    for v in sorted_versions[start_index:]:
        data_per_version = inventory.get(v, {})
        if not isinstance(data_per_version, dict):
            continue  # skip malformed entries
        for logic_path, content in data_per_version.items():
            if logic_path not in result:
                result[logic_path] = set()
            result[logic_path].update(to_set(content))

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a mapping of versions to path mappings")
    if version not in inventory:
        raise ValueError(f"Version '{version}' not found in inventory")

    # Prepare result accumulator
    result = {}

    # Sort inventory keys to impose a deterministic order
    try:
        sorted_versions = sorted(inventory.keys())
    except Exception:
        # If the keys cannot be sorted (e.g., mixed types), fall back to the original order
        sorted_versions = list(inventory.keys())

    # Iterate over all versions >= the requested one
    for v in sorted_versions:
        try:
            if v < version:
                continue
        except Exception:
            # Unable to compare this version; skip it
            continue

        mapping = inventory.get(v, {})
        if not isinstance(mapping, dict):
            continue  # skip malformed entries

        for logical_path, content_files in mapping.items():
            # Ensure we have an iterable of content files
            if isinstance(content_files, (set, list, tuple)):
                files_set = set(content_files)
            else:
                # Treat the entry as a single content file
                files_set = {content_files}

            # Merge into the result dict
            if logical_path in result:
                result[logical_path].update(files_set)
            else:
                result[logical_path] = files_set

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may include references to duplicate files in
