    """
    path_map = {}
    try:
        # Inventory is expected to be a mapping from version identifiers
        # to either a mapping of logical_path -> content files or a list of
        # entries containing the mapping information.
        if not isinstance(inventory, dict):
            raise TypeError("inventory must be a mapping of versions to data")

        raw_data = inventory.get(version)
        if raw_data is None:
            # No information for the requested version
            return {}

        # Case 1: raw_data is already a mapping of logical_path -> file(s)
        if isinstance(raw_data, dict):
            for lp, val in raw_data.items():
                if isinstance(val, (list, set, tuple)):
                    # convert to set
                    path_map[lp] = set(val)
                else:
                    # single value
                    path_map[lp] = {val}
            return path_map

        # Case 2: raw_data is a list of entries describing logical paths
        if isinstance(raw_data, list):
            for entry in raw_data:
                # dictionary entry
                if isinstance(entry, dict):
                    lp = entry.get("logical_path") or entry.get("logicalPath") or entry.get("lp")
                    cf = entry.get("content_file") or entry.get("contentFile") or entry.get("cf")
                    if lp is not None:
                        path_map.setdefault(lp, set())
                        if cf is not None:
                            path_map[lp].add(cf)
                # tuple/list entry like (logical_path, content_file)
                elif isinstance(entry, (list, tuple)) and len(entry) == 2:
                    lp, cf = entry
                    path_map.setdefault(lp, set()).add(cf)
            return path_map

        # Other data structures are not supported; return empty mapping
        return {}
    except Exception as exc:
        # Log the exception if a logging facility is available, otherwise
        # raise a runtime error with a clear message.
        raise RuntimeError(f"Failed to construct logical path map for version '{version}': {exc}") from exc

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise TypeError("inventory must be provided and not None")

    # Accept inventory as dict (key->entry) or any iterable of entries
    if isinstance(inventory, dict):
        entries = inventory.values()
    else:
        try:
            iter(inventory)
            entries = inventory
        except TypeError:
            raise TypeError("inventory must be a dict or iterable of entry objects")

    # Determine the set of logical paths that belong to the requested version.
    logical_paths_in_version = set()
    for ent in entries:
        try:
            logical = ent.get('logical_path_in_state') if isinstance(ent, dict) else getattr(ent, 'logical_path_in_state', None)
            ver = ent.get('version') if isinstance(ent, dict) else getattr(ent, 'version', None)
        except Exception:
            # Skip invalid entries
            continue

        if logical is None:
            continue

        # Compare version; allow string/int comparison
        if ver == version:
            logical_paths_in_version.add(logical)

    # Build the mapping for those logical paths, including duplicate content files from later versions
    mapping = {}
    for ent in entries:
        try:
            logical = ent.get('logical_path_in_state') if isinstance(ent, dict) else getattr(ent, 'logical_path_in_state', None)
            content_file = ent.get('content_file') if isinstance(ent, dict) else getattr(ent, 'content_file', None)
        except Exception:
            continue

        if logical in logical_paths_in_version and content_file:
            mapping.setdefault(logical, set()).add(content_file)

    return mapping

def get_logical_path_map(inventory, version):
    """
    Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        return {}
    if version is None:
        raise ValueError("version must be provided")

    path_to_files = {}

    # Helper function to add a file to the mapping
    def _add(path, file):
        if path is not None and file is not None:
            path_to_files.setdefault(path, set()).add(file)

    # First try to treat inventory as a mapping: {logical_path: iterable_of_entries}
    try:
        for logical_path, entries in inventory.items():
            # entries could be a list/tuple of entry objects or dicts
            logical_in_state = False
            for entry in entries:
                try:
                    v = entry["version"] if isinstance(entry, dict) else getattr(entry, "version")
                    f = entry["file"] if isinstance(entry, dict) else getattr(entry, "file")
                except Exception:
                    continue  # skip malformed entry
                if v is None:
                    continue
                if v <= version:
                    logical_in_state = True
                _add(logical_path, f)
            if logical_in_state:
                # ensure the key is present even if no file was added yet
                path_to_files.setdefault(logical_path, set())
    except AttributeError:
        # inventory is not a mapping; treat it as a flat iterable of entries
        for entry in inventory:
            try:
                l = entry["logical_path"] if isinstance(entry, dict) else getattr(entry, "logical_path")
                v = entry["version"] if isinstance(entry, dict) else getattr(entry, "version")
                f = entry["file"] if isinstance(entry, dict) else getattr(entry, "file")
            except Exception:
                continue  # skip malformed entry
            if v is None:
                continue
            if v <= version:
                _add(l, f)
            else:
                # include later version files only if the logical path has already been seen
                if l in path_to_files:
                    _add(l, f)

    return path_to_files

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise TypeError("fixity must be a dictionary")

    # Common structure: expected to have a top-level 'files' list
    if 'files' not in fixity:
        raise ValueError("The fixity block must contain a 'files' key")

    file_entries = fixity['files']
    if not isinstance(file_entries, list):
        raise TypeError("'files' in the fixity block must be a list")

    # Ensure the manifest_files collection is iterable and build a set for efficient look-up
    if manifest_files is None:
        raise ValueError("manifest_files argument cannot be None")
    try:
        manifest_set = set(manifest_files)
    except TypeError:
        raise TypeError("manifest_files must be an iterable of filenames")

    seen = set()
    for entry in file_entries:
        if not isinstance(entry, dict):
            raise TypeError("Each item in 'files' must be a dictionary")

        if 'filename' not in entry or 'hash' not in entry:
            raise ValueError("Each file entry must contain 'filename' and 'hash' fields")

        filename = entry['filename']
        if not isinstance(filename, str):
            raise TypeError("'filename' must be a string")

        # Ensure the file is actually in the manifest
        if filename not in manifest_set:
            raise ValueError(f"Fixity references an unknown file: {filename}")

        # Optional: check that each file appears only once in the fixity block
        if filename in seen:
            raise ValueError(f"Duplicate file reference in fixity block: {filename}")
        seen.add(filename)

    # All checks passed; return True for convenience
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and make sure that only files
        listed in the manifest are referenced.
        """
        # normalise manifest_files to a set of file identifiers
        if isinstance(manifest_files, (list, tuple)):
            manifest_set = set(manifest_files)
        else:
            # assume a single iterable object
            try:
                manifest_set = set(manifest_files)
            except TypeError:
                raise TypeError(
                    "manifest_files must be an iterable of file identifiers"
                )

        # The fixity block should be a sequence (list/tuple) of dict-like items
        if not isinstance(fixity, (list, tuple)):
            raise TypeError(
                f"fixity must be a list or tuple, got {type(fixity).__name__}"
            )

        seen_files = set()
        for idx, entry in enumerate(fixity):
            if not isinstance(entry, dict):
                raise TypeError(
                    f"Each fixity entry must be a dict, entry {idx} is {type(entry).__name__}"
                )

            # Basic structural checks
            if "file" not in entry:
                raise ValueError(f"Fixity entry {idx} missing required key 'file'")
            file_name = entry["file"]
            if not isinstance(file_name, str):
                raise TypeError(f"File name in entry {idx} must be a string")

            if "checksum" not in entry:
                raise ValueError(
                    f"Fixity entry {idx} missing required key 'checksum'"
                )
            checksum = entry["checksum"]
            if not isinstance(checksum, str):
                raise TypeError(f"Checksum in entry {idx} must be a string")

            # Ensure the file is actually referenced in the manifest
            if file_name not in manifest_set:
                raise ValueError(
                    f"File '{file_name}' in fixity entry {idx} not present in the manifest"
                )

            # Guard against duplicate entries
            if file_name in seen_files:
                raise ValueError(
                    f"Duplicate file reference '{file_name}' found in fixity block at entry {idx}"
                )
            seen_files.add(file_name)

        # If we made it here the block is valid
        return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Nothing to validate
    if not fixity:
        return True

    # The fixity block should be a mapping of file paths to metadata
    if not isinstance(fixity, dict):
        raise TypeError('fixity must be a dict mapping file paths to metadata')

    # Define a minimal set of required keys in each file's metadata.
    # You can extend this set if the inventory definition requires more.
    required_keys = {'checksum'}

    for file_path, meta in fixity.items():
        if file_path not in manifest_files:
            raise ValueError(f'File "{file_path}" referenced in fixity is not listed in the manifest')

        if not isinstance(meta, dict):
            raise TypeError(f'Metadata for file "{file_path}" must be a dict')

        missing = required_keys - meta.keys()
        if missing:
            raise ValueError(f'File "{file_path}" metadata is missing required keys: {missing}')

    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and make sure that only files
    listed in the manifest are referenced.
    """
    # If there is no fixity information, nothing to validate.
    if not fixity:
        return True

    # List of keys that are allowed in an individual fixity entry.
    allowed_keys = {"file", "checksum", "algo", "algorithm"}

    # Helper to check that referenced file exists in the manifest.
    def _check_file(file_name):
        if file_name not in manifest_files:
            raise ValueError(
                f"Fixity references unknown file '{file_name}'. "
                f"Only files listed in the manifest are allowed."
            )

    # If the fixity block is a dictionary: two common formats are
    #   1. { 'filename': 'checksum' }
    #   2. { 'filename': { 'file': 'filename', 'checksum': '...', ... } }
    if isinstance(fixity, dict):
        for key, value in fixity.items():
            _check_file(key)
            if isinstance(value, dict):
                # Validate dict structure
                if "file" not in value or "checksum" not in value:
                    raise ValueError(
                        f"Dictionary entry for file '{key}' must contain "
                        f"both 'file' and 'checksum' keys."
                    )
                if value["file"] != key:
                    raise ValueError(
                        f"Dictionary entry for file '{key}' contains "
                        f"mismatched 'file' key value '{value['file']}'."
                    )
                for k in value:
                    if k not in allowed_keys:
                        raise ValueError(
                            f"Unexpected key '{k}' in fixity entry for file '{key}'."
                        )
            else:
                # Treat as a simple checksum string.
                if not isinstance(value, str) or not value:
                    raise ValueError(
                        f"Checksum value for file '{key}' must be a non‑empty string."
                    )
        return True

    # If the fixity block is an iterable of dictionaries.
    if isinstance(fixity, (list, tuple)):
        for entry in fixity:
            if not isinstance(entry, dict):
                raise ValueError(
                    f"Each fixity entry must be a dict, found {type(entry)}."
                )
            if "file" not in entry or "checksum" not in entry:
                raise ValueError(
                    f"Fixity entry {entry} missing required 'file' or 'checksum' key."
                )
            _check_file(entry["file"])
            for k in entry:
                if k not in allowed_keys:
                    raise ValueError(
                        f"Unexpected key '{k}' in fixity entry for file '{entry['file']}'."
                    )
        return True

    # If we reach this point the structure is unsupported.
    raise ValueError(
        f"Fixity block must be a dict or list of dicts, got {type(fixity)}."
    )

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Nothing to validate if the block is empty or None
    if not fixity:
        return True

    # Prepare a set of valid file identifiers from the manifest
    allowed_files = set(manifest_files or [])

    # Case 1: a dict mapping file identifiers to their checksums
    if isinstance(fixity, dict):
        for file_path, checksum in fixity.items():
            if file_path not in allowed_files:
                raise ValueError(
                    f"File '{file_path}' referenced in fixity is not present in the manifest."
                )
            if not isinstance(checksum, (str, bytes)):
                raise ValueError(
                    f"Checksum for file '{file_path}' must be a string or bytes."
                )
        return True

    # Case 2: a list of entries (each entry may be a dict or a 2‑tuple/list)
    if isinstance(fixity, list):
        for entry in fixity:
            if isinstance(entry, dict):
                file_path = entry.get("file") or entry.get("filename")
                checksum = entry.get("checksum")
                if file_path is None or checksum is None:
                    raise ValueError(
                        f"Fixity entry must contain 'file'/'filename' and 'checksum': {entry!r}"
                    )
            elif isinstance(entry, (tuple, list)) and len(entry) == 2:
                file_path, checksum = entry
            else:
                raise ValueError(f"Invalid fixity entry type: {entry!r}")

            if file_path not in allowed_files:
                raise ValueError(
                    f"File '{file_path}' referenced in fixity is not present in the manifest."
                )
            if not isinstance(checksum, (str, bytes)):
                raise ValueError(
                    f"Checksum for file '{file_path}' must be a string or bytes."
                )
        return True

    # If we get here, the structure is unknown
    raise TypeError("Fixity block must be a dict or a list of entries.")

def files_list(path):
    """Return the files in ``path``."""
    import os
    from pathlib import Path
    p = Path(path)
    if not p.exists():
        raise FileNotFoundError(f"Path does not exist: {path}")
    try:
        if p.is_file():
            return [str(p.resolve())]
        if p.is_dir():
            return [str(f.resolve()) for f in p.iterdir() if f.is_file()]
        # For other types (symlinks, etc.) treat as file if it refers to a file
        if p.is_symlink() and Path(os.readlink(p)).exists():
            target = Path(os.readlink(p))
            if target.is_file():
                return [str(target.resolve())]
            if target.is_dir():
                return [str(f.resolve()) for f in target.iterdir() if f.is_file()]
    except OSError as exc:
        raise RuntimeError(f"Error accessing path '{path}': {exc}") from exc
    return []

