def _group_files_by_xml_filename(source, xmls, files):
    """
    Group files by their XML basename

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    source : str
        Directory or base path to join with filenames if they are relative.
    xmls : list of str
        List of XML file paths (full or relative).
    files : list of str
        List of files in the folder or zipfile (full or relative).

    Returns
    -------
    dict
        key: name of the XML file (basename without extension)
        value: list of file paths that belong to that XML file
    """
    import os

    # Validate input types
    if not isinstance(source, str):
        raise TypeError("source must be a string")
    if not hasattr(xmls, "__iter__") or isinstance(xmls, (str, bytes)):
        raise TypeError("xmls must be a list or iterable of strings")
    if not hasattr(files, "__iter__") or isinstance(files, (str, bytes)):
        raise TypeError("files must be a list or iterable of strings")

    # Normalize source path
    source = os.path.abspath(source) if source else ""

    # Build a mapping from XML base name to list of files
    result = {}

    # Preprocess xmls: compute base names and ensure uniqueness
    xml_bases = {}
    for xml_path in xmls:
        try:
            xml_base = os.path.splitext(os.path.basename(xml_path))[0]
        except Exception:
            continue
        if xml_base in xml_bases:
            raise ValueError(f"Duplicate XML base name detected: {xml_base}")
        xml_bases[xml_base] = xml_path
        result[xml_base] = []

    # Helper to normalize file path
    def normalize_path(p):
        if source and not os.path.isabs(p):
            return os.path.normpath(os.path.join(source, p))
        return os.path.normpath(p)

    # Iterate over all files and associate them with their XML base
    for file_path in files:
        try:
            file_base = os.path.splitext(os.path.basename(file_path))[0]
        except Exception:
            continue
        if file_base in result:
            full_path = normalize_path(file_path)
            result[file_base].append(full_path)

    return result

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package

    Returns
    -------
    dict
    """
    import os

    # Validate input
    if not isinstance(folder, (str, bytes)):
        raise TypeError(f"folder must be a string path, got {type(folder).__name__}")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder does not exist or is not a directory: {folder}")

    # First, collect all XML basenames in the folder (recursively)
    xml_basenames = set()
    for root, _, files in os.walk(folder):
        for name in files:
            if name.lower().endswith(".xml"):
                base, _ = os.path.splitext(name)
                xml_basenames.add(base)

    # If no XML files found, return an empty dict
    if not xml_basenames:
        return {}

    # Now group all files that share an XML basename
    grouped_data = {}
    for root, _, files in os.walk(folder):
        for name in files:
            base, _ = os.path.splitext(name)
            if base in xml_basenames:
                full_path = os.path.join(root, name)
                # Use relative path for consistency
                rel_path = os.path.relpath(full_path, folder)
                grouped_data.setdefault(base, []).append(rel_path)

    return grouped_data

def _eval_file(prefix, file_path):
    """
    Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    filename : str
        filename
    file_folder : str
        file folder

    Returns
    -------
    dict
    """
    import os
    from pathlib import Path

    # normalize prefix (ensure it doesn't contain extension)
    if prefix is not None:
        prefix = os.path.splitext(os.path.basename(prefix))[0]
    else:
        prefix = ""

    result = {}

    try:
        path = Path(file_path)
        if not path.is_file():
            raise FileNotFoundError(f"File not found: {file_path}")

        # Determine file type by extension and quick content inspection
        ext = path.suffix.lower()
        lower_ext = ext.replace(".", "")
        file_type = None

        # Use heuristics based on common extensions and content markers
        if lower_ext in ["m3u8", "playlist", "xml", "json"]:
            with path.open("r", encoding="utf-8", errors="ignore") as f:
                sample = f.read(8192).lower()
                if "<rendition>" in sample or "streamid" in sample or "m3u8" in sample:
                    file_type = "rendition"
                elif "<asset>" in sample or "duration" in sample:
                    file_type = "asset"
                else:
                    file_type = "rendition" if lower_ext == "m3u8" else "asset"
        elif lower_ext in ["mp4", "avi", "mkv", "mov", "wmv", "flv", "jpg", "png", "gif"]:
            file_type = "asset"
        else:
            # fallback if unknown extension
            file_type = "asset"

        # Update global packages dict if present
        try:
            globals()
            if "packages" in globals() and isinstance(globals()["packages"], dict):
                globals()["packages"][prefix] = {"type": file_type, "url": str(path.resolve())}
        except Exception:
            # silently ignore if packages not defined
            pass

        result = {
            "prefix": prefix,
            "type": file_type,
            "url": str(path.resolve())
        }

    except Exception as exc:
        # Return dict containing error message for debugging
        result = {"prefix": prefix, "error": str(exc)}

    return result

