def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import os
    import zipfile

    if not isinstance(zip_path, str):
        raise TypeError(f"zip_path must be a string, got {type(zip_path).__name__}")
    if not os.path.isfile(zip_path):
        raise FileNotFoundError(f"zip file does not exist: {zip_path}")

    groups = {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as z:
            for info in z.infolist():
                if info.is_dir():
                    continue
                filepath = info.filename
                if not filepath.lower().endswith('.xml'):
                    continue
                basename = os.path.splitext(os.path.basename(filepath))[0]
                try:
                    content_bytes = z.read(info)
                except Exception:
                    # If reading fails for some reason, skip this file
                    continue
                try:
                    content = content_bytes.decode('utf-8')
                except Exception:
                    content = content_bytes.decode('utf-8', errors='replace')
                groups.setdefault(basename, []).append(content)
    except zipfile.BadZipFile as e:
        raise zipfile.BadZipFile(f"cannot read zip file: {zip_path}") from e

    return groups

def _explore_zipfile(zip_path):
    """
    Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    import zipfile
    import os

    if not isinstance(zip_path, (str, bytes)):
        raise TypeError("zip_path must be a string or bytes path")
    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    data = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            for name in zf.namelist():
                if not isinstance(name, str):
                    continue
                if not name.lower().endswith('.xml'):
                    continue
                # get basename without extension
                base_name = name.rsplit('/', 1)[-1]
                if '.' in base_name:
                    base_name = base_name.rsplit('.', 1)[0]
                try:
                    content = zf.read(name)
                except RuntimeError:
                    # skip files that cannot be read
                    continue
                data.setdefault(base_name, []).append(content)
    except zipfile.BadZipFile as exc:
        raise ValueError(f"Invalid zip file: {zip_path}") from exc
    return data

def files_list_from_zipfile(zip_path):
    """
    Return the files in `zip_path`

    Example:

    ```
    [
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200069.pdf',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200069.xml',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071.pdf',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071.xml',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf01.tif',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf02.tif',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf03.tif',
        '2318-0889-tinf-33-0421/2318-0889-tinf-33-e200071-gf04.tif',
    ]
    ```
    """
    import os
    import zipfile

    # Validate path-like input
    if not isinstance(zip_path, (str, bytes, os.PathLike)):
        raise TypeError(f"zip_path must be a path-like object or string, got {type(zip_path).__name__}")

    # Convert PathLike to string
    try:
        zip_path = os.fspath(zip_path)
    except Exception as exc:
        raise TypeError(f"Cannot convert zip_path to a path string: {exc}") from exc

    if not os.path.exists(zip_path):
        raise FileNotFoundError(f"Zip file not found: {zip_path}")

    try:
        with zipfile.ZipFile(zip_path, "r") as zf:
            # Use is_dir if available (Python ≥ 3.6), otherwise fall back to trailing slash
            files = [
                info.filename
                for info in zf.infolist()
                if not (hasattr(info, "is_dir") and info.is_dir()) and not info.filename.endswith("/")
            ]
    except zipfile.BadZipFile as exc:
        raise zipfile.BadZipFile(f"Invalid or corrupted zip file: {zip_path}") from exc
    except Exception as exc:
        # Catch any other exception that might arise from opening or reading the zip file
        raise RuntimeError(f"Unexpected error reading zip file {zip_path}: {exc}") from exc

    return sorted(files)

