def fix_namespace_prefix_w(content):
    """
    Convert textos cujo padrão é `w:st="` em `w-st="`.

    Parameters
    ----------
    content : str or bytes
        The text content or byte string to be processed.

    Returns
    -------
    str or bytes
        The processed text with the prefix replaced.
    """
    if isinstance(content, bytes):
        try:
            text = content.decode('utf-8')
        except Exception as exc:
            raise ValueError('content bytes could not be decoded as UTF-8') from exc
        new_text = text.replace('w:st="', 'w-st="')
        return new_text.encode('utf-8')
    if not isinstance(content, str):
        raise TypeError('content must be a str or bytes instance')
    return content.replace('w:st="', 'w-st="')

