    """
    # Normalizar em lista caso receba apenas uma string
    if not isinstance(pubdate_xpaths, (list, tuple)):
        pubdate_xpaths = [pubdate_xpaths]

    # Tentar cada expressão XPath na ordem dada
    for expr in pubdate_xpaths:
        try:
            # xml.etree.ElementTree e lxml suportam xpath na mesma sintaxe básica
            result = node.xpath(expr) if hasattr(node, "xpath") else None
            if result:
                # retornar o primeiro item, mas converter de forma segura para string
                return str(result[0])
        except Exception:
