            continue

    # Nenhum xpath encontrou nada
    return None

def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    # Get text content from the issue element
    try:
        text = str(issue).strip()
    except Exception:
        return None, None

    # If the element has an attribute `text`, use it
    try:
        if hasattr(issue, "text") and issue.text:
            text = issue.text.strip()
    except Exception:
        pass

    if not text:
        return None, None

    import re

    # Normalize punctuation
    clean_text = re.sub(r'[\.,\(\)]', ' ', text.lower())
    tokens = [t for t in clean_text.split() if t]
    if not tokens:
        return None, None

    sup_words = {
        'suppl', 'sup', 'supp', 'suppl.', 'supp.',
        'spe', 'spe.', 'spepr', 'spe pr', 'spe. pr', 'spepr.',
        'pr', 'pr.', 'prr', 'pr. r', 'pr r', 'pr. r.'
    }

    number = None
    suppl = None
    sup_indicator_present = False

    for token in tokens:
        # Handle tokens like 's2', 'supp5', 'suppl12', etc.
        m = re.match(r'^([a-z]+)(\d+)$', token)
        if m:
            letter, num = m.groups()
            if letter in sup_words:
                # token itself indicates supplement
                if number is None:
                    number = num
                else:
                    suppl = num
                sup_indicator_present = True
            else:
                # unrecognized prefix, treat num as number
                if number is None:
                    number = num
                else:
                    suppl = num
            continue

        # Handle pure numeric or hyphenated numeric tokens
        if re.fullmatch(r'\d+(-\d+)?', token):
            if number is None:
                number = token
            else:
                suppl = token
            continue

        # If token matches one of the known supplement words
        if token in sup_words:
            sup_indicator_present = True
            continue

        # For tokens that contain punctuation that has been removed
        # e.g., 'suppl.pr' becomes 'suppl pr' after clean_text
        # We already cleaned punctuation, so we treat them as sup_indicator
        if any(sub in token for sub in sup_words):
            sup_indicator_present = True
            continue

    # Convert numeric strings to int/keep string for ranges
    def to_int_or_keep(value):
        if value is None:
            return None
        # Preserve ranges like '2-5'
        if '-' in value:
            return value
        try:
            return int(value)
        except ValueError:
            return value

    number = to_int_or_keep(number)
    suppl = to_int_or_keep(suppl)

    return number, suppl

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = '  ' * indent

    def _convert(obj, lvl):
        # Recursively convert objects to string
        if hasattr(obj, 'pretty') and callable(getattr(obj, 'pretty')):
            return obj.pretty(lvl, debug=debug)
        if isinstance(obj, dict):
            return '{' + ', '.join(f'{k}: {_convert(v, lvl)}' for k, v in obj.items()) + '}'
        if isinstance(obj, (list, tuple, set)):
            return '[' + ', '.join(_convert(item, lvl) for item in obj) + ']'
        return repr(obj)

    parts = []
    for key, value in self.__dict__.items():
        parts.append(f'{key}={_convert(value, indent + 1)}')
    return f'{indent_str}{self.__class__.__name__}({", ".join(parts)})'

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    parts = []
    ind = ' ' * indent

    # Start with the class name
    parts.append(f"{ind}{self.__class__.__name__}(")

    # Include attributes if the object provides any
    attrs = None
    if hasattr(self, 'attributes'):
        attrs = self.attributes
    elif hasattr(self, 'attrib'):
        attrs = self.attrib
    elif hasattr(self, 'attribs'):
        attrs = self.attribs

    if attrs:
        for k, v in attrs.items():
            parts.append(f"{ind}  {k}={v!r},")

    # Handle child elements
    children = []
    if hasattr(self, 'children'):
        children = self.children
    else:
        try:
            children = list(self)
        except TypeError:
            # Not iterable
            children = []

    for child in children:
        if hasattr(child, 'pretty'):
            parts.append(child.pretty(indent + 2, debug))
        else:
            # Fallback to repr if pretty is not available
            parts.append(f"{ind}  {repr(child)}")

    # Close the representation
    parts.append(f"{ind})")

    return '\n'.join(parts)

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    prefix = '  ' * indent
    # Gather attributes from the instance dictionary, excluding children
    attr_parts = []
    for k, v in getattr(self, '__dict__', {}).items():
        if k == 'children':
            continue
        if v is None:
            continue
        attr_parts.append(f'{k}="{v}"')
    attr_str = ' ' + ' '.join(attr_parts) if attr_parts else ''
    open_tag = f'{prefix}<{self.__class__.__name__}{attr_str}>'
    # Handle debug mode
    if debug:
        id_val = getattr(self, 'id', None)
        debug_info = f'  # [debug] class={self.__class__.__name__}'
        if id_val is not None:
            debug_info += f', id={id_val}'
        open_tag += debug_info
    # Try to collect children
    children = None
    try:
        children = list(self)
    except TypeError:
        if hasattr(self, 'children'):
            children = getattr(self, 'children')
    # If children exist, recursively pretty them
    if children:
        lines = [open_tag]
        for child in children:
            if hasattr(child, 'pretty') and callable(child.pretty):
                lines.append(child.pretty(indent + 1, debug))
            else:
                lines.append(f'{prefix}  {repr(child)}')
        lines.append(f'{prefix}</{self.__class__.__name__}>')
        return '\n'.join(lines)
    # No children: self-closing tag
    return f'{prefix}<{self.__class__.__name__}{attr_str} />'

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    indent_str = '  ' * indent
    lines = []

    if debug:
        lines.append(f"{indent_str}[DEBUG] {self.__class__.__name__} object at {hex(id(self))}")

    # collect attributes (excluding private and callable)
    attrs = []
    for key, val in getattr(self, "__dict__", {}).items():
        if key.startswith("_"):
            continue
        if callable(val):
            continue
        if isinstance(val, (list, tuple)):
            continue
        if val is None:
            continue
        try:
            attrs.append(f'{key}="{val}"')
        except Exception:
            continue

    start_tag = f"{indent_str}<{self.__class__.__name__}"
    if attrs:
        start_tag += ' ' + ' '.join(attrs)
    start_tag += ">"
    lines.append(start_tag)

    # recurse into children
    for key, val in getattr(self, "__dict__", {}).items():
        if isinstance(val, (list, tuple)):
            for child in val:
                if hasattr(child, "pretty") and callable(child.pretty):
                    lines.append(child.pretty(indent + 1, debug))
                else:
                    lines.append(f"{indent_str}  {repr(child)}")
        else:
            if hasattr(val, "pretty") and callable(val.pretty):
                lines.append(val.pretty(indent + 1, debug))
            elif val is not None:
                lines.append(f"{indent_str}  {repr(val)}")

    lines.append(f"{indent_str}</{self.__class__.__name__}>")
    return "\n".join(lines)

def pretty(self, indent=0, debug=False):
    """Return a pretty formatted representation of self."""
    try:
        indent = int(indent)
    except Exception:
        indent = 0
    prefix = '    ' * indent
    # Build attribute string from instance dictionary, ignoring private, methods and None
    attrs = []
    if hasattr(self, '__dict__'):
        for k, v in self.__dict__.items():
            if k.startswith('_') or callable(v) or v is None:
                continue
            # Escape quotes in value for safety
            escaped_val = str(v).replace('"', '&quot;')
            attrs.append(f'{k}="{escaped_val}"')
    attr_str = ''
    if attrs:
        attr_str = ' ' + ' '.join(attrs)
    # Determine children (iterable); if object is a leaf, nothing to format
    try:
        children = list(self)
    except Exception:
        children = []
    if not children:
        # Self-closing tag or simple text node
        if debug:
            return f'{prefix}<{self.__class__.__name__}{attr_str} (debug) />'
        else:
            return f'{prefix}<{self.__class__.__name__}{attr_str} />'
    else:
        lines = [f'{prefix}<{self.__class__.__name__}{attr_str}>']
        for child in children:
            if hasattr(child, 'pretty'):
                lines.append(child.pretty(indent + 1, debug))
            else:
                # Treat any non-element as text
                child_str = str(child).replace('\n', f'\n{"    " * (indent + 1)}')
                lines.append('    ' * (indent + 1) + child_str)
        lines.append(f'{prefix}</{self.__class__.__name__}>')
        return '\n'.join(lines)

