def get_versions():
    """
    Get version information or return default if unable to do so.

    Returns:
        dict: Dictionary containing at least the key 'version'. Additional
        keys may appear when available. In cases where the version cannot be
        determined, the dictionary will contain a key 'error' with a short
        description of the failure.
    """
    import os
    # Attempt to get importlib.metadata for retrieving distribution version
    try:
        # Python 3.8+
        from importlib.metadata import version, PackageNotFoundError
    except Exception:
        try:
            # backport for older Python versions
            from importlib_metadata import version, PackageNotFoundError  # type: ignore
        except Exception:
            # No metadata support available
            return {"version": "0.0.0", "error": "importlib.metadata not available"}

    # Try to infer the distribution name from the module's package
    dist_name = None
    try:
        if __package__:
            dist_name = __package__.split('.')[0]
    except Exception:
        dist_name = None

    # If a distribution name is known, attempt to get its version
    if dist_name:
        try:
            dist_version = version(dist_name)
            return {"version": dist_version}
        except PackageNotFoundError:
            # Distribution not found – proceed to fallback methods
            pass
        except Exception as exc:
            # Any other exception: fall back to a default
            return {"version": "0.0.0", "error": str(exc)}

    # Fallback #1: look for a VERSION file in common parent directories
    for potential_root in (".", "..", "../.."):
        version_path = os.path.join(potential_root, "VERSION")
        try:
            with open(version_path, "r", encoding="utf-8") as vf:
                ver_text = vf.read().strip()
                if ver_text:
                    return {"version": ver_text}
        except FileNotFoundError:
            continue
        except Exception as exc:
            # Unexpected error while reading VERSION file
            return {"version": "0.0.0", "error": f"Error reading {version_path}: {exc}"}

    # Fallback #2: encode that no version could be determined
    return {"version": "0.0.0", "error": "unable to determine package version"}

