    def _to_str(obj):
        """Convert an object to its string representation, handling None."""
        return "" if obj is None else str(obj)

    # Helper for HTML escaping
    def _html_escape(text):
        """Escape &, <, >, \" and convert newlines to <br>."""
        return (
            text
            .replace("&", "&amp;")
            .replace("<", "&lt;")
            .replace(">", "&gt;")
            .replace('"', "&quot;")
            .replace("'", "&#x27;")
            .replace("\n", "<br>")
        )

    try:
        if style.lower() == 'plain':
            # Simple concatenation
            return "".join(_to_str(p) for p in iterator)

        elif style.lower() == 'html':
            # Escape and join
            return "".join(_html_escape(_to_str(p)) for p in iterator)

        elif style.lower() == 'json':
            import json
            # Return JSON array of string representations
            return json.dumps([_to_str(p) for p in iterator])

        elif style.lower() == 'xml':
            # Wrap each piece in <piece> tags and combine
            pieces_xml = []
            for p in iterator:
                content = _to_str(p)
                # Escape content for XML
                escaped = content.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                pieces_xml.append(f"<piece>{escaped}</piece>")
            return "".join(pieces_xml)

        else:
            raise ValueError(f"Unsupported rendering style: {style}")

    except Exception as exc:
        raise RuntimeError(f"Error rendering pieces with style '{style}': {exc}") from exc

