def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, shlex, os

    # Merge provided environment with the current environment if env is specified
    if env is not None:
        env = {**os.environ, **env}

    # Prepare arguments for subprocess.run
    if isinstance(commands, list):
        # Ensure every element is a string
        cmd = [str(c) for c in commands]
        if args:
            if isinstance(args, (list, tuple)):
                cmd.extend(str(a) for a in args)
            else:
                cmd.append(str(args))
        run_kwargs = {
            "cwd": cwd,
            "env": env,
            "stdout": subprocess.PIPE,
            "stderr": subprocess.PIPE,
            "text": True,
            "check": True,
        }
        proc = subprocess.run(cmd, **run_kwargs)
    else:
        # Treat commands as a string; optionally append args
        cmd_str = str(commands)
        if args:
            if isinstance(args, (list, tuple)):
                arg_parts = [shlex.quote(str(a)) for a in args]
                cmd_str += " " + " ".join(arg_parts)
            else:
                cmd_str += " " + shlex.quote(str(args))
        run_kwargs = {
            "shell": True,
            "cwd": cwd,
            "env": env,
            "stdout": subprocess.PIPE,
            "stderr": subprocess.PIPE,
            "text": True,
            "check": True,
        }
        proc = subprocess.run(cmd_str, **run_kwargs)

    if verbose:
        # Print command and results; hide stderr if requested
        exec_cmd = proc.args if isinstance(proc.args, str) else " ".join(proc.args)
        print(f"Command: {exec_cmd}")
        print(f"Return code: {proc.returncode}")
        print(f"Stdout:\n{proc.stdout}")
        if not hide_stderr:
            print(f"Stderr:\n{proc.stderr}")

    # If hide_stderr is True, discard stderr before raising exceptions
    if hide_stderr:
        proc.stderr = ""

    return proc.stdout, proc.stderr, proc.returncode

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS.

    Parameters
    ----------
    vcs : str
        Name or identifier of the version control system.
    method : callable, optional
        If provided, the handler function to register.
        If omitted, `register_vcs_handler` returns a decorator.
    """
    if method is None:
        def decorator(func):
            return _register_vcs_handler(vcs, func)
        return decorator
    return _register_vcs_handler(vcs, method)

def register_vcs_handler(vcs, method):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str):
        raise TypeError("vcs must be a string")
    if not callable(method):
        raise TypeError("method must be callable")

    # Retrieve the global registry; create if it doesn't exist
    registry = globals().setdefault('_VCS_HANDLERS', {})

    if vcs in registry:
        # If a handler for this VCS is already registered, raise an error
        raise ValueError(f"A handler for vcs '{vcs}' has already been registered.")

    registry[vcs] = method
    return method

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    stack = [self]
    while stack:
        obj = stack.pop()
        num_objects += 1

        ok = True

        # Validate object if requested
        if validate_objects:
            try:
                if hasattr(obj, 'validate'):
                    # Assume validate raises if object is invalid
                    obj.validate()
                elif getattr(obj, 'isValid', None) is not None:
                    ok = bool(obj.isValid())
            except Exception as e:
                ok = False
                if show_warnings:
                    msg = f"Warning: Validation failed for {type(obj).__name__}"
                    if getattr(obj, 'id', None):
                        msg += f" (id={obj.id})"
                    msg += f": {e}"
                    print(msg)

        # Check digest if requested
        if check_digests:
            try:
                digest_ok = True
                if hasattr(obj, 'check_digest'):
                    digest_ok = obj.check_digest()
                elif hasattr(obj, 'digest') and hasattr(obj, 'content'):
                    import hashlib
                    h = hashlib.sha256()
                    # assume content is string; otherwise encode appropriately
                    content = obj.content
                    if isinstance(content, str):
                        content = content.encode('utf-8')
                    h.update(content)
                    digest_ok = (h.hexdigest() == obj.digest)
                if not digest_ok:
                    ok = False
                    if show_warnings:
                        msg = f"Warning: Digest mismatch for {type(obj).__name__}"
                        if getattr(obj, 'id', None):
                            msg += f" (id={obj.id})"
                        print(msg)
            except Exception as e:
                ok = False
                if show_warnings:
                    msg = f"Warning: Digest check failed for {type(obj).__name__}"
                    if getattr(obj, 'id', None):
                        msg += f" (id={obj.id})"
                    msg += f": {e}"
                    print(msg)

        if ok:
            good_objects += 1

        # Gather children
        children = []
        try:
            children = list(obj)
        except Exception:
            if hasattr(obj, 'children'):
                try:
                    children = list(obj.children)
                except Exception:
                    pass
            elif hasattr(obj, 'elements'):
                try:
                    children = list(obj.elements)
                except Exception:
                    pass
        stack.extend(children)

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
