    """
    num_objects = 0
    good_objects = 0

    def _traverse(node):
        """Recursively yield all descendants of node, including node itself."""
        yield node
        try:
            for child in node:
                yield from _traverse(child)
        except TypeError:
            # node is not iterable
            return

