    if not isinstance(show_warnings, bool):
        raise TypeError("show_warnings must be a boolean")

    # Determine how to iterate over the hierarchy
    if hasattr(self, '__iter__'):
        iterable = self
    elif hasattr(self, 'children'):
        iterable = getattr(self, 'children')
    else:
        raise RuntimeError("The storage root does not provide an iterable over its child objects")

    num_objects = 0
    good_objects = 0

    for obj in iterable:
