                        )
            except Exception as e:
                is_ok = False
                if show_warnings:
                    warnings.warn(
                        f"Validation failed for object {obj!r}: {e}"
                    )

        # Check the digest if required
        if check_digests:
            try:
                if hasattr(obj, 'digest'):
                    stored = getattr(obj, 'stored_digest', None)
                    if obj.digest() != stored:
                        is_ok = False
                else:
                    if show_warnings:
                        warnings.warn(
                            f"Object {obj!r} has no digest() method."
                        )
            except Exception as e:
                is_ok = False
                if show_warnings:
