def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import warnings
    num_objects = 0
    good_objects = 0

    def _recurse(elem):
        nonlocal num_objects, good_objects
        num_objects += 1
        is_good = True

        if validate_objects:
            try:
                if hasattr(elem, "validate"):
                    res = elem.validate()
                    if not res:
                        is_good = False
            except Exception as exc:
                is_good = False
                if show_warnings:
                    warnings.warn(f"validate() raised {exc!s} on {elem}")

        if check_digests:
            try:
                if hasattr(elem, "check_digest"):
                    res = elem.check_digest()
                    if not res:
                        is_good = False
            except Exception as exc:
                is_good = False
                if show_warnings:
                    warnings.warn(f"check_digest() raised {exc!s} on {elem}")

        if is_good:
            good_objects += 1
        elif show_warnings:
            warnings.warn(f"Element {elem!r} failed validation checks")

        # Recurse into children if possible
        try:
            for child in elem:
                _recurse(child)
        except TypeError:
            # element not iterable; nothing to recurse into
            pass

    _recurse(self)
    return num_objects, good_objects

