                    warnings.append(f"Validation error for {obj!r}: {e}")

        # Digest validation
        if check_digests and hasattr(obj, 'validate_digest'):
            try:
                if not obj.validate_digest():
                    valid = False
                    if show_warnings:
                        warnings.append(f"Digest mismatch for {obj!r}")
            except Exception as e:
                valid = False
                if show_warnings:
                    warnings.append(f"Digest check error for {obj!r}: {e}")

        if valid:
            good_objects += 1

        # Recursively validate children
        for child in getattr(obj, '__iter__', lambda: [])():
            if child is None:
                continue
            _validate(child)

    _validate(self)

    if show_warnings and warnings:
        for w in warnings:
            print("WARNING:", w)

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    from pathlib import Path

    # --- Validate configuration ------------------------------------
    root_attr = getattr(self, "root", None)
    if root_attr is None:
        raise AttributeError("Instance has no 'root' attribute to designate the OCFL storage root")

    root_path = Path(root_attr).expanduser().resolve()
    if not root_path:
        raise ValueError(f"Invalid root path: {root_attr}")

    # --- Create root directory ------------------------------------
    try:
        root_path.mkdir(parents=True, exist_ok=False)
    except FileExistsError:
        raise FileExistsError(f"OCFL storage root already exists at {root_path}") from None
    except OSError as exc:
        raise OSError(f"Could not create root directory '{root_path}': {exc}") from exc

    # --- Create mandatory subdirectories --------------------------
    try:
        (root_path / "objects").mkdir(exist_ok=False)
        (root_path / "objects" / "shipments").mkdir(exist_ok=False)
    except OSError as exc:
        raise OSError(f"Failed to create required OCFL directories under '{root_path}': {exc}") from exc

    # --- Create placeholder metadata files -----------------------
    try:
        (root_path / "manifest.json").write_text("{}\n", encoding="utf-8")
        (root_path / "objects" / "catalog.json").write_text("{}\n", encoding="utf-8")
    except OSError as exc:
        raise OSError(f"Failed to create metadata files under '{root_path}': {exc}") from exc

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    import json
    import uuid
    import datetime

    if not hasattr(self, 'root'):
        raise AttributeError("Root path must be set before initialization.")
    root_path = self.root

    # create root directory
    try:
        os.makedirs(root_path, exist_ok=True)
    except OSError as e:
        raise RuntimeError(f"Failed to create root directory at {root_path}: {e}") from e

    # required sub‑directories
    subdirs = ['objects', 'storage', 'metadata']
    for sub in subdirs:
        sub_path = os.path.join(root_path, sub)
        try:
            os.makedirs(sub_path, exist_ok=True)
        except OSError as e:
            raise RuntimeError(f"Failed to create subdirectory '{sub}' in {root_path}: {e}") from e

    # initial metadata file
    meta_path = os.path.join(root_path, 'metadata', 'info.json')
    if not os.path.exists(meta_path):
        meta = {
            'root_id': str(uuid.uuid4()),
            'created': datetime.datetime.utcnow().isoformat() + 'Z',
            'version': '1.0'
        }
        try:
            with open(meta_path, 'w', encoding='utf-8') as f:
                json.dump(meta, f, indent=4)
        except (OSError, TypeError) as e:
            raise RuntimeError(f"Failed to write metadata file at {meta_path}: {e}") from e

    # internal flag to indicate initialization is complete
    self.root_initialized = True
    return True

def initialize(self):
