    # Standard OCFL directories (`.ocfl/`, `objects/`, `metadata/`).
    ocfl_dir = os.path.join(root_path, ".ocfl")
    objects_dir = os.path.join(ocfl_dir, "objects")
    metadata_dir = os.path.join(ocfl_dir, "metadata")

    for dir_path in (ocfl_dir, objects_dir, metadata_dir):
        try:
            os.makedirs(dir_path, exist_ok=True)
        except OSError as exc:
            raise RuntimeError(f"Could not create OCFL subdirectory '{dir_path}': {exc}") from exc

