def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str) or not version:
        raise ValueError("version must be a non-empty string")

    # Find the first digit to separate any leading non-numeric prefix (e.g., 'v')
    first_digit = None
    for i, ch in enumerate(version):
        if ch.isdigit():
            first_digit = i
            break
    if first_digit is None:
        raise ValueError("version string must contain at least one digit")

    prefix = version[:first_digit]
    numeric_part = version[first_digit:]

    parts = numeric_part.split('.')
    # Validate numeric parts
    for p in parts:
        if not p.isdigit():
            raise ValueError(f"Invalid numeric component '{p}' in version '{version}'")

    last_part = parts[-1]
    width = len(last_part)
    new_last = str(int(last_part) + 1)
    # Preserve zero padding if possible
    if len(new_last) < width:
        new_last = new_last.zfill(width)
    parts[-1] = new_last

    return prefix + '.'.join(parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")

    parts = version.split('.')
    if not parts:
        raise ValueError("empty version string")

    # Find the last numeric part
    last_index = -1
    for i in range(len(parts) - 1, -1, -1):
        if parts[i].isdigit():
            last_index = i
            break
    if last_index == -1:
        raise ValueError(f"no numeric part found in version '{version}'")

    last_part = parts[last_index]
    width = len(last_part)
    try:
        new_value = int(last_part) + 1
    except ValueError:
        raise ValueError(f"invalid numeric part '{last_part}' in version '{version}'")

    new_last_part = str(new_value)
    if len(new_last_part) < width:
        new_last_part = new_last_part.zfill(width)

    new_parts = parts[:last_index] + [new_last_part] + parts[last_index + 1:]
    return '.'.join(new_parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("version string cannot be empty")

    parts = version.split('.')
    last = parts[-1]

    try:
        numeric = int(last)
    except ValueError as exc:
        raise ValueError(f"cannot parse version segment '{last}' as integer") from exc

    new_numeric = numeric + 1
    # preserve original width if there were leading zeros
    width = len(last)
    new_last = str(new_numeric).zfill(width)
    parts[-1] = new_last
    return '.'.join(parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        raise TypeError("version must be a string")
    if not version:
        raise ValueError("empty version string")
    if not version.isdigit():
        raise ValueError("version must contain only digits")

    # Determine padding: keep original length only if there is a leading zero
    # and the string is longer than one character (so we avoid turning '0' into '001')
    pad_len = None
    if len(version) > 1 and version.startswith('0'):
        pad_len = len(version)

    num = int(version) + 1
    # Convert back to string, preserving padding if needed
    if pad_len is not None:
        return str(num).zfill(pad_len)
    return str(num)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os

    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        return

    # Helper to read an inventory file into a dict: {file: digest}
    def _read_inventory(inv_path):
        digests = {}
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Inventory file not found: {inv_path}")
        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                for line in f:
                    line = line.strip()
                    if not line or line.startswith("#"):
                        continue
                    parts = line.split(None, 1)
                    if len(parts) != 2:
                        continue  # malformed line, skip
                    path, digest = parts
                    digests[path] = digest
        except Exception as exc:
            raise IOError(f"Failed to read inventory '{inv_path}': {exc}") from exc
        return digests

    # Determine root path for inventories (assumed to be the object's base dir)
    # Use an attribute that should exist on the instance; fall back to os.getcwd()
    base_dir = getattr(self, "docroot", os.getcwd())

    root_inventory_path = os.path.join(base_dir, "inventory.xml")
    try:
        root_digests = _read_inventory(root_inventory_path)
    except Exception:
        # If root inventory is missing or unreadable, treat as empty
        root_digests = {}

    # Store differences between each version inventory and the root
    inventory_differences = {}

    for v_dir in version_dirs:
        # Construct path to the inventory in this version directory
        inv_path = os.path.join(base_dir, v_dir, "inventory.xml")
        try:
            v_digests = _read_inventory(inv_path)
        except FileNotFoundError as nf:
            # If a version is missing its inventory, we treat it as an error
            raise ValueError(f"Version directory '{v_dir}' lacks a required inventory file.") from nf
        except Exception as exc:
            # Any other IO errors are propagated as runtime errors
            raise RuntimeError(f"Error reading inventory for version '{v_dir}': {exc}") from exc

        # Compare digests against the root inventory
        differing_files = []
        for key, digest in v_digests.items():
            root_digest = root_digests.get(key)
            if root_digest is None or root_digest != digest:
                differing_files.append(key)

        if differing_files:
            inventory_differences[v_dir] = differing_files

    # Store the differences so other methods can access them
    # Use a predictable attribute name
    setattr(self, "_inventory_differences", inventory_differences)

    # Method returns the diffs dictionary for convenience
    return inventory_differences

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os

        if not isinstance(version_dirs, (list, tuple)) or not version_dirs:
            raise ValueError("version_dirs must be a non-empty list or tuple of directory names")

        root_inventory = None
        differences = {}

        prev_inventory = None
        for i, vdir in enumerate(version_dirs):
            inventory_path = os.path.join(vdir, "inventory.txt")
            if not os.path.isfile(inventory_path):
                raise FileNotFoundError(
                    f"Missing inventory file in '{vdir}'. Expected at {inventory_path}"
                )

            # Load inventory for this version
            inv = {}
            try:
                with open(inventory_path, "r", encoding="utf-8") as f:
                    for line in f:
                        line = line.strip()
                        if not line or line.startswith("#"):
                            continue
                        parts = line.split(None, 1)
                        if len(parts) == 2:
                            filename, digest = parts
                            inv[filename] = digest
            except Exception as exc:
                raise RuntimeError(f"Error reading inventory '{inventory_path}': {exc}") from exc

            # Ensure this inventory contains all entries of the previous one
            if prev_inventory is not None:
                missing_keys = set(prev_inventory) - set(inv)
                if missing_keys:
                    missing_list = ", ".join(sorted(missing_keys))
                    raise ValueError(
                        f"Version directory '{vdir}' inventory is missing entries "
                        f"from previous version(s): {missing_list}"
                    )

            # Compare digests against root inventory and record differences
            if i == 0:
                root_inventory = inv
            else:
                for fname, digest in inv.items():
                    root_digest = root_inventory.get(fname)
                    if root_digest and root_digest != digest:
                        differences.setdefault(fname, []).append(vdir)

            prev_inventory = inv

        return differences

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.
    """
    import os
    import json

    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        # Nothing to validate; nothing to do.
        return True

    # Prepare storage for inventories and digests that differ from the root
    self.inventories = {}
    self.different_digests = []

    root_inventory = None

    for idx, dir_name in enumerate(version_dirs):
        inventory_path = os.path.join(dir_name, "inventory.json")
        try:
            with open(inventory_path, encoding="utf-8") as fp:
                inv = json.load(fp)
        except FileNotFoundError:
            raise FileNotFoundError(
                f"Missing inventory file in version directory '{dir_name}'. Expected '{inventory_path}'."
            )
        except json.JSONDecodeError as exc:
            raise ValueError(
                f"Invalid JSON in inventory '{inventory_path}': {exc}"
            )

        if not isinstance(inv, dict):
            raise ValueError(
                f"Inventory '{inventory_path}' must be a JSON object mapping content IDs to digests"
            )

        # Store the inventory
        self.inventories[dir_name] = inv

        # The first inventory is considered the root inventory
        if idx == 0:
            root_inventory = inv
            continue

        # Compare the current inventory with the root inventory
        for content_id, digest in inv.items():
            root_digest = root_inventory.get(content_id)
            if root_digest is None:
                # New content that does not exist in the root inventory
                self.different_digests.append(
                    (dir_name, content_id, None, digest)
                )
            elif digest != root_digest:
                # Digest differs from the root
                self.different_digests.append(
                    (dir_name, content_id, root_digest, digest)
                )

        # Optionally, you could also check if any content present in the root
        # inventory is missing from the current inventory, but that logic depends
        # on the specific validation rules you wish to enforce.

    return True

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os
    import xml.etree.ElementTree as ET

    def _parse_inventory(path):
        """
        Try to parse an inventory file from the given path. Supports both an
        XML file with <file name="..." digest="..."/> elements and a simple
        text file where each line contains 'filename digest'.
        Returns a dictionary mapping filenames to their digests.
        """
        inv = {}
        try:
            tree = ET.parse(path)
            root = tree.getroot()
            for fe in root.findall('.//file'):
                name = fe.get('name')
                digest = fe.get('digest')
                if name and digest:
                    inv[name] = digest
            # If at least one file element was found, assume XML format is correct
            if inv:
                return inv
        except (ET.ParseError, FileNotFoundError):
            pass

        # Fallback to simple text format
        try:
            with open(path, 'r', encoding='utf-8') as fh:
                for line in fh:
                    parts = line.strip().split(None, 1)
                    if len(parts) != 2:
                        continue
                    name, digest = parts
                    inv[name] = digest
        except FileNotFoundError:
            raise FileNotFoundError(f"Inventory file not found: {path}")
        except Exception as exc:
            raise ValueError(f"Failed to parse inventory '{path}': {exc}")

        return inv

    if not hasattr(self, 'root_inventory') or not isinstance(self.root_inventory, dict):
        raise AttributeError("Instance must have a 'root_inventory' dictionary.")

    # Collect differences between root inventory and each version inventory
    differences = []

    for vd in version_dirs:
        inv_path = os.path.join(vd, 'inventory.xml')
        # If XML doesn't exist, try a plain text inventory
        if not os.path.exists(inv_path):
            inv_path = os.path.join(vd, 'inventory.txt')
            if not os.path.exists(inv_path):
                # no inventory for this version – could be acceptable; skip
                continue

        try:
            inv = _parse_inventory(inv_path)
        except Exception as exc:
            raise ValueError(f"Error loading inventory for version '{vd}': {exc}")

        for fname, digest in inv.items():
            root_digest = self.root_inventory.get(fname)
            if root_digest is None:
                # File is new in this version; record as difference
                differences.append({
                    'file': fname,
                    'version': vd,
                    'root_digest': None,
                    'version_digest': digest
                })
            elif root_digest != digest:
                differences.append({
                    'file': fname,
                    'version': vd,
                    'root_digest': root_digest,
                    'version_digest': digest
                })

    # Store or return differences as needed. Here we simply return them.
    return differences

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        import os
        import json

        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")

        if not version_dirs:
            raise ValueError("version_dirs is empty – nothing to validate")

        root_inventory = None
        self.different_digests = []  # reset any prior record

        for idx, dir_name in enumerate(version_dirs):
            if not isinstance(dir_name, str):
                raise TypeError(f"directory name at position {idx} is not a string")

            # Expect inventory file named 'inventory.json' in each directory
            inv_path = os.path.join(dir_name, "inventory.json")
            if not os.path.isfile(inv_path):
                raise FileNotFoundError(
                    f"Missing inventory file in version directory '{dir_name}'. Expected at {inv_path}"
                )

            try:
                with open(inv_path, "r", encoding="utf-8") as f:
                    inventory = json.load(f)
            except Exception as e:
                raise ValueError(f"Failed to load inventory file '{inv_path}': {e}")

            if not isinstance(inventory, dict):
                raise ValueError(f"Inventory in '{inv_path}' is not a JSON object (dict)")

            if idx == 0:
                # first version is considered the root inventory
                root_inventory = inventory
            else:
                # compare digests with root inventory
                for key, val in inventory.items():
                    root_val = root_inventory.get(key)
                    if root_val is not None and val != root_val:
                        self.different_digests.append((key, root_val, val))

        # If any differences were recorded, we keep them on the instance for later use
        # Method returns True on successful validation
        return True

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root' - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file' - a file, might be an inventory
        other string explains error description

    Looks only at "0=* Namaste files to determine the directory type.
    """
    import os, fnmatch

    # Resolve to absolute path
    path = os.path.abspath(path)

    # Path does not exist
    if not os.path.exists(path):
        return f"not found: {path}"

    # File path
    if os.path.isfile(path):
        return 'file'

    # Directory path
    if os.path.isdir(path):
        # Directory could be a root if it contains subfolder 'objects'
        has_objects = os.path.isdir(os.path.join(path, 'objects'))

        # Look for any Namaste file "0=*"
        def has_namaste(p):
            try:
                for entry in os.listdir(p):
                    if fnmatch.fnmatch(entry, '0=*') and os.path.isfile(os.path.join(p, entry)):
                        return True
            except Exception:
                pass
            return False

        if has_objects:
            # probable root; confirm Namaste file in the root
            if has_namaste(path):
                return 'root'
            else:
                return f"root? missing Namaste file in {path}"
        else:
            # probable object; confirm Namaste file
            if has_namaste(path):
                return 'object'
            else:
                return f"object? missing Namaste file in {path}"

    # If we get here, something unexpected
    return f"unknown type for {path}"

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a regular file (might be an inventory)
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os

    try:
        if not os.path.exists(path):
            return f"not found: {path}"

        if os.path.isfile(path):
            return "file"

        if not os.path.isdir(path):
            return f"unknown type: {path}"

        # Check for the presence of an OCFL .ocfl_version file
        ocfl_version_file = os.path.join(path, ".ocfl_version")
        if os.path.isfile(ocfl_version_file):
            try:
                with open(ocfl_version_file, "r", encoding="utf-8") as fp:
                    content = fp.read().strip().lower()
            except Exception as exc:
                return f"cannot read .ocfl_version: {exc}"
            if content == "root":
                return "root"
            if content == "object":
                return "object"
            return f"unknown ocfl_version content: '{content}'"

        # Fallback: look for Namaste files matching "0=*"
        # Only check files directly in this directory (not recursive)
        namaste_files = []
        try:
            for entry in os.listdir(path):
                if entry.startswith("0="):
                    full = os.path.join(path, entry)
                    if os.path.isfile(full):
                        namaste_files.append(entry)
        except Exception as exc:
            return f"cannot list directory: {exc}"

        if not namaste_files:
            return f"missing Namaste file in {path}"
        if len(namaste_files) == 1:
            # If there is exactly one Namaste file but no .ocfl_version
            # it's ambiguous; prefer 'root' as a safe default if the directory
            # contains no subdirectories (except maybe ignored dot files).
            try:
                entries = [e for e in os.listdir(path) if not e.startswith('.')]
            except Exception:
                entries = []
            subdirs = [e for e in entries if os.path.isdir(os.path.join(path, e))]
            # If no subdirectories, treat as root; otherwise object
            if not subdirs:
                return "root"
            return "object"

        # Multiple Namaste files: best guess is an object directory
        return "object"

    except Exception as exc:
        return f"unexpected error: {exc}"

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""

    # Validate inputs
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if isinstance(bug_ids, (int, str)):
        bug_ids = [bug_ids]
    if not isinstance(bug_ids, (list, tuple)):
        raise TypeError("bug_ids must be a list or tuple of bug identifiers")

    # Extract existing ids from params if any
    existing_ids = set()
    if 'ids' in params:
        ids_val = params['ids']
        if isinstance(ids_val, str):
            if ids_val:
                try:
                    existing_ids.update(int(i.strip()) for i in ids_val.split(',') if i.strip())
                except ValueError:
                    raise ValueError("Existing 'ids' value must be a comma-separated list of integers")
        else:
