def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to determine if a node is a MappingNode
    def is_mapping(node):
        try:
            return isinstance(node, MappingNode)
        except NameError:
            return False

    # Recursive merge of two MappingNodes
    def merge_mapping_nodes(n1, n2):
        # Build a lookup for n1's pairs by key string
        existing_pairs = n1.value  # list of (key_node, val_node)
        new_pairs = n2.value
        key_to_index = {k.value: (i, p) for i, (k, p) in enumerate(existing_pairs)}
        # Start with a shallow copy of existing pairs
        merged_pairs = existing_pairs[:]
        for k_node, v_node in new_pairs:
            k = k_node.value
            if k in key_to_index:
                idx, (_, existing_val) = key_to_index[k]
                if is_mapping(existing_val) and is_mapping(v_node):
                    merged_val = merge_mapping_nodes(existing_val, v_node)
                else:
                    merged_val = v_node
                merged_pairs[idx] = (k_node, merged_val)
            else:
                merged_pairs.append((k_node, v_node))
                key_to_index[k] = (len(merged_pairs) - 1, (k_node, v_node))
        # Return a new MappingNode with same tag and merged pairs
        return type(n1)(tag=n1.tag, value=merged_pairs)

    # Main merging logic
    merged = {}
    key_to_keynode = {}
    key_order = []

    for key_node, value_node in nodes:
        # Defensive: ensure key_node is scalar
        try:
            key_val = key_node.value
        except AttributeError:
            # If key_node doesn't have value, use default string representation
            key_val = str(key_node)

        if key_val not in merged:
            merged[key_val] = value_node
            key_to_keynode[key_val] = key_node
            key_order.append(key_val)
        else:
            existing = merged[key_val]
            if is_mapping(existing) and is_mapping(value_node):
                merged[key_val] = merge_mapping_nodes(existing, value_node)
            else:
                merged[key_val] = value_node

    # Construct result in original key order, using the first key_node seen
    result = []
    for key_val in key_order:
        key_node = key_to_keynode[key_val]
        result.append((key_node, merged[key_val]))

    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    def _merge_value(v1, v2):
        # If both are MappingNode, merge recursively
        if getattr(v1, 'tag', None) == 'tag:yaml.org,2002:map' and getattr(v2, 'tag', None) == 'tag:yaml.org,2002:map':
            # Convert v1 into dict of key_value to (key_node, val_node)
            merged_inner = {}
            for k_node, val_node in v1.value:
                merged_inner[k_node.value] = (k_node, val_node)
            for k_node, val_node in v2.value:
                key = k_node.value
                if key in merged_inner:
                    merged_val = _merge_value(merged_inner[key][1], val_node)
                    merged_inner[key] = (k_node, merged_val)
                else:
                    merged_inner[key] = (k_node, val_node)
            # Rebuild list preserving original order of v1 keys, then new keys
            new_list = []
            handled = set()
            for k_node, val_node in v1.value:
                key = k_node.value
                new_list.append((k_node, merged_inner[key][1]))
                handled.add(key)
            for key, pair in merged_inner.items():
                if key not in handled:
                    new_list.append(pair)
            return MappingNode(tag=v1.tag, value=new_list)
        else:
            # Non-mapping nodes: last value wins
            return v2

    if not nodes:
        return []

    # Merge duplicate keys
    merged_dict = {}
    first_occurrence = {}
    for key_node, value_node in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            # Skip nodes with no identifiable key
            continue
        if key in merged_dict:
            merged_dict[key] = _merge_value(merged_dict[key], value_node)
        else:
            merged_dict[key] = value_node
            first_occurrence[key] = key_node

    # Reconstruct result preserving original key order
    result = []
    for key_node, _ in nodes:
        key = getattr(key_node, 'value', None)
        if key is None:
            continue
        if key in merged_dict:
            result.append((key_node, merged_dict[key]))
            del merged_dict[key]
    return result

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a space-separated
    string.
    """
    try:
        actions = parser._actions
    except AttributeError:
        raise TypeError('Expected an argparse.ArgumentParser instance')
    flags = []
    for action in actions:
        # Each action may have multiple option strings (e.g., ['-a', '--alpha'])
