def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse
    try:
        parser = argparse.ArgumentParser()
        # NOTE: The caller should add any required global arguments or subparsers
        # to this parser *before* invoking parse_arguments. This function only
        # performs the actual parsing operation.
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
    except Exception as exc:
        raise ValueError(f"Argument parsing failed: {exc}") from exc

    # Store unknown arguments on the namespace for potential downstream use
    if unknown:
        setattr(namespace, "_unknown_args", unknown)

    # Determine the key for the resulting dictionary.
    # Commonly a subparser uses a destination attribute such as 'subcommand' or
    # 'subparser_name'.  We try both names; if neither is present we default to
    # 'global'.
    key = getattr(namespace, "subcommand", None) or getattr(namespace, "subparser_name", None)
    if key:
        return {key: namespace}
    return {"global": namespace}

def parse_arguments(*unparsed_arguments):
    """
    Given command-line arguments with which this script was invoked, parse the arguments and return
    them as a dict mapping from subparser name (or "global") to an argparse.Namespace instance.
    """
    import argparse

    # Create a top-level parser. We do not know any specific options in advance,
    # but we allow the parser to accept any unknown arguments without error.
    parser = argparse.ArgumentParser(add_help=False)
    # If the caller wants to see help, keep the default help option.
    # Note that NO subparsers are defined here because we have no knowledge
    # of them; the returned mapping will only contain a 'global' key.
    try:
        namespace, unknown = parser.parse_known_args(unparsed_arguments)
    except Exception:
        # In unexpected failure cases, return an empty namespace under 'global'
        namespace = argparse.Namespace()
    return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    if not isinstance(unparsed_arguments, (list, tuple)):
        # coerce to list to allow indexing and ordering
        try:
            unparsed_arguments = list(unparsed_arguments)
        except Exception:
            raise TypeError("unparsed_arguments must be an iterable of strings")

    # Ensure subparsers is a dict mapping names to ArgumentParser objects
    if not isinstance(subparsers, dict):
        raise TypeError("subparsers must be a dict mapping names to ArgumentParser objects")

    parsed_results = {}
    all_claimed = set()

    for name, parser in subparsers.items():
        if not hasattr(parser, "parse_known_args"):
            raise TypeError(f"Subparser for '{name}' does not have method parse_known_args")
        try:
            namespace, unknowns = parser.parse_known_args(unparsed_arguments)
        except Exception as exc:
            # In case of an exception, we log it and skip this parser
            # but we could also propagate; here we choose to skip
            raise RuntimeError(f"Error parsing arguments for subparser '{name}': {exc}") from exc
        parsed_results[name] = namespace
        # Determine which arguments were claimed by this parser
        claimed_by_this = set(unparsed_arguments) - set(unknowns)
        all_claimed.update(claimed_by_this)

    # Arguments not claimed by any subparser
    remaining = [arg for arg in unparsed_arguments if arg not in all_claimed]

    return parsed_results, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    """
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments.
    This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    """
    parsed = {}
    remaining = []

    for name, parser in subparsers.items():
        try:
            ns, rem = parser.parse_known_args(unparsed_arguments)
        except Exception:
            # If parsing fails, skip this subparser
            continue

        parsed[name] = ns
        # Keep the unclaimed arguments: add unique items only
        for arg in rem:
            if arg not in remaining:
                remaining.append(arg)

    return parsed, remaining

def deep_merge_nodes(nodes):
    """
    Merge a list of YAML mapping nodes that may contain duplicate keys.
    The last value wins in case of non-mapping conflicts.
    """
    def is_mapping(node):
        return hasattr(node, "value") and isinstance(node.value, list)

    def merge_nodes(a, b):
        """
        Merge two nodes recursively.
        If both are mappings, deep-merge their contents.
        Otherwise, the second node wins.
        """
        if is_mapping(a) and is_mapping(b):
            # Build dictionaries of existing key -> (key_node, value_node)
            dict_a = {k.value: (k, v) for k, v in a.value}
            for k_node, val in b.value:
                key = k_node.value
                if key in dict_a:
                    merged_val = merge_nodes(dict_a[key][1], val)
                    dict_a[key] = (k_node, merged_val)
                else:
                    dict_a[key] = (k_node, val)
            # Preserve original order from a, then new keys
            new_pairs = list(dict_a.values())
            return type(a)(tag=a.tag, value=new_pairs)
        else:
            # Not both mappings: the later value wins
            return b

    # Maintain order of first occurrences of keys
    merged = {}
    key_order = []

    for key_node, val_node in nodes:
        key = key_node.value
        if key in merged:
            merged[key] = merge_nodes(merged[key], val_node)
        else:
            merged[key] = val_node
            key_order.append(key)

    # Build the final merged list preserving first-key order
    result = [(next(k for k in nodes if k[0].value == key)[0], merged[key]) for key in key_order]
    return result

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.
    '''
    if nodes is None:
        return []
    # Helper to merge two lists of (key_node, value_node) tuples
    def merge_lists(old, new):
        merged = {}
        # Insert old entries
        for k_node, v_node in old:
            merged[k_node.value] = (k_node, v_node)
        # Merge new entries
        for k_node, v_node in new:
            key = k_node.value
            if key in merged:
                old_k, old_v = merged[key]
                # If both values are MappingNodes, deep merge
                if isinstance(old_v, MappingNode) and isinstance(v_node, MappingNode):
                    # Recursively merge child lists
                    merged_child = merge_lists(old_v.value, v_node.value)
                    merged_v = MappingNode(tag=v_node.tag, value=merged_child)
                else:
                    # Last value wins
                    merged_v = v_node
                merged[key] = (old_k, merged_v)
            else:
                merged[key] = (k_node, v_node)
        # Preserve insertion order: first occurrence retains its position
        return list(merged.values())
    # Perform the merge on the top-level list
    return merge_lists([], nodes) if not nodes else merge_lists([], nodes) or nodes

def deep_merge_nodes(nodes):
    """
    Merge duplicate keys in a list of (ScalarNode, value) tuples, recursively merging MappingNode values.
    """
    # Helper functions
    def is_mapping_node(node):
        return getattr(node, "__class__", None).__name__ == "MappingNode"

    def merge_nodes(a, b):
        if is_mapping_node(a) and is_mapping_node(b):
            return merge_mapping_nodes(a, b)
        else:
            # Non-mapping nodes: last wins
            return b

    def merge_mapping_nodes(a_node, b_node):
        """
        Deep merge two MappingNode objects.
        """
        # Build dictionaries keyed by the scalar value
        mapping_a = {k.value: (k, v) for k, v in a_node.value}
        mapping_b = {k.value: (k, v) for k, v in b_node.value}

        # Start with a's mapping
        merged = dict(mapping_a)

        # Merge b into it
        for key, (b_key_node, b_val_node) in mapping_b.items():
            if key in merged:
                a_key_node, a_val_node = merged[key]
                merged[key] = (a_key_node, merge_nodes(a_val_node, b_val_node))
            else:
                merged[key] = (b_key_node, b_val_node)

        # Preserve order: a's keys first, then new keys from b
        merged_list = []
        for k_node, v_node in a_node.value:
            merged_list.append((k_node, merged[k_node.value][1]))
        for k_node, v_node in b_node.value:
            if k_node.value not in mapping_a:
                merged_list.append((k_node, v_node))

        return type(a_node)(tag=a_node.tag, value=merged_list)

    # Aggregate by key value, preserving the first key node
    seen = {}
    for key_node, value_node in nodes:
        key_value = key_node.value
        if key_value in seen:
            # Merge with existing
            existing_key_node, existing_value_node = seen[key_value]
            new_value_node = merge_nodes(existing_value_node, value_node)
            seen[key_value] = (existing_key_node, new_value_node)
        else:
            seen[key_value] = (key_node, value_node)

    # Construct result list in order of first occurrence
    result = []
    seen_keys = set()
    for key_node, value_node in nodes:
        key_value = key_node.value
        if key_value not in seen_keys:
            seen_keys.add(key_value)
            _, merged_value_node = seen[key_value]
            result.append((key_node, merged_value_node))

    return result

