def bash_completion():
    """
    Return a bash completion script for the borgmatic command.
    The script is generated by introspecting borgmatic's command-line
    argument parsers.  This function attempts to import the parser
    from the typical borgmatic entry point.  If it fails to locate a
    parser or if ``argcomplete`` isn't available, it returns an empty
    string instead of raising an exception.
    """
    script = ''
    try:
        # Attempt to import argcomplete which has utilities to generate
        # completion scripts for argparse parsers.
        import argcomplete
    except Exception:
        # argcomplete is not installed – fall back to empty script
        return script

    try:
        # Borgmatic typically exposes the top-level parser as
        # borgmatic.cli.main.parser.  Import that parser dynamically.
        from borgmatic.cli.main import parser as _parser
    except Exception:
        # If the import fails, attempt a more generic lookup
        try:
            import borgmatic
            # Search for an attribute named 'parser' in any submodule
            for _, mod_name, _ in pkgutil.iter_modules(borgmatic.__path__):
                full_name = f"borgmatic.{mod_name}"
                try:
                    mod = __import__(full_name, fromlist=['parser'])
                    _parser = getattr(mod, 'parser', None)
                    if _parser:
                        break
                except Exception:
                    continue
            else:
                _parser = None
        except Exception:
            _parser = None

    if not _parser:
        return script

    try:
        # Generate the bash completion script using argcomplete's helper.
        # The script generated is appropriate for ``bash`` and tries to
        # wrap the original parser so that runtime completion works.
        # The returned value contains the full shell function definition.
        script = argcomplete.get_scripted_completer(_parser, prog='borgmatic')
        if not isinstance(script, str):
            script = str(script)
    except Exception as e:
        # Any failure during script generation should not crash the caller.
        script = ''
    return script

