    return {'global': namespace}

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. This allows
    common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Basic validation
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a list or tuple of strings')
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dict mapping names to ArgumentParser instances')

    parsed_results = {}
    consumed_args = set()

    for name, parser in subparsers.items():
        # Ensure the parser is an ArgumentParser instance
        try:
            import argparse
            valid_parser = isinstance(parser, argparse.ArgumentParser)
        except ImportError:
            valid_parser = False

        if not valid_parser:
            raise TypeError(f'Subparser "{name}" is not an argparse.ArgumentParser instance')

        try:
            namespace, unknown = parser.parse_known_args(unparsed_arguments)
            parsed_results[name] = namespace
        except SystemExit:
            # argparse uses SystemExit to handle -h/--help; we ignore it for the purpose of parsing
            parsed_results[name] = None
            unknown = list(unparsed_arguments)  # nothing parsed
        except Exception:
            parsed_results[name] = None
            unknown = list(unparsed_arguments)

        # Mark all arguments that this parser consumed
        # Any argument not in the unknown list was parsed by this parser
        for arg in unparsed_arguments:
            if arg not in unknown:
                consumed_args.add(arg)

    # Remaining arguments are those that were not consumed by any subparser
    remaining = [arg for arg in unparsed_arguments if arg not in consumed_args]

    return parsed_results, remaining

def parse_subparser_arguments(unparsed_arguments, subparsers):
    '''
    Given a sequence of arguments and a dict from subparser name to argparse.ArgumentParser
    instance, give each requested action's subparser a shot at parsing all arguments. 
    This allows common arguments like "--repository" to be shared across multiple subparsers.

    Return the result as a tuple of (a dict mapping from subparser name to a parsed namespace of
    arguments, a list of remaining arguments not claimed by any subparser).
    '''
    # Ensure the input is a list (or tuple) of arguments
    if not isinstance(unparsed_arguments, (list, tuple)):
        raise TypeError('unparsed_arguments must be a sequence (list or tuple) of strings')
    # Validate subparsers dict
    if not isinstance(subparsers, dict):
        raise TypeError('subparsers must be a dictionary mapping names to ArgumentParser instances')

    # If there are no subparsers, everything remains unclaimed
    if not subparsers:
        return {}, list(unparsed_arguments)

    parsed_map = {}
    remaining_sets = []

    for name, parser in subparsers.items():
        if not hasattr(parser, 'parse_known_args'):
            raise TypeError(f'Subparser for {name} does not have a parse_known_args method')
        ns, remaining = parser.parse_known_args(unparsed_arguments)
        parsed_map[name] = ns
        remaining_sets.append(set(remaining))

    # Compute arguments that were not recognised by any subparser
    if remaining_sets:
        common_remaining_set = set.intersection(*remaining_sets)
    else:
        common_remaining_set = set()

    # Preserve original order of remaining arguments
    remaining_args = [arg for arg in unparsed_arguments if arg in common_remaining_set]

    return parsed_map, remaining_args

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int) or max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    def _generator():
        for i in range(0, len(response), max_results):
            yield response[i:i + max_results]

    return _generator()

