        return url

def _replace_url_args(url, url_args):
    """Replace any custom string URL items with values in args"""

    import re

    if not isinstance(url, str):
        raise TypeError("url must be a string")

    if not isinstance(url_args, (dict, list, tuple)):
        raise TypeError("url_args must be a dict, list, or tuple")

    # Pattern to find {placeholder}
    pattern = re.compile(r'\{([^{}]+)\}')

    def _replace(match):
        key = match.group(1)
        value = None

        if isinstance(url_args, dict):
            if key in url_args:
                value = url_args[key]
        else:  # list/tuple: allow numeric keys
            if key.isdigit():
                idx = int(key)
                if 0 <= idx < len(url_args):
                    value = url_args[idx]

        # If value not found, keep original placeholder
        if value is None:
            return match.group(0)

        # If value is a list or tuple, join with commas
        if isinstance(value, (list, tuple)):
            return ','.join(map(str, value))

        return str(value)

    return pattern.sub(_replace, url)

