        digits = [alphabet[0]] * pad_len + digits
    return "".join(digits)

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    # Basic validation
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError(f"number must be non-negative, got {number}")
    if not isinstance(alphabet, (list, tuple)) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty sequence of strings")

    base = len(alphabet)
    if base <= 1:
        raise ValueError("alphabet must contain at least two symbols")

    # Special case for zero
    if number == 0:
        digits = [alphabet[0]]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        digits.reverse()

    # Apply padding if requested
    if padding is not None:
        if not isinstance(padding, int) or padding < 0:
            raise ValueError(f"padding must be a non-negative integer, got {padding}")
        if len(digits) < padding:
            digits = [alphabet[0]] * (padding - len(digits)) + digits

    return "".join(digits)

