        Args:
            item: dict to convert
        Returns:
            dict with keys converted to regexes
        """
        if not isinstance(item, dict):
            raise TypeError("Input must be a dictionary")

        def _wildcard_to_regex(pattern):
            # Escape regex special chars except * and ?
            escaped = re.escape(pattern)
            # Replace escaped wildcard characters with regex equivalents
            escaped = escaped.replace(r'\*', '.*').replace(r'\?', '.')
            # Anchor the regex to match the whole string
            if not escaped.startswith('^'):
                escaped = '^' + escaped
            if not escaped.endswith('$'):
                escaped = escaped + '$'
            return escaped

        converted = {}
        for key, value in item.items():
            if isinstance(key, str):
                converted_key = _wildcard_to_regex(key)
                converted[converted_key] = value
            else:
                # Leave non-string keys unchanged
                converted[key] = value

        return converted

