def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None or (isinstance(frequency, str) and frequency.strip().lower() == 'always'):
        return None

    if not isinstance(frequency, str):
        raise ValueError(f'Frequency must be a string or None, got {type(frequency).__name__}')

    import re
    frequency = frequency.strip()
    # Pattern: number followed by space and unit (letters only)
    m = re.fullmatch(r'(\d+)\s*([a-zA-Z]+)', frequency)
    if not m:
        raise ValueError(f'Cannot parse frequency: "{frequency}"')

    value, unit = m.group(1), m.group(2).lower()
    try:
        value = int(value)
    except ValueError:
        raise ValueError(f'Invalid numeric value in frequency: "{value}"')

    # Map unit to timedelta keyword
    unit_map = {
        'days': 'days',  'day': 'days',
        'weeks': 'weeks', 'week': 'weeks',
        'hours': 'hours', 'hour': 'hours',
        'minutes': 'minutes', 'minute': 'minutes',
        'seconds': 'seconds', 'second': 'seconds',
        'milliseconds': 'milliseconds', 'millisecond': 'milliseconds',
        'microseconds': 'microseconds', 'microsecond': 'microseconds',
    }

    if unit not in unit_map:
        raise ValueError(f'Unsupported time unit in frequency: "{unit}"')

    kwargs = {unit_map[unit]: value}
    return datetime.timedelta(**kwargs)

