    value_str, unit = match.groups()
    try:
        value = float(value_str) if '.' in value_str else int(value_str)
    except ValueError:
        raise ValueError(f'invalid numeric value "{value_str}" in frequency "{frequency}"')

    unit = unit.lower()
    unit_map = {
        'second': 'seconds',
        'seconds': 'seconds',
        'minute': 'minutes',
        'minutes': 'minutes',
        'hour': 'hours',
        'hours': 'hours',
        'day': 'days',
        'days': 'days',
        'week': 'weeks',
        'weeks': 'weeks',
    }

    if unit not in unit_map:
        raise ValueError(f'unknown unit "{unit}" in frequency "{frequency}"')

    kwargs = {unit_map[unit]: value}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    # Resolve address(es) of input host
    try:
        host_addrs = {addr[4][0] for addr in socket.getaddrinfo(host, None)}
    except socket.gaierror:
        return False

    # Resolve address(es) of local machine
    local_addrs = set()
    # Include loopback addresses explicitly
    local_addrs.update({'127.0.0.1', '::1'})
    try:
        local_addrs.update({addr[4][0] for addr in socket.getaddrinfo(socket.gethostname(), None)})
    except socket.gaierror:
        # Fall back to just loopback if hostname resolution fails
        pass

    # If any resolved address matches one of the local addresses, it's local
    return bool(host_addrs & local_addrs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Quick check for known loopback names
        if host in ("localhost", "127.0.0.1", "::1"):
            return True

        # Resolve the host to all addresses (IPv4 and IPv6)
        try:
            addrinfo = socket.getaddrinfo(host, None)
        except socket.gaierror:
            return False

        for family, _, _, _, sockaddr in addrinfo:
            if family == socket.AF_INET:
                ip = sockaddr[0]
                # IPv4 loopback addresses start with 127.
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                if ip == "::1":
                    return True

        return False
    except Exception:
        # Any unexpected error should result in a safe False
        return False

