    """returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    # First, ensure we are on Windows
    if os.name != 'nt':
        return False

    # MSYSTEM env var is set in Git Bash (MINGW32, MINGW64, CYGWIN, MSYS)
    msystem = os.getenv('MSYSTEM', '')
    if msystem:
        return msystem.lower().startswith(('mingw', 'cygwin', 'msys'))

    # OSTYPE is also set in MSYS environments
    ostype = os.getenv('OSTYPE', '').lower()
    if ostype.startswith(('msys', 'cygwin')):
        return True

    # Some installations set TERM_PROGRAM to mintty when running under Git Bash
    if os.getenv('TERM_PROGRAM', '').lower() == 'mintty':
        return True

    return False

