def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Attempt to get variable name from named or positional groups
    groups = matcher.groupdict()
    var_name = groups.get('name')
    if var_name is None:
        try:
            var_name = matcher.group(1)
        except IndexError:
            var_name = None

    # Attempt to get default value from named or positional groups
    default_val = groups.get('default')
    if default_val is None:
        try:
            default_val = matcher.group(2)
        except IndexError:
            default_val = None

    if var_name is None:
        raise ValueError("Matcher does not contain a variable name.")

    # Retrieve the environment variable
    value = os.getenv(var_name)
    if value is None:
        if default_val is not None:
            return default_val
        else:
            raise KeyError(f"Environment variable '{var_name}' not found and no default value provided.")

    return value

def _resolve_string(matcher):
    """Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    """
    # Determine the variable name
    name = None
    try:
        # Named group 'name' preferred
        name = matcher.group('name')
    except Exception:
        try:
            # Fallback to first positional group
            name = matcher.group(1)
        except Exception:
            pass

    # Determine the default value if present
    default = None
    try:
        # Named group 'default' preferred
        default = matcher.group('default')
    except Exception:
        try:
            # Fallback to second positional group if exists
            if matcher.lastindex and matcher.lastindex >= 2:
                default = matcher.group(2)
        except Exception:
            pass

    if name is None:
        raise RuntimeError("Matcher does not contain a variable name")

    # Fetch from environment
    value = os.environ.get(name)
    if value is not None:
        return value
    if default is not None:
        return default

    raise RuntimeError(f"Environment variable '{name}' not set and no default provided")

