    elif isinstance(commands, list):
        cmd = list(commands)
    else:
        raise TypeError(f"commands must be a str or list, got {type(commands).__name__}")

    if args is None:
        args_list = []
    elif isinstance(args, list):
        args_list = args
    else:
        args_list = [args]

    cmd.extend(args_list)

