def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import os

    # Validate arguments
    if commands is None:
        raise ValueError("commands must not be None")
    if args is not None and not isinstance(args, (list, tuple)):
        raise ValueError("args must be a list or tuple of arguments")

    # Default environment
    if env is None:
        env = os.environ.copy()

    # Helper to execute a single command list
    def _execute(cmd):
        if verbose:
            print(f"Running command: {' '.join(cmd)}")
        stdout_pipe = subprocess.PIPE
        stderr_pipe = subprocess.PIPE if not hide_stderr else subprocess.DEVNULL
        result = subprocess.run(
            cmd,
            cwd=cwd,
            env=env,
            stdout=stdout_pipe,
            stderr=stderr_pipe,
            text=True
        )
        if result.returncode != 0:
            raise subprocess.CalledProcessError(
                result.returncode,
                cmd,
                output=result.stdout,
                stderr=result.stderr
            )
        return result.stdout

    # If commands is a string or a single list of arguments
    if isinstance(commands, str):
        full_cmd = [commands] + (list(args) if args else [])
        return _execute(full_cmd)

    # If commands is a list or tuple
    if isinstance(commands, (list, tuple)):
        # Determine how to pair commands with args
        if all(isinstance(c, (list, tuple)) for c in commands):
            # Each element is itself a command list
            outputs = []
            for cmd in commands:
                outputs.append(_execute(list(cmd)))
            return outputs
        elif all(isinstance(c, str) for c in commands):
            # All elements are command names; apply common args if provided
            outputs = []
            for cmd_name in commands:
                full_cmd = [cmd_name] + (list(args) if args else [])
                outputs.append(_execute(full_cmd))
            return outputs
        else:
            raise ValueError("commands list elements must be all str or all list/tuple")

    raise TypeError("commands must be a string or list/tuple of command specifications")

