    import subprocess, sys, shlex

    # Build the base command list
    if isinstance(commands, str):
        base_cmd = shlex.split(commands)
    elif isinstance(commands, (list, tuple)):
        base_cmd = list(commands)
    else:
        raise TypeError("commands must be a str, list, or tuple")

    # Append any additional arguments
    if args:
        if isinstance(args, str):
            args_list = shlex.split(args)
        elif isinstance(args, (list, tuple)):
            args_list = list(args)
        else:
            raise TypeError("args must be a str, list, or tuple")
        full_cmd = base_cmd + args_list
    else:
        full_cmd = base_cmd

    if verbose:
        sys.stderr.write("Running command: {}\n".format(" ".join(full_cmd)))

    # Set up stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    # Execute the command
    result = subprocess.run(
        full_cmd,
        cwd=cwd,
        env=env,
        stdout=subprocess.PIPE,
        stderr=stderr_target,
        text=True,
        check=True,
    )

    return result

