    """Dump to a py2-unicode or py3-string"""
    # Default to the safe dumper for security and readability
    if dumper is None:
        dumper = yaml.SafeDumper
    try:
        # Dump the object to a YAML string
        yaml_str = yaml.dump(
            obj,
            Dumper=dumper,
            default_flow_style=False,
            allow_unicode=True,
        )
    except Exception as exc:
        raise ValueError(f"Failed to dump object to YAML string: {exc}") from exc

    # In Python 2, yaml.dump may return a byte string; convert it to unicode.
    import sys
    if sys.version_info[0] < 3 and isinstance(yaml_str, bytes):
        try:
            yaml_str = yaml_str.decode("utf-8")
        except Exception as exc:
            raise ValueError(f"Could not decode byte string produced by yaml.dump: {exc}") from exc

    return yaml_str

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Default to safe dumper if none provided
    if dumper is None:
        dumper = yaml.SafeDumper

    # Try the modern dump signature
    try:
        result = yaml.dump(
            obj,
            Dumper=dumper,
            default_flow_style=False,
            allow_unicode=True
        )
    except TypeError:
        # Older yaml may not support allow_unicode, fall back
        result = yaml.dump(obj, Dumper=dumper, default_flow_style=False)

    # Ensure we return a string (unicode in py2, str in py3)
    if isinstance(result, bytes):
        try:
            result = result.decode("utf-8")
        except Exception:
            # If decoding fails, leave as is
            pass

    return result

def _dump_string(obj, dumper=None):
    """Dump to a py2-unicode or py3-string"""
    # Default dumper is yaml.safe_dump with friendly options
    if dumper is None:
        dumper = yaml.safe_dump
    # Perform the dump; ensure we get a string result
    try:
        s = dumper(obj, default_flow_style=False, allow_unicode=True)
    except Exception as exc:
        raise RuntimeError(f"YAML dumping failed: {exc}") from exc
    # In Python 2, the result might be a byte string; convert to unicode
    if isinstance(s, bytes):
        try:
            return s.decode("utf-8")
        except Exception:
            # If decoding fails, just return the bytes as-is
            return s
    # For Python 3, the result is a str
    return s

def make_array(shape, dtype=np.dtype("float32")):
    """
    Function to create an array with shape and dtype.

    Parameters
    ----------
    shape : tuple
        shape of the array to create
    dtype : `numpy.dtype`
        data-type of the array to create
    """
    # Validate and normalize shape
    if shape is None:
        raise ValueError("shape must not be None")
    if isinstance(shape, int):
        shape = (shape,)
    elif isinstance(shape, (list, tuple)):
        shape = tuple(shape)
    else:
        raise TypeError(f"shape must be an int, tuple, or list, got {type(shape).__name__}")
    if not shape:
        raise ValueError("shape cannot be empty")
    # Ensure dtype is a numpy.dtype instance
    if dtype is None:
        dtype = np.dtype("float32")
    elif isinstance(dtype, str):
        dtype = np.dtype(dtype)
    elif not isinstance(dtype, np.dtype):
        try:
            dtype = np.dtype(dtype)
        except Exception as e:
            raise TypeError(f"Invalid dtype: {dtype}") from e
    # Create and return the array
    return np.zeros(shape, dtype=dtype)

