def gaussian(x):
    """Gaussian centered around 0.2 with a sigma of 0.1."""
    mean = 0.2
    sigma = 0.1
    return np.exp(-((x - mean) ** 2) / (2 * sigma ** 2)) / (sigma * np.sqrt(2 * np.pi))

def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    # Convert input to numpy array for broadcasting
    try:
        x_arr = np.asarray(x, dtype=float)
    except Exception as e:
        raise TypeError("Input x must be numeric or convertible to a numeric array") from e

    mu = 0.2
    sigma = 0.1

    return np.exp(-((x_arr - mu) ** 2) / (2 * sigma ** 2))

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.'''
    import json
    import os
    import logging

    configs = {}
    errors = []

    def _log_error(msg, exc=None, path=None):
        record = logging.LogRecord(
            name='load_configurations',
            level=logging.ERROR,
            pathname=path if path else '',
            lineno=0,
            msg=msg,
            args=(),
            exc_info=exc
        )
        errors.append(record)

    def _apply_overrides(cfg, overrides_dict):
        if isinstance(cfg, dict) and isinstance(overrides_dict, dict):
            merged = dict(cfg)
            merged.update(overrides_dict)
            return merged
        return cfg

    def _resolve_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        return value

    if not isinstance(config_filenames, (list, tuple)):
        _log_error('config_filenames must be an iterable of filenames.', path='')
        return {}, errors

    for filename in config_filenames:
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                try:
                    cfg = json.load(f)
                except json.JSONDecodeError as e:
                    _log_error(f'JSON parsing error in {filename}: {e.msg}', exc=e, path=filename)
                    continue
        except FileNotFoundError as e:
            _log_error(f'Configuration file not found: {filename}', exc=e, path=filename)
            continue
        except OSError as e:
            _log_error(f'Error reading {filename}: {e}', exc=e, path=filename)
            continue

        # apply overrides if provided
        if overrides is not None:
            try:
                cfg = _apply_overrides(cfg, overrides)
            except Exception as e:
                _log_error(f'Error applying overrides to {filename}: {e}', exc=e, path=filename)
                continue

        # resolve environment variables
        if resolve_env:
            try:
                cfg = _resolve_env(cfg)
            except Exception as e:
                _log_error(f'Error resolving environment variables in {filename}: {e}', exc=e, path=filename)
                continue

        configs[filename] = cfg

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import logging
    import os
    import json
    import sys

    # Normalize input to a list of filenames
    if isinstance(config_filenames, str):
        filenames = [config_filenames]
    else:
        try:
            filenames = list(config_filenames)
        except TypeError:
            filenames = [config_filenames]

    # Prepare output containers
    parsed_configs = {}
    error_records = []

    # Helper to create a LogRecord with optional exc_info
    def make_record(msg, exc_info=None, filename=''):
        return logging.LogRecord(
            name='load_configurations',
            level=logging.ERROR,
            pathname=filename,
            lineno=0,
            msg=msg,
            args=None,
            exc_info=exc_info
        )

    for fname in filenames:
        # Attempt to read the file
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as exc:
            error_records.append(make_record(f"Failed to read file '{fname}': {exc}", exc_info=sys.exc_info(), filename=fname))
            continue

        # Expand environment variables if requested
        if resolve_env:
            try:
                content = os.path.expandvars(content)
            except Exception as exc:
                error_records.append(make_record(f"Failed to expand environment variables in '{fname}': {exc}", exc_info=sys.exc_info(), filename=fname))
                continue

        # Try to parse as JSON first
        cfg = None
        try:
            cfg = json.loads(content)
        except Exception:
            pass

        # If JSON fails, try YAML if available
        if cfg is None:
            try:
                import yaml
                cfg = yaml.safe_load(content)
            except Exception:
                pass

        # If still None, try ConfigParser (ini format)
        if cfg is None:
            try:
                import configparser
                parser = configparser.ConfigParser()
                parser.read_string(content)
                # Convert sections to dict
                cfg = {section: dict(parser.items(section)) for section in parser.sections()}
            except Exception:
                pass

        # If parsing succeeded, ensure we have a dict
        if not isinstance(cfg, dict):
            msg = f"File '{fname}' did not parse into a dictionary."
            if cfg is None:
                msg = f"Failed to parse configuration file '{fname}'."
            error_records.append(make_record(msg, exc_info=None, filename=fname))
            continue

        # Apply overrides if provided
        if overrides:
            if not isinstance(overrides, dict):
                error_records.append(make_record(f"Overrides must be a dictionary, got {type(overrides)}", exc_info=None, filename=fname))
            else:
                for key, value in overrides.items():
                    cfg[key] = value

        # Store the parsed configuration
        parsed_configs[fname] = cfg

    return parsed_configs, error_records

def protocol_handlers(cls, protocol_version=None):
    """Return a dictionary of available Bolt protocol handlers,
    keyed by version tuple. If an explicit protocol version is
    provided, the dictionary will contain either zero or one items,
    depending on whether that version is supported. If no protocol
    version is provided, all available versions will be returned.

    :param protocol_version: tuple identifying a specific protocol
        version (e.g. (3, 5)) or None
    :return: dictionary of version tuple to handler class for all
        relevant and supported protocol versions
    :raise TypeError: if protocol version is not passed in a tuple
    """
    if protocol_version is not None and not isinstance(protocol_version, tuple):
        raise TypeError("protocol_version must be a tuple of ints")
    handlers = {}
    # Expect a class-level mapping `_handlers` of version -> handler class
    for ver, handler_cls in getattr(cls, "_handlers", {}).items():
        # If a specific version was requested, skip unrelated entries
        if protocol_version is not None and ver != protocol_version:
            continue
        # Optional runtime checks for handler support
        if hasattr(handler_cls, "is_supported"):
            try:
                if not handler_cls.is_supported():
                    continue
            except Exception:
                # If the check fails, silently skip this handler
                continue
        elif hasattr(handler_cls, "supports_version"):
            try:
                if not handler_cls.supports_version(ver):
                    continue
            except Exception:
                continue
        handlers[ver] = handler_cls
    return handlers

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        instance = cls()
        if values is None:
            return instance
        # Accept a single string as a one‑item sequence
        try:
            iter(values)
        except TypeError:
            values = [values]
        for raw in values:
            if raw is None:
                continue
            raw = str(raw).strip()
            if not raw:
                continue
            try:
                # Try to create a bookmark object from the raw string if such a
                # factory method exists.  If it does not exist or fails, we fall
                # back to storing the raw string directly.
                bookmark = getattr(cls, "Bookmark", None)
                if bookmark and hasattr(bookmark, "from_raw_value"):
                    bookmark_obj = bookmark.from_raw_value(raw)
                else:
                    bookmark_obj = raw
            except Exception:
                # In case something unexpected happened, use the raw value
                bookmark_obj = raw
            instance.append(bookmark_obj)
        return instance

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values cannot be None")
    try:
        raw_values = list(values)
    except TypeError as exc:
        raise TypeError("values must be an iterable of strings") from exc
    for i, val in enumerate(raw_values):
        if not isinstance(val, str):
            raise TypeError(
                f"Bookmark value at index {i} is not a string "
                f"(got {type(val).__name__})"
            )
    return cls(raw_values)

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.
        """
        if values is None:
            values = []
        # Accept a single string as a single bookmark
        if isinstance(values, str):
            values = [values]
        # Ensure that the passed object is iterable and yields strings
        try:
            iterator = iter(values)
        except TypeError as exc:
            raise TypeError("values must be an iterable of strings") from exc

        instance = cls()
        for raw in iterator:
            if not isinstance(raw, str):
                raise TypeError(f"Bookmark values must be strings, got {type(raw).__name__}")
            # If the Bookmarks instance provides an add() method, use it.
            if hasattr(instance, "add") and callable(instance.add):
                instance.add(raw)
            # Otherwise try to use list.append() or similar.
            elif hasattr(instance, "append") and callable(instance.append):
                instance.append(raw)
            else:
                # Fallback: if still a collection that supports assignment
                try:
                    instance.append(raw)  # generic case
                except Exception as exc:
                    raise RuntimeError(f"Unable to add bookmark value {raw!r}") from exc
        return instance

def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError("values argument cannot be None")
        # Accept any iterable of strings (but not a single string)
        if isinstance(values, (str, bytes)):
            raise TypeError("values must be an iterable of strings, not a single string")
        try:
            raw_values = list(values)
        except TypeError:
            raise TypeError("values must be an iterable of strings")
        for v in raw_values:
            if not isinstance(v, str):
                raise TypeError(f"Bookmark value must be a string, got {type(v).__name__}")
        # If the Bookmarks constructor accepts an iterable of raw values, use it
        # otherwise create an empty instance and add manually using the `add` method.
        try:
            return cls(raw_values)
        except Exception:
            # Fallback: create instance and add bookmarks one by one
            bookmarks = cls()
            for v in raw_values:
                # strip whitespace and skip empty entries
                trimmed = v.strip()
                if trimmed:
                    if hasattr(bookmarks, "add"):
                        bookmarks.add(trimmed)
                    else:
                        # If no add method, try appending directly to an internal list if it exists
                        if hasattr(bookmarks, "_raw_values"):
                            bookmarks._raw_values.append(trimmed)
                        else:
                            raise
            return bookmarks

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # Name of the function implies we want to return a tuple
    # (sequence object, originating type). If *seq* is already a
    # list or tuple we return it unchanged.  For other iterables
    # we materialise them into a list.  If *seq* is None we return an
    # empty list and the type ``NoneType``.
    #
    # Parameters:
    #   seq      : an arbitrary object or iterable
    #   bufsize  : optional buffer size hint (currently unused)
    #
    # Returns:
    #   tuple (sequence, type)

    # Handle None explicitly
    if seq is None:
        return [], type(seq)

    # If it is already a list or tuple, return it unchanged
    if isinstance(seq, (list, tuple)):
        return seq, type(seq)

    # Try to materialise into a list
    try:
        seq_list = list(seq)
        return seq_list, type(seq)
    except Exception:
        # Not iterable, wrap it
        return [seq], type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """
    Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    # If seq is a string and a bufsize is given, interpret it as a file path.
    # This is a best‑effort heuristic: other code may rely on buffered reading
    if isinstance(seq, str) and bufsize is not None:
        try:
            # Use binary mode and the specified buffer size
            f = open(seq, 'rb', buffering=bufsize)
            return f, type(f)
        except IOError:
            # Fall back to treating the string as a normal sequence
            pass

    # Return the original if it is an iterable type (excludes str to avoid
    # treating a string as an iterable of characters; use type(seq) later)
    if isinstance(seq, (bytes, bytearray, list, tuple, set, frozenset)):
        return seq, type(seq)

    # For other iterable objects (generators etc.) we return as-is
    try:
        iter(seq)
        return seq, type(seq)
    except TypeError:
        # seq is not iterable – wrap it in a list
        return [seq], type(seq)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise TypeError("seq cannot be None")

    # We consider objects that implement the Sequence ABC as already
    # a sequence. This includes lists, tuples, strings, bytes, etc.
    try:
        from collections.abc import Sequence as _Sequence
    except Exception:  # pragma: no cover
        # Very old Python versions (prior to 3.3) don't have collections.abc.
        from collections import Sequence as _Sequence  # type: ignore

    if isinstance(seq, _Sequence):
        return seq, type(seq)

    # If the object is an iterator or generator, materialise it into a list.
    try:
        seq = list(seq)
        return seq, type(seq)
    except TypeError:
        raise TypeError(f"object of type {type(seq).__name__} is not a sequence")

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Attempt to import the specific exception if available
    try:
        from . import LenaValueError
    except Exception:
        class LenaValueError(ValueError):
            """Fallback exception for missing module."""
            pass

    # Helper to multiply values generically
    def _mult(value, factor):
        try:
            # NumPy array or similar supports element‑wise multiplication
            return value * factor
        except Exception:
            # Fall back to Python list/tuple handling
            if isinstance(value, (list, tuple)):
                return type(value)(_mult(v, factor) for v in value)
            # Scalar numeric
            return value * factor

    # Determine current scale attribute
    if hasattr(self, "scale"):
        current_scale = self.scale
    elif hasattr(self, "_scale"):
        current_scale = self._scale
    else:
        raise ValueError("Graph object has no scale attribute")

    if other is None:  # Getter
        return current_scale

    # Setter: other must be numeric
    if not isinstance(other, (int, float)):
        raise TypeError(f"Expected numeric `other`, got {type(other).__name__}")

    # Check for unknown or zero scale
    if current_scale is None or float(current_scale) == 0.0:
        raise LenaValueError("Cannot rescale graph with undefined or zero scale")

    factor = float(other) / float(current_scale)

    # Find all coordinate attributes (x, y, z or any other numeric attributes)
    coords = []
    for name in ("x", "y", "z"):
        if hasattr(self, name):
            coords.append(name)
    # If no standard coords, inspect all attributes for numeric types
    if not coords:
        for attr_name, attr_val in vars(self).items():
            if isinstance(attr_val, (int, float)):
                coords.append(attr_name)
    if not coords:
        raise ValueError("Could not identify any coordinate attributes to rescale")

    last_coord = coords[-1]
    # Rescale the coordinate
    try:
        current_val = getattr(self, last_coord)
        setattr(self, last_coord, _mult(current_val, factor))
    except Exception as exc:
        raise LenaValueError(f"Error rescaling coordinate '{last_coord}': {exc}") from exc

    # Rescale corresponding error attribute if present
    err_name = f"{last_coord}err"
    if hasattr(self, err_name):
        try:
            current_err = getattr(self, err_name)
            setattr(self, err_name, _mult(current_err, factor))
        except Exception as exc:
            raise LenaValueError(f"Error rescaling error '{err_name}': {exc}") from exc

    # Update the stored scale if it exists
    if hasattr(self, "scale"):
        self.scale = other
    elif hasattr(self, "_scale"):
        self._scale = other

    return self

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    import numbers

    # --------- Get current scale ----------------------------------------
    if other is None:
        # Return the current scale if it exists, otherwise None
        return getattr(self, 'scale', None)

    # --------- Validate input --------------------------------------------
    if not isinstance(other, numbers.Number):
        raise TypeError(f"Scale must be numeric, got {type(other).__name__}")

    # --------- Validate current scale ------------------------------------
    current_scale = getattr(self, 'scale', None)
    if current_scale is None or not isinstance(current_scale, numbers.Number):
        raise LenaValueError("Graph has unknown scale; cannot rescale.")
    if current_scale == 0:
        raise LenaValueError("Graph has zero scale; cannot rescale.")

    # --------- Compute scaling factor ------------------------------------
    try:
        factor = float(other) / float(current_scale)
    except Exception:
        raise ValueError("Could not compute scaling factor from provided scale.")

    # --------- Apply scaling to the last coordinate --------------------
    # Try common coordinate attribute names (x, y, z).
    coord_attrs = [attr for attr in ('x', 'y', 'z') if hasattr(self, attr)]
    if not coord_attrs:
        # Fall back to a generic 'data' or 'fields' attribute if present.
        if hasattr(self, 'fields') and isinstance(self.fields, (list, tuple)):
            last_field = self.fields[-1]
            # Assume the last field has a 'values' attribute that is a list/array.
            if hasattr(last_field, 'values'):
                try:
                    last_field.values = [v * factor for v in last_field.values]
                except Exception:
                    pass
            # If the field has an errors attribute, rescale it as well.
            if hasattr(last_field, 'errors'):
                try:
                    last_field.errors = [e * factor for e in last_field.errors]
                except Exception:
                    pass
            # Update the graph's scale and finish.
            setattr(self, 'scale', float(other))
            return
        else:
            raise AttributeError("No recognizable coordinate data to rescale.")

    last_coord = coord_attrs[-1]
    # Rescale the coordinate values
    try:
        original_value = getattr(self, last_coord)
        # Support both scalar and iterable types
        if isinstance(original_value, (list, tuple)):
            new_value = [v * factor for v in original_value]
        else:
            new_value = original_value * factor
        setattr(self, last_coord, new_value)
    except Exception as exc:
        raise RuntimeError(f"Failed to rescale {last_coord} coordinate: {exc}")

    # Rescale corresponding error attribute if present
    err_attr = f"{last_coord}_err"
    if hasattr(self, err_attr):
        try:
            original_err = getattr(self, err_attr)
            if isinstance(original_err, (list, tuple)):
                new_err = [e * factor for e in original_err]
            else:
                new_err = original_err * factor
            setattr(self, err_attr, new_err)
        except Exception:
            # ignore errors in rescaling error values; they are non-critical
            pass

    # Update the graph's recorded scale
    setattr(self, 'scale', float(other))

def scale(self, other=None):
    """Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    # Return current scale if nothing to set
    if other is None:
        return getattr(self, "scale", None)

    # Ensure *other* is numeric
    try:
        new_scale = float(other)
    except (TypeError, ValueError):
        raise TypeError("Scale value must be a number")

    current_scale = getattr(self, "scale", None)
    # If the current scale is unknown or zero, raise an error
    if current_scale is None or not isinstance(current_scale, (int, float)):
        raise LenaValueError("Graph has unknown scale")
    if current_scale == 0 or (isinstance(current_scale, float) and current_scale != current_scale):
        # also check for NaN
        raise LenaValueError("Graph has zero scale")

    # Compute the factor to apply to coordinates
    factor = new_scale / current_scale

    # Find the container that holds the coordinates.
    # The official implementation uses either .data or .coords.
    if hasattr(self, "data"):
        data_container = self.data
    elif hasattr(self, "coords"):
        data_container = self.coords
    else:
        raise AttributeError("Graph has no coordinate data to rescale")

    # Make sure we have points to work with
    if not data_container:
        raise ValueError("Coordinate data is empty")

    # Determine the index of the last coordinate for each point
    # We assume that each point is an iterable of coordinates
    try:
        last_idx = len(data_container[0]) - 1
    except (IndexError, TypeError):
        raise ValueError("Coordinate data is malformed")

    # Rescale the coordinates
    for idx, point in enumerate(data_container):
        try:
            new_point = list(point)
            new_point[last_idx] *= factor
            data_container[idx] = type(point)(new_point)
        except Exception:
            # If the point is not a mutable sequence, skip it
            continue

    # Also rescale any associated error values if present
    for err_attr in ("errors", "error"):
        if hasattr(self, err_attr):
            err_container = getattr(self, err_attr)
            try:
                for idx, err_point in enumerate(err_container):
                    try:
                        new_err = list(err_point)
                        new_err[last_idx] *= factor
                        err_container[idx] = type(err_point)(new_err)
                    except Exception:
                        continue
            except Exception:
                # If the error container is not iterable, ignore
                pass

    # Update the graph's scale
    self.scale = new_scale
    return self

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Validate get_coordinate argument
    if get_coordinate not in ("left", "right", "middle"):
        raise ValueError(
            f"get_coordinate must be 'left', 'right' or 'middle', got '{get_coordinate}'"
        )

    # Retrieve histogram edges and bin contents
    try:
        edges = hist.edges
    except AttributeError:
        try:
            edges = hist.bin_edges
        except AttributeError:
            raise AttributeError(
                "Histogram object must have an 'edges' or 'bin_edges' attribute"
            )

    try:
        bin_values = hist.bins
    except AttributeError:
        try:
            bin_values = hist.bin_contents
        except AttributeError:
            raise AttributeError(
                "Histogram object must have a 'bins' or 'bin_contents' attribute"
            )

    n_bins = len(bin_values)
    if len(edges) != n_bins + 1:
        raise ValueError(
            f"Expected {n_bins+1} edges for {n_bins} bins, got {len(edges)}"
        )

    # Prepare output points
    points = []
    for i in range(n_bins):
        left_edge = edges[i]
        right_edge = edges[i + 1]
        if get_coordinate == "left":
            coord = left_edge
        elif get_coordinate == "right":
            coord = right_edge
        else:  # middle
            coord = (left_edge + right_edge) / 2.0

        # Extract bin value, possibly using make_value
        content = bin_values[i]
        if make_value is not None:
            try:
                processed = make_value(content)
            except Exception as exc:
                raise ValueError(
                    f"make_value function raised an exception for bin {i}: {exc}"
                ) from exc
        else:
            processed = content

        # Build point tuple
        if isinstance(processed, (tuple, list)):
            point = (coord,) + tuple(processed)
        else:
            point = (coord, processed)

        points.append(point)

    # Determine graph scale
    graph_scale = None
    if scale is True:
        graph_scale = getattr(hist, "scale", None)
    elif scale is not None:
        graph_scale = scale

    # Create the graph object.  We assume a Graph class is available
    # in the current namespace with a suitable initializer.
    try:
        graph = Graph(points=points, field_names=field_names, scale=graph_scale)
    except Exception as exc:
        # Fallback: return a simple dict if Graph is not available
        graph = {
            "points": points,
            "field_names": field_names,
            "scale": graph_scale,
        }
    return graph

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Determine iterable of bins
    if hasattr(hist, "bins"):
        bins = hist.bins
    elif hasattr(hist, "__iter__"):
        bins = hist
    else:
        raise TypeError("Provided histogram does not expose bins or is not iterable")

    points = []

    # Helper to get bin coordinate
    def _get_bin_coord(bin_obj, coord_type):
        left = None
        right = None
        if hasattr(bin_obj, "left") and hasattr(bin_obj, "right"):
            left = bin_obj.left
            right = bin_obj.right
        elif hasattr(bin_obj, "edges"):
            edges = bin_obj.edges
            if len(edges) >= 2:
                left, right = edges[0], edges[-1]
        if left is None or right is None:
            raise AttributeError(f"Bin object {bin_obj} lacks left/right edges")
        if coord_type == "left":
            return left
        if coord_type == "right":
            return right
        if coord_type == "middle":
            return (left + right) / 2.0
        raise ValueError(f"Invalid get_coordinate value: {coord_type}")

    for bin_obj in bins:
        coord = _get_bin_coord(bin_obj, get_coordinate)

        # Get bin content/value
        bin_value = None
        if make_value is None:
            # Try common attribute names for content
            if hasattr(bin_obj, "content"):
                bin_value = bin_obj.content
            elif hasattr(bin_obj, "value"):
                bin_value = bin_obj.value
            else:
                # Assume bin_obj itself is the numeric value
                bin_value = bin_obj
        else:
            # If make_value expects the raw bin value, provide it
            if hasattr(bin_obj, "content"):
                raw_val = bin_obj.content
            elif hasattr(bin_obj, "value"):
                raw_val = bin_obj.value
            else:
                raw_val = bin_obj
            bin_value = make_value(raw_val)

        # Ensure bin_value is iterable if more than one field is expected
        if isinstance(bin_value, (list, tuple)):
            value_tup = tuple(bin_value)
        else:
            value_tup = (bin_value,)

        if len(field_names) - 1 != len(value_tup):
            raise ValueError(
                f"Number of fields in field_names ({len(field_names) - 1}) "
                f"does not match number of values from make_value ({len(value_tup)})")

        point = {field_names[0]: coord}
        for fn, v in zip(field_names[1:], value_tup):
            point[fn] = v
        points.append(point)

    # Resolve scale
    if scale is True:
        scale = getattr(hist, "scale", None)
    elif scale is None:
        scale = getattr(hist, "scale", None)

    # Simple graph container class
    class Graph:
        def __init__(self, fields, pts, scl=None):
            self.fields = fields
            self.points = pts
            self.scale = scl

        def __iter__(self):
            return iter(self.points)

        def __len__(self):
            return len(self.points)

        def __repr__(self):
            return f"<Graph fields={self.fields} size={len(self.points)}>"

    return Graph(field_names, points, scale)

def _verify(iface, candidate, tentative=False, vtype=None):
        """Verify that *candidate* might correctly provide *iface*.

        This involves:

        - Making sure the candidate claims that it provides the
          interface using ``iface.providedBy`` (unless *tentative* is `True`,
          in which case this step is skipped). This means that the candidate's class
          declares that it `implements <zope.interface.implementer>` the interface,
          or the candidate itself declares that it `provides <zope.interface.provider>`
          the interface

        - Making sure the candidate defines all the necessary methods

        - Making sure the methods have the correct signature (to the
          extent possible)

        - Making sure the candidate defines all the necessary attributes

        :return bool: Returns a true value if everything that could be
           checked passed.
        :raises zope.interface.Invalid: If any of the previous
           conditions does not hold.

        .. versionchanged:: 5.0
            If multiple methods or attributes are invalid, all such errors
            are collected and reported. Previously, only the first error was reported.
            As a special case, if only one such error is present, it is raised
            alone, like before.
        """
        from zope.interface import Invalid
        import inspect

        errors = []

        # 1. Check that the candidate claims to provide the interface
        if not tentative:
            try:
                if not iface.providedBy(candidate):
                    errors.append(f"Candidate {candidate!r} does not provide interface {iface.__name__}")
            except Exception as exc:
                errors.append(f"Error checking providedBy: {exc}")

        # Helper to compare signatures
        def signatures_match(sig1, sig2):
            if len(sig1.parameters) != len(sig2.parameters):
                return False
            for p1, p2 in zip(sig1.parameters.values(), sig2.parameters.values()):
                if p1.name != p2.name or p1.kind != p2.kind:
                    return False
            return True

        # 2. Examine all interface attributes and methods
        for name in getattr(iface, "names", lambda: ())():
            if name.startswith("_"):
                continue
            try:
                attr = getattr(iface, name)
            except Exception:
                continue
            # Use zope.interface's Attribute vs Method detection
            is_callable = callable(attr)
            if is_callable:
                # Method: check presence and signature
                if not hasattr(candidate, name):
                    errors.append(f"Missing method {name}")
                else:
                    cand_method = getattr(candidate, name)
                    try:
                        iface_sig = inspect.signature(attr)
                        cand_sig = inspect.signature(cand_method)
                        if not signatures_match(iface_sig, cand_sig):
                            errors.append(f"Signature mismatch for method {name}: "
                                           f"interface {iface_sig} vs candidate {cand_sig}")
                    except Exception as exc:
                        errors.append(f"Error inspecting signatures for {name}: {exc}")
            else:
                # Attribute: check presence
                if not hasattr(candidate, name):
                    errors.append(f"Missing attribute {name}")

        # 3. If vtype is specified, ensure that candidate attributes of that kind exist
        if vtype is not None:
            # Here we assume vtype is a type or interface; check membership
            try:
                if not isinstance(candidate, vtype):
                    errors.append(f"Candidate {candidate!r} is not of expected type {vtype}")
            except Exception as exc:
                errors.append(f"Error checking vtype {vtype} against candidate: {exc}")

        # 4. Raise aggregated errors if any
        if errors:
            if len(errors) == 1:
                raise Invalid(errors[0])
            raise Invalid("; ".join(errors))

        return True

def verifyObject(iface, candidate, tentative=False):
        """
        Verify that *candidate* might correctly provide *iface*.

        This involves:

        - Making sure the candidate claims that it provides the
          interface using ``iface.providedBy`` (unless *tentative* is `True`,
          in which case this step is skipped). This means that the candidate's class
          declares that it `implements <zope.interface.implementer>` the interface,
          or the candidate itself declares that it `provides <zope.interface.provider>`
          the interface

        - Making sure the candidate defines all the necessary methods

        - Making sure the methods have the correct signature (to the
          extent possible)

        - Making sure the candidate defines all the necessary attributes

        :return bool: Returns a true value if everything that could be
        checked passed.
        :raises zope.interface.Invalid: If any of the previous
        conditions does not hold.

        .. versionchanged:: 5.0
            If multiple methods or attributes are invalid, all such errors
            are collected and reported. Previously, only the first error was reported.
            As a special case, if only one such error is present, it is raised
            alone, like before.
        """
        import inspect
        from zope.interface import Invalid

        errors = []

        # 1. Check the interface declaration
        if not tentative:
            try:
                if not iface.providedBy(candidate):
                    errors.append("Candidate does not declare that it provides interface %s." % iface.__name__)
            except Exception as exc:
                errors.append("Error checking provides: %s" % exc)

        # Helper to compare signatures roughly
        def signatures_match(iface_sig, candidate_sig):
            # Convert both to list of positional params (excluding * and **)
            iface_params = [p for p in iface_sig.parameters.values()
                            if p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD,
                                      inspect.Parameter.POSITIONAL_ONLY,
                                      inspect.Parameter.ARGS)]
            cand_params = [p for p in candidate_sig.parameters.values()
                            if p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD,
                                      inspect.Parameter.POSITIONAL_ONLY,
                                      inspect.Parameter.ARGS)]

            # Interface methods include 'self' as first param; candidate bound methods omit it
            # Treat mismatch by checking lengths after dropping the first param of iface
            if iface_params and iface_params[0].name == 'self':
                iface_params = iface_params[1:]

            return len(iface_params) == len(cand_params)

        # 2. Check methods
        try:
            iface_methods = getattr(iface, 'methods', lambda: [])()
        except Exception:
            iface_methods = []

        for m in iface_methods:
            name = m.__name__
            if not hasattr(candidate, name):
                errors.append("Missing method '%s' required by interface %s." % (name, iface.__name__))
                continue
            cand_attr = getattr(candidate, name)
            if not callable(cand_attr):
                errors.append("Attribute '%s' exists but is not callable as required by interface %s." % (name, iface.__name__))
                continue
            try:
                iface_sig = inspect.signature(m)
            except Exception:
                iface_sig = None
            try:
                cand_sig = inspect.signature(cand_attr)
            except Exception:
                cand_sig = None
            if iface_sig and cand_sig:
                if not signatures_match(iface_sig, cand_sig):
                    errors.append("Signature of method '%s' does not match interface %s." % (name, iface.__name__))

        # 3. Check attributes
        try:
            iface_attrs = getattr(iface, 'attributes', lambda: [])()
        except Exception:
            iface_attrs = []

        for a in iface_attrs:
            name = a.__name__
            if not hasattr(candidate, name):
                errors.append("Missing attribute '%s' required by interface %s." % (name, iface.__name__))

        # Raise collected errors or return True
        if errors:
            if len(errors) == 1:
                raise Invalid(errors[0])
            else:
                raise Invalid("Multiple interface errors: " + "; ".join(errors))
        return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    import inspect
    try:
        from zope.interface import Invalid
    except Exception:
        # Fallback: if zope.interface is not available, raise a generic exception
        raise RuntimeError("zope.interface is required for verifyObject")

    errors = []

    # Step 1: interface provision check (unless tentative)
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                errors.append(f"Candidate does not provide interface '{iface.__name__}'")
        except Exception as e:
            errors.append(f"Unable to evaluate providedBy for candidate: {e}")

    # Helper to get interface attributes and methods in a robust way
    def _get_iface_attrs(iface_obj):
        try:
            return iface_obj.getRequiredAttributes()
        except Exception:
            # Fallback: introspect the interface class for members that are not special
            return [
                name
                for name, obj in vars(iface_obj).items()
                if not name.startswith("_") and
                not inspect.isroutine(obj) and
                not isinstance(obj, property)
            ]

    def _get_iface_methods(iface_obj):
        try:
            return iface_obj.getRequiredMethods()
        except Exception:
            # Fallback: members that are callables
            return {
                name: getattr(iface_obj, name)
                for name, obj in vars(iface_obj).items()
                if not name.startswith("_") and inspect.isroutine(obj)
            }

    # Step 2: Attribute checks
    required_attrs = _get_iface_attrs(iface)
    for attr in required_attrs:
        if not hasattr(candidate, attr):
            errors.append(f"Missing required attribute '{attr}'")

    # Step 3: Method checks
    required_methods = _get_iface_methods(iface)
    for name, iface_sig in required_methods.items():
        if not hasattr(candidate, name):
            errors.append(f"Missing required method '{name}'")
            continue

        cand_obj = getattr(candidate, name)
        # For interface method, iface_sig may be a function object; introspect its signature
        try:
            iface_sig_obj = iface_sig if inspect.isroutine(iface_sig) else None
            iface_signature = inspect.signature(iface_sig_obj) if iface_sig_obj else None
        except Exception:
            iface_signature = None

        try:
            cand_signature = inspect.signature(cand_obj)
        except Exception:
            errors.append(f"Cannot inspect signature of candidate method '{name}'")
            continue

        # Compare parameter lists if interface signature was available
        if iface_signature is not None:
            iface_params = list(iface_signature.parameters.values())
            cand_params = list(cand_signature.parameters.values())
            if iface_params != cand_params:
                errors.append(
                    f"Signature mismatch for method '{name}': "
                    f"expected {iface_params}, got {cand_params}"
                )

    # Report errors
    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid("\n".join(errors))

    return True

