def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    try:
        if candidate is None:
            return False

        # If iface is a class type, use isinstance/issubclass
        if isinstance(iface, type):
            if isinstance(candidate, iface):
                return True
            if isinstance(candidate, type):
                return issubclass(candidate, iface)

        # If interface defines abstract methods (e.g., an ABC)
        if hasattr(iface, "__abstractmethods__"):
            for name in getattr(iface, "__abstractmethods__"):
                if not hasattr(candidate, name):
                    return False
            return True

        # If iface is an iterable of attribute names
        if isinstance(iface, (list, tuple, set)):
            for name in iface:
                if not hasattr(candidate, name):
                    return False
            return True

        # Fallback: inspect attributes of iface that are callables
        attrs = [
            attr
            for attr in dir(iface)
            if not attr.startswith("_") and callable(getattr(iface, attr, None))
        ]
        for name in attrs:
            if not hasattr(candidate, name):
                return False
        return True

    except Exception:
        if tentative:
            return False
        raise

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Validate input
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a list or tuple of base classes")
    for b in bases:
        if not isinstance(b, type):
            raise TypeError("base %r is not a class" % b)

    # Collect all metaclasses from bases
    metaclasses = set(type(b) for b in bases)

    # Include explicit metaclass if provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass %r is not a class" % explicit_mc)
        metaclasses.add(explicit_mc)

    # If no metaclasses found, default to the built‑in metaclass 'type'
    if not metaclasses:
        return type

    # Find the most derived metaclass that is a subclass of all others
    candidate = None
    for m in metaclasses:
        if all(issubclass(m, other) for other in metaclasses):
            if candidate is None:
                candidate = m
            else:
                # More than one candidate, ambiguous
                raise TypeError("Metaclass conflict: multiple candidates %r and %r" % (candidate, m))

    if candidate is None:
        raise TypeError("Metaclass conflict: no common metaclass for %r" % (metaclasses,))

    return candidate

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # If an explicit metaclass is provided, use it directly.
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit __metaclass__ must be a type")
        return explicit_mc

    # No bases means the default metaclass is `type`.
    if not bases:
        return type

    # Try to let Python compute the appropriate metaclass by creating a dummy
    # class that uses the specified bases. The metaclass of this dummy
    # class is the one that Python would choose.
    try:
        dummy = type('tmp', bases, {})
