    except TypeError as exc:
        # Fallback: manually find the most derived metaclass that is a
        # subclass of all base metaclasses.
        metaclasses = [type(b) for b in bases]

        # Start with the most general meta
        candidate = type
        for mc in metaclasses:
            if mc is candidate or issubclass(mc, candidate):
                candidate = mc
            elif not issubclass(candidate, mc):
