def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    if not isinstance(bases, (list, tuple)):
        raise TypeError("bases must be a sequence of classes")
    if not bases:
        # Default to 'type' if no bases are provided
        return type
    # Validate all bases are classes
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f"Base {base!r} is not a class")
    # Start with the metaclass of the first base
    chosen = type(bases[0])
    # Helper to find common superclass of two metaclasses
    def _common_metaclass(a, b):
        for cls in a.mro():
            if cls in b.mro():
                return cls
