    # Resolve conflicts among the base metaclasses
    for base in bases[1:]:
        base_meta = type(base)
        if chosen is base_meta:
            continue
        if issubclass(chosen, base_meta):
            continue
        if issubclass(base_meta, chosen):
            chosen = base_meta
            continue
        common = _common_metaclass(chosen, base_meta)
        if common is None:
            raise TypeError(f"metaclass conflict: {chosen.__name__} & {base_meta.__name__}")
        chosen = common
    # If an explicit metaclass was supplied, it takes precedence
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError("explicit metaclass must be a class")
        # Ensure compatibility with the metaclasses derived from the bases
        for base in bases:
            base_meta = type(base)
            if not (issubclass(explicit_mc, base_meta) or issubclass(base_meta, explicit_mc)):
                raise TypeError(
                    f"explicit metaclass {explicit_mc.__name__} is not compatible"
                    f" with base metaclass {base_meta.__name__}"
                )
        chosen = explicit_mc
    return chosen

