def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    """Find tags in text.

    Tries to ignore tags inside code blocks.

    Optionally, if passed a "replacer", will also replace the tag word with the result
    of the replacer function called with the tag word.

    Returns a set of tags and the original or replaced text.
    """
    import re
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Regex to find fenced code blocks and inline code spans
    code_pattern = re.compile(r'(```.*?```|`[^`]*`)', re.DOTALL)
    spans = [(m.start(), m.end()) for m in code_pattern.finditer(text)]

    def in_code(pos: int) -> bool:
        """Return True if position is inside one of the code spans."""
        for start, end in spans:
            if start <= pos < end:
                return True
        return False

    tags = set()
    tag_pattern = re.compile(r'#(\w+)')

    def replacer_func(match: re.Match) -> str:
        start = match.start()
        if in_code(start):
            # Leave tags inside code blocks unchanged
            return match.group(0)
        tag = match.group(1)
        tags.add(tag)
        if callable(replacer):
            return replacer(tag)
        return match.group(0)

    replaced_text = tag_pattern.sub(replacer_func, text)
    return tags, replaced_text

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    if not isinstance(text, str):
        raise TypeError(f"text must be a str instance, got {type(text).__name__}")
    if not text:
        return text

    # Use the regex module via __import__ to avoid top-level imports
    try:
        re = __import__('re')
    except Exception as exc:
        raise RuntimeError("Failed to import the 're' module.") from exc

    # Patterns for markdown links [text](url) and plain URLs
    md_pattern = re.compile(r'\[([^\]]+)\]\((https?://[^\)]+)\)', flags=re.IGNORECASE)
    url_pattern = re.compile(r'(?i)\b((?:https?://|ftp://|www\.)[^\s<]+)', flags=re.IGNORECASE)

    def _make_link(match, href_attr=None, link_text=None):
        """Internal helper to construct an <a> tag with target and rel attributes."""
        href = href_attr if href_attr else match.group(0)
        if not href.startswith(('http://', 'https://', 'ftp://')):
            href = 'http://' + href
        display = link_text if link_text is not None else match.group(0)
        return f'<a href="{href}" target="_blank" rel="noopener">{display}</a>'

    # Replace markdown links first to avoid double replacement
    try:
        processed = md_pattern.sub(lambda m: _make_link(m, href_attr=m.group(2), link_text=m.group(1)), text)
    except re.error as e:
        raise ValueError(f"Markdown regex error: {e}") from e

    # Replace any remaining plain URLs
    try:
        processed = url_pattern.sub(lambda m: _make_link(m), processed)
    except re.error as e:
        raise ValueError(f"URL regex error: {e}") from e

    return processed

def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re
    if text is None:
        return ""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    # Regular expression to match URLs starting with http/https/ftp or www.
    url_pattern = re.compile(
        r'\b(?:(https?://|ftp://|www\.)[^\s<]+)',
        re.IGNORECASE
    )
    def _replace(match):
        prefix, url = match.group(1), match.group(0)
        # Ensure the href has a proper scheme
        href = url
        if url.lower().startswith('www.'):
            href = 'http://' + url
        return f'<a href="{href}" target="_blank" rel="noopener noreferrer" class="linkified">{url}</a>'
    return url_pattern.sub(_replace, text)

