def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    if not isinstance(url, str):
        raise TypeError("url must be a string")

    try:
        import requests
    except Exception:
        return None

    try:
        # Perform a HEAD request; follow redirects with a reasonable timeout
        response = requests.head(url, allow_redirects=True, timeout=5)
        # Some servers may not allow HEAD; fall back to GET if HEAD fails
        if response.status_code in {405, 500, 502, 503}:
            response = requests.get(url, stream=True, timeout=5)
        content_type = response.headers.get("Content-Type")
        return content_type if content_type is not None else None
    except Exception:
        return None

