def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        import urllib.request
        import urllib.parse
        from urllib.error import URLError, HTTPError

        # Normalize handle: ensure it contains a '@'
        if '@' not in handle:
            return None
        # Ensure resource is prefixed with 'acct:'
        resource = handle if handle.lower().startswith('acct:') else f'acct:{handle}'
        domain = handle.split('@', 1)[1]
        # Build the webfinger URL
        query = urllib.parse.urlencode({'resource': resource})
        url = f'https://{domain}/.well-known/webfinger?{query}'

        # Prepare the request with appropriate headers
        req = urllib.request.Request(
            url,
            headers={'Accept': 'application/jrd+json, application/json;q=0.9'}
        )
        # Try HTTPS first, but if SSL certificate verification fails, fallback to disabling verification
        try:
            with urllib.request.urlopen(req, timeout=5) as resp:
                if 200 <= resp.status < 300:
                    return resp.read().decode('utf-8')
        except HTTPError as e:
            # If the server returns a 404 or other HTTP error, just ignore and return None
            if e.code == 404:
                return None
            # For other HTTP errors, also return None
            return None
        except URLError as e:
            # If there's a URL error (e.g., DNS resolution failure), return None
            return None
        except Exception:
            return None
    except Exception:
        # Any import error or unexpected failure should result in None
        return None

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
