def retrieve_and_parse_diaspora_webfinger(handle):
    """Retrieve a and parse a remote Diaspora webfinger document.

    :arg handle: Remote handle to retrieve
    :returns: dict
    """
    try:
        # Accept handle in form 'local@domain' or 'acct:local@domain'
        if handle.startswith('acct:'):
            handle = handle[5:]
        if '@' not in handle:
            raise ValueError(f"Invalid handle '{handle}'. Expected 'user@domain'.")
        local, domain = handle.split('@', 1)
        if not domain:
            raise ValueError(f"Invalid handle '{handle}'. Domain part missing.")

        url = f"https://{domain}/.well-known/webfinger?resource=acct:{handle}"
        import requests  # local import to keep function self‑contained
        response = requests.get(url, timeout=10)
    except Exception as exc:
