def retrieve_diaspora_host_meta(host):
    """Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import ssl
    import xml.etree.ElementTree as ET

    # Normalize host to just hostname (strip scheme if present)
    if host.startswith("http://"):
        host = host[len("http://") :]
    elif host.startswith("https://"):
        host = host[len("https://") :]

    # Construct the URL; attempt HTTPS first
    base_url = f"https://{host}/.well-known/host-meta"

    # Helper to fetch from a given URL
    def _fetch(url):
        context = ssl.create_default_context()
        with urllib.request.urlopen(url, context=context, timeout=10) as resp:
            if resp.status != 200:
                raise RuntimeError(
                    f"Failed to retrieve host-meta from {host}: HTTP {resp.status}"
                )
            return resp.read()

    # Try HTTPS, fall back to HTTP if SSL errors occur
    try:
        data = _fetch(base_url)
    except (urllib.error.URLError, ssl.SSLError):
        # Try plain HTTP
        try:
            data = _fetch(f"http://{host}/.well-known/host-meta")
        except urllib.error.HTTPError as e:
            raise RuntimeError(
                f"HTTP error retrieving host-meta from {host}: {e}"
            ) from e
        except urllib.error.URLError as e:
            raise RuntimeError(
                f"URL error retrieving host-meta from {host}: {e}"
            ) from e

    # Parse the XML into an ElementTree element
    try:
        root = ET.fromstring(data)
    except ET.ParseError as e:
        raise ValueError(f"Failed to parse host-meta XML from {host}") from e

    # Some libraries expect an XRD class instance; if such exists we
    # wrap the ElementTree element accordingly, otherwise return the
    # ElementTree root directly.
    try:
        from xrd import XRD  # type: ignore
        return XRD(root)
    except Exception:  # pragma: no cover
        return root

def retrieve_diaspora_host_meta(host):
    """
    Retrieve a remote Diaspora host-meta document.

    :arg host: Host to retrieve from
    :returns: ``XRD`` instance
    """
    import urllib.request
    import urllib.error
    import xml.etree.ElementTree as ET

    # Normalise host: strip scheme if present
    if host.startswith(("http://", "https://")):
        host = host.split("://", 1)[1]
    # Construct the possible URLs for host-meta
    urls = [f"https://{host}/.well-known/host-meta",
            f"http://{host}/.well-known/host-meta",
            f"https://{host}/.well-known/nodeinfo",
            f"http://{host}/.well-known/nodeinfo"]
    for url in urls:
        try:
            with urllib.request.urlopen(url, timeout=10) as response:
                data = response.read()
                if data:
                    break
        except (urllib.error.HTTPError, urllib.error.URLError):
            continue
    else:
        # If none succeeded, raise an error
        raise ValueError(f"Could not retrieve host-meta for {host}")

    # A simple XRD wrapper that holds the XML root
    class XRD:
        def __init__(self, root):
            self.root = root

        @classmethod
        def fromstring(cls, xml_bytes):
            """
            Create an XRD instance from an XML bytes string.
            """
            try:
                root = ET.fromstring(xml_bytes)
            except ET.ParseError as exc:
                raise ValueError("Invalid XML received for host-meta") from exc
            return cls(root)

        def __repr__(self):
            return f"<XRD object at {hex(id(self))} root_tag={self.root.tag}>"

    return XRD.fromstring(data)

