def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError("dic must be a dictionary")
    if key is None:
        raise ValueError("key cannot be None")

    # Build the full chain of keys. If key is a list/tuple and no other keys are supplied,
    # treat it as the full key chain.
    if isinstance(key, (list, tuple)) and not keys:
        chain = list(key)
    else:
        chain = [key] + list(keys)

    if not chain:
        raise ValueError("no key specified")

    current = dic
    for idx, k in enumerate(chain):
        if not isinstance(k, str):
            raise TypeError(f"key must be a string, got {type(k).__name__}")
        if idx == len(chain) - 1:
            current[k] = val
        else:
            if k not in current or not isinstance(current[k], dict):
                current[k] = {}
            current = current[k]
    return dic

def dict_insert(dic, val, key, *keys):
    """insert a value of a nested key into a dictionary

    to insert value for a nested key, all ancestor keys should be given as
    method's arguments

    example:
      dict_insert({}, 'val', 'key1.key2'.split('.'))

    :param dic: a dictionary object to insert the nested key value into
    :param val: a value to insert to the given dictionary
    :param key: first key in a chain of key that will store the value
    :param keys: sub keys in the keys chain
    """
    if not isinstance(dic, dict):
        raise TypeError(f"dic must be a dict, got {type(dic).__name__}")
    # Build a flat list of keys
    chain = []
    if isinstance(key, (list, tuple)) and all(isinstance(k, str) for k in key):
        chain.extend(key)
    else:
        chain.append(key)
    if keys:
        chain.extend(keys)
    if not chain:
        raise ValueError("At least one key must be provided")
    # Navigate/construct nested dicts
    current = dic
    for idx, k in enumerate(chain):
        if not isinstance(k, str):
            raise TypeError(f"Key must be a string, got {type(k).__name__} at position {idx}")
        if idx == len(chain) - 1:
            # final key: set value
            current[k] = val
        else:
            # intermediate key: ensure dict
            if k not in current:
                current[k] = {}
            elif not isinstance(current[k], dict):
                raise TypeError(f"Expected dict at key '{k}', got {type(current[k]).__name__}")
            current = current[k]
    return dic

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch
    import warnings

    # Validate input types
    if not isinstance(settings_dirs, (list, tuple)):
        raise TypeError("settings_dirs must be a list or tuple of directory paths")
    if spec_option is not None and not isinstance(spec_option, str):
        raise TypeError("spec_option must be a string or None")

    file_names = []

    for dir_path in settings_dirs:
        if not isinstance(dir_path, str):
            warnings.warn(f"Directory path {dir_path!r} is not a string, skipping.")
            continue

        if not os.path.isdir(dir_path):
            warnings.warn(f"Directory {dir_path!r} does not exist, skipping.")
            continue

        for root, _, files in os.walk(dir_path):
            for filename in files:
                if spec_option:
                    # Support simple patterns like '*.ini' or specific extensions like '.ini'
                    if fnmatch.fnmatch(filename, spec_option) or filename.endswith(spec_option):
                        file_names.append(os.path.join(root, filename))
                else:
                    file_names.append(os.path.join(root, filename))

    return file_names

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    # Normalize settings_dirs to a list
    if settings_dirs is None:
        dirs = []
    elif isinstance(settings_dirs, (str, bytes)):
        dirs = [settings_dirs]
    elif isinstance(settings_dirs, (list, tuple)):
        dirs = list(settings_dirs)
    else:
        raise TypeError(f"settings_dirs must be a str or a list/tuple of strings, got {type(settings_dirs).__name__}")

    # Ensure spec_option is a string; if None treat as wildcard
    if spec_option is None:
        pattern = '*'
    else:
        if not isinstance(spec_option, (str, bytes)):
            raise TypeError(f"spec_option must be a string or None, got {type(spec_option).__name__}")
        pattern = str(spec_option)

    result = []
    for d in dirs:
        if not isinstance(d, str):
            continue
        if not os.path.isdir(d):
            # Skip non-existent directories but don't raise
            continue
        try:
            for root, _, files in os.walk(d):
                for fn in files:
                    if fnmatch.fnmatch(fn, pattern):
                        result.append(os.path.join(root, fn))
        except OSError:
            # Ignore errors reading this directory
            continue

    # Return a sorted list for reproducibility
    return sorted(result)

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os
    import fnmatch

    if not isinstance(settings_dirs, (list, tuple)):
