def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    import os
    import pathlib
    import configparser

    # Use a cached config manager if available
    if hasattr(cls, "_ansible_config_manager"):
        return getattr(cls, "_ansible_config_manager")

    # Determine config file path
    # Priority: ANSIBLE_CONFIG env var, then default ~/.ansible.cfg
    cfg_path = None
    env_cfg = os.getenv("ANSIBLE_CONFIG")
    if env_cfg:
        cfg_path = pathlib.Path(env_cfg).expanduser()
    else:
        cfg_path = pathlib.Path("~/.ansible.cfg").expanduser()

    # Load config if file exists
    if cfg_path and cfg_path.is_file():
        parser = configparser.ConfigParser()
        try:
            parser.read(cfg_path)
        except Exception:
            parser = None
    else:
        parser = None

    # Cache and return
    setattr(cls, "_ansible_config_manager", parser)
    return parser

def ansible_config_manager(cls):
    """Gets the ansible config manager. """
    # Try to use Ansible's internal configuration manager first
    try:
        from ansible.constants import GLOBAL_OPTS
    except Exception:
        # Fall back to reading the ansible configuration file manually.
        # Determine the path to the configuration file
        try:
            import os
            from configparser import ConfigParser
        except Exception:
            try:
                # Python 2 fallback
                import os
                from ConfigParser import ConfigParser
            except Exception:
                # If we can't import ConfigParser at all, return an empty dict
                return {}
        cfg_path = os.getenv('ANSIBLE_CONFIG')
        if not cfg_path:
            # Default to $HOME/.ansible.cfg
            cfg_path = os.path.join(os.path.expanduser('~'), '.ansible.cfg')
        parser = ConfigParser()
        if os.path.exists(cfg_path):
            try:
                parser.read(cfg_path)
            except Exception:
                # If the file cannot be read, treat it as empty
                pass
        return parser
    else:
        # GLOBAL_OPTS is a dictionary containing the resolved configuration
        return GLOBAL_OPTS

