def _include_groups(self, parser_dict):
        """Resolves the include dict directive in the spec files. """
        # Basic type checking
        if not isinstance(parser_dict, dict):
            raise TypeError("parser_dict must be a dictionary")

        # Extract and remove the include directive if present
        includes = parser_dict.pop("include_groups", None)
        if not includes:
            # Nothing to include – just return the original dict
            return parser_dict

        # Normalise includes to a list
        if isinstance(includes, (str, bytes)):
            includes = [includes]
        elif isinstance(includes, (list, tuple)):
            includes = list(includes)
        else:
            raise TypeError(
                "include_groups must be a string, list or tuple of strings"
            )

        # Verify that a 'groups' section exists and is a dict
        groups_section = parser_dict.get("groups", {})
        if not isinstance(groups_section, dict):
            raise TypeError("'groups' entry must be a dictionary if 'include_groups' is used")

        # Merge the requested groups
        merged_groups = {}
        for grp_name in includes:
            if not isinstance(grp_name, (str, bytes)):
                raise TypeError(f"Group name {grp_name!r} must be a string")
            if grp_name not in groups_section:
                raise KeyError(f"Included group '{grp_name}' not found in 'groups'")
            group_def = groups_section[grp_name]
            if not isinstance(group_def, dict):
                # Skip non-dict definitions – perhaps a warning is warranted
                continue
            merged_groups.update(group_def)

        # Store the merged groups under a new key, preserving original data
        parser_dict["resolved_groups"] = merged_groups

        # Optionally remove the original 'groups' key if it is no longer needed
        # parser_dict.pop("groups", None)

        return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    # The include directive is expected to be a key named '_include_' or 'include'
    # that holds a mapping of groups that should be merged into the current spec.
    # This method processes such directives recursively and returns a new dict
    # with all includes resolved.  It raises a ValueError if the directive is
    # malformed or if a circular include is detected.
    #
    # Example:
    #   {'_include_': {'group1': {...}}, 'group2': {...}}
    # becomes:
    #   {'group1': {...}, 'group2': {...}}

    seen_keys = set()

    def _resolve(d):
        if not isinstance(d, dict):
            return d

        # Create a copy to avoid mutating the input
        result = {}
        for key, value in d.items():
            # Check for include directive (case-insensitive)
            if key.lower() in ('_include_', 'include'):
                # The value must be a mapping
                if not isinstance(value, dict):
                    raise ValueError(
                        f"Include directive must contain a dictionary; got {type(value).__name__}"
                    )
                # Detect circular includes by checking object identity
                inc_id = id(value)
                if inc_id in seen_keys:
                    raise ValueError("Circular include detected in spec")
                seen_keys.add(inc_id)
                inc_resolved = _resolve(value)
                seen_keys.remove(inc_id)
                # Merge included groups into the current result
                for inc_key, inc_val in inc_resolved.items():
                    if inc_key in result:
                        # Skip overriding existing keys; alternatively raise an error
                        continue
                    result[inc_key] = inc_val
            else:
                # For all other keys, recurse if the value is a mapping
                result[key] = _resolve(value)
        return result

    # Resolve the top-level parser_dict
    return _resolve(parser_dict)

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    spec = getattr(self, "spec", None)
    if not isinstance(spec, dict):
        # No spec available or not a dict – nothing to resolve
        return defaults
    try:
        for key, props in spec.items():
            if not isinstance(props, dict):
                continue
            # Store the default if defined
            if "default" in props:
                # Only set the attribute if it hasn't been set yet
                if getattr(self, key, None) is None:
                    setattr(self, key, props["default"])
                defaults[key] = getattr(self, key)
    except Exception as e:
        # Catch unexpected errors from spec processing
        raise ValueError(
            f"Failed to resolve defaults from spec: {e}"
        ) from e
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Ensure the spec attribute exists and is a dictionary
    if not hasattr(self, "spec") or not isinstance(self.spec, dict):
        raise AttributeError("Instance has no valid 'spec' attribute")

    for arg_name, arg_opts in self.spec.items():
        if not isinstance(arg_opts, dict):
            continue  # skip malformed entries

        # Start with the explicit default, if any
        value = arg_opts.get("default")

        # Override with an environment variable if specified
        env_var = arg_opts.get("env")
        if env_var:
            try:
                env_val = os.getenv(env_var) if "os" in globals() else None
                if env_val is not None:
                    value = env_val
            except Exception:
                pass  # ignore any unexpected environment lookup errors

        # Override with a config value if specified and available
        config_key = arg_opts.get("config")
        if config_key and hasattr(self, "config") and isinstance(self.config, dict):
            if config_key in self.config:
                value = self.config[config_key]

        defaults[arg_name] = value

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    try:
        defaults = {}
        # If the instance doesn't have a spec attribute, nothing to resolve.
        if not hasattr(self, "spec"):
            return defaults
        spec = getattr(self, "spec")
        # The spec should provide an iterable of argument definitions. They might be dicts
        # or simple objects with name and default attributes.
        args = getattr(spec, "arguments", None) or getattr(spec, "args", None) or []
        # Normalize args to a list if it isn't already.
        if not isinstance(args, list):
            try:
                args = list(args)
            except Exception:
                args = []
        for arg_def in args:
            # Extract the argument name.
            if isinstance(arg_def, dict):
                name = arg_def.get("name")
                default_val = arg_def.get("default")
            else:
                name = getattr(arg_def, "name", None)
                default_val = getattr(arg_def, "default", None)
            if not name:
                continue
            # Check if the instance already has a value set for this argument.
            current_val = getattr(self, name, None)
            if current_val is not None:
                defaults[name] = current_val
            else:
                defaults[name] = default_val
        return defaults
    except Exception:
        # In case of any unexpected error, return an empty dictionary.
        return {}

def get_spec_defaults(self):
        """Resolve arguments' values from spec and other sources."""
        defaults = {}
        # 1. class-level defaults
        if hasattr(self.__class__, "SPEC_DEFAULTS"):
            try:
                defaults.update(self.__class__.SPEC_DEFAULTS or {})
            except Exception as e:
                # ignore malformed defaults
                import warnings
                warnings.warn("Failed to update SPEC_DEFAULTS: %s" % e)

        # 2. instance-level spec defaults
        if getattr(self, "spec", None):
            try:
                spec = self.spec
                if isinstance(spec, dict):
                    spec_defaults = spec.get("DEFAULTS", {})
                    if isinstance(spec_defaults, dict):
                        defaults.update(spec_defaults)
                elif hasattr(spec, "DEFAULTS"):
                    if isinstance(spec.DEFAULTS, dict):
                        defaults.update(spec.DEFAULTS)
                elif hasattr(spec, "get_defaults"):
                    # fallback to method that returns a dict
                    spec_defaults = spec.get_defaults()
                    if isinstance(spec_defaults, dict):
                        defaults.update(spec_defaults)
            except Exception as e:
                # robust to malformed spec
                import warnings
                warnings.warn("Failed to extract defaults from spec: %s" % e)

        # 3. fallback built-in defaults
        try:
            fallback = getattr(self.__class__, "DEFAULTS", None)
            if isinstance(fallback, dict):
                defaults.update(fallback)
        except Exception:
            pass

        return defaults

