def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Define the deprecated arguments.
        # Ideally this attribute is defined on the class. If not,
        # we fall back to an empty list to avoid errors.
        deprecated = getattr(self, "DEPRECATED_ARGS", {})
        # `DEPRECATED_ARGS` can be either a mapping from old to new,
        # or a set/list of names to be treated as deprecated.
        if isinstance(deprecated, dict):
            deprec_old_to_new = deprecated
            deprec_keys = set(deprecated.keys())
        else:
            deprec_keys = set(deprecated)
            deprec_old_to_new = {}

        # Merge the two sources of arguments to a single dictionary
        # while preserving the source for debugging.
        combined = {}
        source_map = {}
        if isinstance(cli_args, dict):
            for k, v in cli_args.items():
                if k not in combined:
                    combined[k] = v
                    source_map[k] = "cli"
        if isinstance(answer_file_args, dict):
            for k, v in answer_file_args.items():
                if k not in combined:
                    combined[k] = v
                    source_map[k] = "answer file"

        # Check for deprecated arguments
        for key in list(combined.keys()):
            if key in deprec_keys:
                # Determine if there is a recommended replacement
                replacement = deprec_old_to_new.get(key)
                if replacement:
                    msg = (
                        f"WARNING: Argument '{key}' ({source_map[key]}) "
                        f"is deprecated and will be removed in a future release. "
                        f"Use '{replacement}' instead."
                    )
                else:
                    msg = (
                        f"WARNING: Argument '{key}' ({source_map[key]}) "
                        f"is deprecated and will be removed in a future release."
                    )
                # Print the warning to stderr to avoid interfering with stdout
                # which might be captured by tests.
                import sys
                print(msg, file=sys.stderr)

                # If a replacement argument is defined, populate it with
                # the value from the deprecated key, unless it already exists.
                if replacement and replacement not in combined:
                    combined[replacement] = combined[key]

                # Optionally remove the deprecated key to avoid accidental
                # downstream usage. This behaviour is safe because we already
                # copied its value to the replacement if applicable.
                del combined[key]

        # Update the original argument dictionaries if needed.
        # We keep the original references intact by mutating them.
        if isinstance(cli_args, dict):
            cli_keys = set(cli_args.keys())
            for k in list(cli_args.keys()):
                if k not in combined and k in cli_keys:
                    # if the key was removed due to deprecation, delete it
                    del cli_args[k]
            # Add any new keys that were inserted via replacements.
            for k, v in combined.items():
                if k not in cli_args:
                    cli_args[k] = v

        if isinstance(answer_file_args, dict):
            ans_keys = set(answer_file_args.keys())
            for k in list(answer_file_args.keys()):
                if k not in combined and k in ans_keys:
                    del answer_file_args[k]
            for k, v in combined.items():
                if k not in answer_file_args:
                    answer_file_args[k] = v

def validate_arg_deprecation(self, cli_args, answer_file_args):
        """Validates and prints the deprecated arguments.

        :param cli_args: the dict of arguments from cli
        :param answer_file_args:  the dict of arguments from files
        """
        # Retrieve mapping of deprecated arguments from the instance.
        # It may be a dict mapping argument names to deprecation messages.
        deprecated_map = getattr(self, 'DEPRECATED_ARGS', {})
        if not isinstance(deprecated_map, dict):
            deprecated_map = {}

        import sys

        def _report_deprecated(arg, source):
            """Helper to write a deprecation warning to stderr."""
            msg = deprecated_map.get(arg)
            if msg:
                warning_msg = f"Argument '{arg}' is deprecated in {source} arguments: {msg}"
            else:
                warning_msg = f"Argument '{arg}' is deprecated in {source} arguments."
            sys.stderr.write(warning_msg + "\n")

        # Validate CLI arguments
        if isinstance(cli_args, dict):
            for arg_name in cli_args:
                if arg_name in deprecated_map:
                    _report_deprecated(arg_name, "CLI")

        # Validate answer file arguments
        if isinstance(answer_file_args, dict):
            for arg_name in answer_file_args:
                if arg_name in deprecated_map:
                    _report_deprecated(arg_name, "answer file")

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if command_name == "":
        raise ValueError("command_name cannot be empty")

    # The mapping that stores option specs; fallback to empty dict if attribute missing
    option_map = getattr(self, "_parser_option_specs", None)
    if option_map is None:
        option_map = getattr(self, "parser_option_specs", {})
    if not isinstance(option_map, dict):
        raise AttributeError("Expected a dictionary of parser options, got %r" % (type(option_map),))

    # Retrieve options for the given command
    opts = option_map.get(command_name, [])

    # Normalise to a list and return a shallow copy to prevent accidental mutation
    if isinstance(opts, list):
        return opts.copy()
    try:
        return list(opts)
    except TypeError:
        # Non-iterable value; wrap it in a list
        return [opts]

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Validate the input
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string")

        # Ensure a parser mapping exists
        parser_map = getattr(self, "parser", None)
        if parser_map is None:
            raise AttributeError("No parser mapping defined on this object")

        # Retrieve the parser object for the given command
        if isinstance(parser_map, dict):
            parser_obj = parser_map.get(command_name)
        else:
            try:
                parser_obj = parser_map.get(command_name)
            except Exception:
                parser_obj = None

        if parser_obj is None:
            raise ValueError(f"Command '{command_name}' not found in parser mapping")

        # Try to fetch the option specifications from the parser object
        if hasattr(parser_obj, "get_option_specs"):
            try:
                return parser_obj.get_option_specs()
            except Exception as exc:  # pragma: no cover
                raise RuntimeError(f"Failed to retrieve option specs for '{command_name}': {exc}") from exc

        if hasattr(parser_obj, "options"):
            try:
                return list(parser_obj.options)
            except Exception as exc:  # pragma: no cover
                raise RuntimeError(f"Failed to list options for '{command_name}': {exc}") from exc

        # Fallback: return attribute names as an indicator of available options
        try:
            return list(vars(parser_obj).keys())
        except Exception:  # pragma: no cover
            return []

def get_parser_option_specs(self, command_name):
        """Gets all the options for the specified command

        :param command_name: the command name (main, virsh, ospd, etc...)
        :return: the list of all command options
        """
        # Validate input type
        if not isinstance(command_name, str):
            raise TypeError("command_name must be a string, got %r" % (command_name,))

        # Attempt to retrieve the command entry
        command_entry = None
        try:
            # Prefer 'commands' mapping if available
            if hasattr(self, 'commands') and isinstance(self.commands, (dict, list, tuple)):
                command_entry = self.commands.get(command_name) if isinstance(self.commands, dict) else None
            # Fallback to 'command_options' dict
            if command_entry is None and hasattr(self, 'command_options'):
                command_entry = self.command_options.get(command_name)
        except Exception as exc:
            raise RuntimeError("Failed to access command registry: %s" % exc)

        if command_entry is None:
            raise ValueError("Unknown command: %r" % command_name)

        # Extract options in various possible formats
        options = []

        # If the entry is a dict with an 'options' key
        if isinstance(command_entry, dict):
            options = command_entry.get('options', [])

        # If the entry itself is a list or tuple of options
        elif isinstance(command_entry, (list, tuple)):
            options = list(command_entry)

        # If the entry has a method to provide options
        elif hasattr(command_entry, 'get_options') and callable(command_entry.get_options):
            try:
                options = command_entry.get_options()
            except Exception as exc:
                raise RuntimeError("Error retrieving options for command %r: %s" % (command_name, exc))

        # If nothing matched, attempt to find 'options' attribute
        elif hasattr(command_entry, 'options'):
            options = getattr(command_entry, 'options')

        # Ensure the result is a list
        if not isinstance(options, list):
            # Attempt to convert iterable to list
            try:
                options = list(options)
            except Exception:
                options = []

        return options

def get_parser_option_specs(self, command_name):
    """Gets all the options for the specified command

    :param command_name: the command name (main, virsh, ospd, etc...)
    :return: the list of all command options
    """
    # The object that represents a command may store its options in a variety of ways.
    # First try a direct mapping of command names to command objects.
    try:
        cmd_obj = self.commands[command_name]
    except Exception:
        raise ValueError(f"Unknown command '{command_name}'")

    # 1. If the command object exposes a ``get_option_specs`` method, use that.
    if hasattr(cmd_obj, 'get_option_specs') and callable(cmd_obj.get_option_specs):
        try:
            return cmd_obj.get_option_specs()
        except Exception as exc:
            raise RuntimeError(f"Error retrieving options via get_option_specs for '{command_name}': {exc}") from exc

    # 2. If it has an ``option_specs`` attribute, return it.
    if hasattr(cmd_obj, 'option_specs'):
        opt = getattr(cmd_obj, 'option_specs')
        # Ensure it is a list; convert if it's a tuple or other sequence.
        if isinstance(opt, (list, tuple)):
            return list(opt)
        return [opt]

    # 3. Some parsers, such as argparse, store options in the ``_actions`` of a parser.
    if hasattr(cmd_obj, 'parser'):
        parser = getattr(cmd_obj, 'parser')
        try:
            actions = getattr(parser, '_actions', [])
            # Extract the primary option string for each action
            return [action.option_strings[0] for action in actions if action.option_strings]
        except Exception:
            pass

    # 4. If none of the above methods work, return an empty list rather than raising.
    return []

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name. """
    # Validate input types
    if not isinstance(command_name, str) or not command_name:
        raise TypeError("command_name must be a non-empty string")
    if not isinstance(argument_name, str) or not argument_name:
        raise TypeError("argument_name must be a non-empty string")

    # Determine where the command specifications are stored
    if hasattr(self, "command_specs"):
        cmd_map = self.command_specs
    elif hasattr(self, "commands"):
        cmd_map = self.commands
    else:
        raise AttributeError(
            "Could not find a command specification structure on this object"
        )

    # Find the specified command
    command_spec = cmd_map.get(command_name)
    if command_spec is None:
        # Try treating cmd_map as a mapping from command objects to specs
        for key, value in dict(cmd_map).items():
            if getattr(key, "name", None) == command_name:
                command_spec = value
                break
    if command_spec is None:
        raise ValueError(f"Command '{command_name}' not found")

    # Locate the options dictionary for the command
    options = None
    if isinstance(command_spec, dict):
        options = command_spec.get("options") or command_spec.get("args") or command_spec.get("parameters")
    else:
        options = getattr(command_spec, "options", None) or getattr(command_spec, "args", None) or getattr(command_spec, "parameters", None)

    if options is None:
        raise ValueError(f"Command '{command_name}' does not contain an options mapping")

    # Retrieve the specification for the requested option
    option_spec = options.get(argument_name)
    if option_spec is None:
        raise ValueError(f"Option '{argument_name}' not found in command '{command_name}'")

    return option_spec

def get_option_spec(self, command_name, argument_name):
    """Gets the specification for the specified option name."""
    if not isinstance(command_name, str):
        raise TypeError("command_name must be a string")
    if argument_name is None:
        return None
    try:
        cmd = self.commands[command_name]
    except Exception as exc:
        raise KeyError(f"Command '{command_name}' not found in configuration.") from exc
    try:
        options = getattr(cmd, "options", None) or {}
    except Exception as exc:
        raise AttributeError(f"Command object for '{command_name}' does not provide an 'options' attribute.") from exc
    try:
        return options[argument_name]
    except KeyError as exc:
        raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'.") from exc
    except Exception as exc:
        raise Exception(f"Error retrieving option specification for '{argument_name}' in command '{command_name}'.") from exc

def get_option_spec(self, command_name, argument_name):
        """Gets the specification for the specified option name."""
        if not isinstance(command_name, str):
            raise TypeError(f"command_name must be str, got {type(command_name).__name__}")
        if not isinstance(argument_name, str):
            raise TypeError(f"argument_name must be str, got {type(argument_name).__name__}")

        # The option specs are stored in a mapping from command name to
        # another mapping of argument name → spec object.
        # If the structure is missing or the requested option cannot be found,
        # we raise an informative ValueError.
        try:
            command_options = self._option_specs[command_name]
        except KeyError:
            raise ValueError(f"Unknown command '{command_name}'. Available commands: {list(self._option_specs)}")

        try:
            return command_options[argument_name]
        except KeyError:
            raise ValueError(f"Option '{argument_name}' not defined for command '{command_name}'. Available options: {list(command_options)}")

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent = []
    if args is None:
        return silent
    # If args is a mapping, consider a silenced argument where the value is `None` or `False`
    if isinstance(args, dict):
        try:
            for key, value in args.items():
                if value in (None, False):
                    silent.append(key)
        except Exception:
            # If something goes wrong with dict iteration, return what we have so far
            return silent
    # If args is an iterable of strings (but not a dict), we cannot determine silenced status
    # without further context; thus we return an empty list.
    elif isinstance(args, (list, tuple, set)):
        # Safely ensure all elements are convertible to strings
        try:
            for item in args:
                if not isinstance(item, str):
                    continue
                # No criteria available to mark as silent, ignore.
                pass
        except Exception:
            # In case of unexpected errors, return empty list
            return silent
    else:
        # Unsupported type; return empty list
        return silent
    return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_names = []

    if args is None:
        return silent_names

    # Helper to check if value is marked silent
    def _is_silent(val):
        if isinstance(val, dict):
            return bool(val.get('silent'))
        return getattr(val, 'silent', False)

    # Dict case: keys are argument names
    if isinstance(args, dict):
        for name, val in args.items():
            if _is_silent(val):
                silent_names.append(name)

    # Iterable case: list/tuple of (name, value) or objects
    elif isinstance(args, (list, tuple)):
        for item in args:
            # Tuple or list (name, value)
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                name, val = item[0], item[1]
                if _is_silent(val):
                    silent_names.append(name)
            # Dict with 'name' key
            elif isinstance(item, dict):
                name = item.get('name')
                val = item
                if name and _is_silent(val):
                    silent_names.append(name)
            # Object with attributes
            else:
                name = getattr(item, 'name', None)
                val = item
                if name and _is_silent(val):
                    silent_names.append(name)

    else:
        # Unsupported type
        raise ValueError(f"Unsupported args type: {type(args).__name__}")

    return silent_names

def get_silent_args(self, args):
        """list of silenced argument

        :param args: The received arguments.
        :return: list, slienced argument names
        """
        if args is None:
            return []

        # Accept a mapping (dict) or an iterable of key/value pairs.
        silent = []

        if isinstance(args, dict):
            silent = [key for key, value in args.items() if value is None]
        elif hasattr(args, "__iter__"):
            try:
                silent = [key for key, value in args if value is None]
            except (TypeError, ValueError):
                raise TypeError(
                    "args must be a dict or an iterable yielding (key, value) pairs"
                )
        else:
            raise TypeError(
                "args must be a mapping (dict) or an iterable of key/value pairs"
            )

        return silent

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    silent_args = []

    if not args:
        return silent_args

    # Ensure iteration over a list-like container
    try:
        iter(args)
    except TypeError:
        args = [args]

    for arg in args:
        name = None
        silent = None

        # Case 1: arg is a dictionary
        if isinstance(arg, dict):
            name = arg.get('name')
            silent = arg.get('silent')

        # Case 2: arg is a sequence (tuple or list)
        elif isinstance(arg, (list, tuple)):
            if len(arg) >= 3:
                # Assume format: (name, value, silent_flag)
                name = arg[0]
                silent = arg[2]
            elif len(arg) == 2:
                # Could be (name, silent_flag) or (value, silent_flag)
                # Try to infer if first element is a string (likely a name)
                if isinstance(arg[0], str):
                    name = arg[0]
                silent = arg[1]

        # Case 3: arg is an object with attributes
        else:
            if hasattr(arg, 'silent'):
                silent = getattr(arg, 'silent')
            if hasattr(arg, 'name'):
                name = getattr(arg, 'name')

        # If silent flag is truthy and we have a name, record it
        try:
            if silent:
                if name is not None:
                    silent_args.append(name)
        except Exception:
            continue

    return silent_args

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, slienced argument names
    """
    silent_args = []
    if not args:
        return silent_args
    # Case when args is a dictionary of argument names to values
    if hasattr(args, "keys"):
        for key in args.keys():
            if isinstance(key, str) and key.startswith("silent"):
                silent_args.append(key)
    else:
        # Assume args is an iterable of argument strings
        try:
            for item in args:
                if isinstance(item, str):
                    # Handle both Python argparse style and custom
                    if item.startswith("silent") or item.startswith("--silent"):
                        silent_args.append(item.lstrip("-"))
        except TypeError:
            # args is not iterable; ignore
            pass
    return silent_args

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # Determine the list of required arguments for this element.
    # Try common names that may define required attributes.
    required = getattr(self, 'REQUIRED_ARGS', None)
    if required is None:
        required = getattr(self, 'REQUIRED_ATTRIBS', None)
    if required is None:
        required = getattr(self, 'REQUIRED', None)
    # If still None, nothing to validate.
    if not required:
        return True

    # Ensure the supplied args are a mapping.
    if not isinstance(args, dict):
        raise TypeError(
            f"Expected a dict of arguments, got {type(args).__name__}"
        )

    # Find missing required keys.
    missing = [req for req in required if req not in args or args[req] is None]
    if missing:
        raise ValueError(
            "Missing required argument(s): " + ", ".join(missing)
        )

    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided. """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict mapping attribute names to values")

    missing = []
    required_attrs = getattr(self, 'REQUIRED_ATTRIBS', [])
    for attr in required_attrs:
        # Treat missing or None values as missing
        if attr not in args or args[attr] is None:
            missing.append(attr)

    if missing:
        missing_str = ', '.join(missing)
        raise ValueError(f"Missing required argument(s): {missing_str}")

    return True

def validate_requires_args(self, args):
    """Check if all the required arguments have been provided."""
    # The element may define a sequence of required argument names.
    required = getattr(self, "REQUIRED_ARGS", None)
    if not required:
        # Nothing to validate
        return True

    if args is None:
        args_dict = {}
    elif isinstance(args, dict):
        args_dict = args
    else:
        # Try to convert to a dict if it's a sequence of key/value pairs
        try:
            args_dict = dict(args)
        except Exception:
            raise TypeError("args must be a dict or a dict-like sequence of key/value pairs")

    missing = [name for name in required
               if name not in args_dict or args_dict[name] is None]

    if missing:
        raise ValueError(f"Missing required arguments: {', '.join(missing)}")

    return True

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        if options_spec is None:
            return []
        # Ensure args is a mapping for lookup
        if not isinstance(args, dict):
            try:
                args = dict(args)
            except Exception:
                args = {}
        required = []
        for opt in options_spec:
            # option name could be stored under different keys
            name = opt.get("name") or opt.get("opt") or opt.get("id") or opt.get("arg")
            if not name:
                continue
            req_when = opt.get("required_when")
            if not req_when:
                continue
            satisfied = False
            try:
                if callable(req_when):
                    # pass command_name and args
                    satisfied = bool(req_when(command_name=command_name, args=args))
                elif isinstance(req_when, str):
                    # eval expression with limited globals
                    satisfied = bool(eval(req_when, {}, {"command_name": command_name, "args": args}))
                elif isinstance(req_when, dict):
                    # all key/value pairs must match exactly
                    satisfied = all(args.get(k) == v for k, v in req_when.items())
                elif isinstance(req_when, (list, tuple)):
                    # treat list/tuple as a group of conditions that all must be true
                    # each element may be a callable, string, or dict
                    conds = []
                    for c in req_when:
                        if callable(c):
                            conds.append(c(command_name=command_name, args=args))
                        elif isinstance(c, str):
                            conds.append(eval(c, {}, {"command_name": command_name, "args": args}))
                        elif isinstance(c, dict):
                            conds.append(all(args.get(k) == v for k, v in c.items()))
                        else:
                            conds.append(False)
                    satisfied = all(conds)
                else:
                    # Unsupported type; treat as not satisfied
                    satisfied = False
            except Exception:
                # If any error occurs (e.g., eval error), treat as not satisfied
                satisfied = False
            if satisfied:
                required.append(name)
        return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        if "required_when" not in opt:
            continue
        cond = opt["required_when"]
        satisfied = False
        try:
            if callable(cond):
                # callable receives command_name and args dict
                satisfied = bool(cond(command_name, args))
            elif isinstance(cond, str):
                # evaluate the string expression with args as locals
                satisfied = bool(eval(cond, {}, args))
            elif isinstance(cond, (list, tuple)):
                # at least one condition must be true
                for sub in cond:
                    if callable(sub):
                        if sub(command_name, args):
                            satisfied = True
                            break
                    elif isinstance(sub, str):
                        if eval(sub, {}, args):
                            satisfied = True
                            break
            else:
                # other types just cast to bool
                satisfied = bool(cond)
        except Exception:
            # if evaluation fails, treat as not satisfied
            satisfied = False
        if satisfied and "name" in opt:
            required.append(opt["name"])
    return required

def _get_conditionally_required_args(self, command_name, options_spec, args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when`` condition
        """
        # Prepare the arguments mapping for evaluation
        if not isinstance(args, dict):
            try:
                args = vars(args)
            except Exception:
                args = {}

        required = []

        for spec in options_spec:
            # Skip non-dict specs; assume a dict-or-like spec
            if not isinstance(spec, dict):
                continue

            # Argument name may be keyed differently; try common keys
            arg_name = spec.get("name") or spec.get("arg") or spec.get("arg_name")
            if not arg_name:
                continue

            # If 'required_when' is not defined, skip
            cond = spec.get("required_when")
            if cond is None:
                continue

            matched = False
            try:
                # Callable: call with args dict
                if callable(cond):
                    matched = bool(cond(args))

                # Boolean literal: directly match
                elif isinstance(cond, bool):
                    matched = cond

                # String expression: evaluate in the context of args
                elif isinstance(cond, str):
                    matched = bool(eval(cond, {}, args))

                # Dictionary of specific conditions
                elif isinstance(cond, dict):
                    matched = all(args.get(k) == v for k, v in cond.items())

                # Unsupported type: treat as not matched
                else:
                    matched = False
            except Exception:
                matched = False

            if matched and arg_name not in required:
                required.append(arg_name)

        return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required = []
        if not isinstance(options_spec, (list, tuple)):
            # no options to check
            return required

        for opt in options_spec:
            # skip if not a mapping or missing name key
            if not isinstance(opt, dict) or 'name' not in opt:
                continue

            condition = opt.get('required_when')
            if condition is None:
                continue

            # Try to evaluate the condition.
            # The condition can be a callable, a mapping of command names,
            # a list of command names, or any truthy value.
            try:
                matched = False
                if callable(condition):
                    # Call with command_name and args (args is expected to be a dict)
                    matched = bool(condition(command_name, args))
                elif isinstance(condition, dict):
                    # Dictionary keyed by command names or wildcard '*'
                    cond_val = condition.get(command_name)
                    if cond_val is None and '*' in condition:
                        cond_val = condition['*']
                    if callable(cond_val):
                        matched = bool(cond_val(args))
                    else:
                        matched = bool(cond_val)
                elif isinstance(condition, (list, tuple, set)):
                    matched = command_name in condition
                else:
                    # Any truthy value is considered a match
                    matched = bool(condition)

                if matched:
                    required.append(opt['name'])
            except Exception:
                # if evaluating the condition raises an error, ignore this option
                continue

        return required

def _get_conditionally_required_args(self, command_name, options_spec,
                                         args):
        """List arguments with ``required_when`` condition matched.

        :param command_name: the command name.
        :param options_spec:  the list of command spec options.
        :param args: the received input arguments
        :return: list, list of argument names with matched ``required_when``
            condition
        """
        required_args = []
        # Normalise args: if it's a mapping (dict-like) use .get, otherwise
        # treat it as a flat list or tuple.
        is_dict = isinstance(args, dict)
        for opt in options_spec:
            # The option dictionary is expected to have a 'name' key.
            name = opt.get('name')
            if not name:
                continue

            cond = opt.get('required_when')
            if not cond:
                continue

            try:
                # If the condition is directly a boolean
                if isinstance(cond, bool):
                    if cond:
                        required_args.append(name)
                    continue

                # If the condition is a callable, call it with args and command_name
                if callable(cond):
                    if cond(args, command_name):
                        required_args.append(name)
                    continue

                # If the condition is a list/tuple of sub‑conditions
                if isinstance(cond, (list, tuple)):
                    matched = False
                    for sub in cond:
                        # Handle simple string conditions of the form "field==value"
                        if isinstance(sub, str):
                            if '==' in sub:
                                field, value = [x.strip() for x in sub.split('==', 1)]
                                # Support field "command_name"
                                if field == 'command_name':
                                    if command_name == value.strip("'\""):
                                        matched = True
                                # Support field "in_args" meaning the value
                                # should be present in args
                                elif field == 'in_args':
                                    if value in args:
                                        matched = True
                            # Support condition that tests for presence of an argument
                            elif sub.startswith('arg_present:'):
                                arg_name = sub.split(':', 1)[1]
                                if (is_dict and arg_name in args) or (not is_dict and arg_name in args):
                                    matched = True
                        # Handle callable sub‑conditions
                        elif callable(sub):
                            if sub(args, command_name):
                                matched = True
                        # Handle simple dict sub‑conditions (e.g., {"depends_on": "x", "value": "y"})
                        elif isinstance(sub, dict):
                            dep = sub.get('depends_on')
                            expected = sub.get('value')
                            if dep is not None:
                                if is_dict:
                                    actual = args.get(dep)
                                else:
                                    # When args is a list, we look for a tuple (dep, expected)
                                    actual = None
                                    for item in args:
                                        if isinstance(item, tuple) and len(item) == 2 and item[0] == dep:
                                            actual = item[1]
                                            break
                                if actual == expected:
                                    matched = True
                    if matched:
                        required_args.append(name)
                    continue

                # Fallback: if condition is a dict that can be evaluated directly
                if isinstance(cond, dict):
                    dep = cond.get('depends_on')
                    expected = cond.get('value')
                    if dep is not None:
                        if is_dict:
                            actual = args.get(dep)
                        else:
                            actual = None
                            for item in args:
                                if isinstance(item, tuple) and len(item) == 2 and item[0] == dep:
                                    actual = item[1]
                                    break
                        if actual == expected:
                            required_args.append(name)
            except Exception:
                # Silently ignore conditions that raise during evaluation
                continue

        return required_args

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError(f"args must be a dict, got {type(args).__name__}")
    # Retrieve a mapping of argument names to max lengths, if available
    max_lengths = getattr(self, "max_lengths", {})
    for name, value in args.items():
        # Skip if no length constraint defined for this argument
        limit = max_lengths.get(name)
        if limit is None:
            continue
        if value is None:
            continue
        # Only enforce length on string values
        if isinstance(value, str) and len(value) > limit:
            raise ValueError(
                f"Argument '{name}' exceeds maximum length of {limit} characters "
                f"(actual length: {len(value)})"
            )
    return True

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    if args is None:
        return

    if not isinstance(args, dict):
        raise TypeError("args must be a dict")

    # Mapping of argument names to maximum allowed length.
    max_lengths = getattr(self, 'max_length', {})
    if not isinstance(max_lengths, dict):
        # If defined but not a dict raise
        raise TypeError("self.max_length must be a dict if defined")

    for name, val in args.items():
        if name not in max_lengths:
            # No length restriction for this argument
            continue

        max_len = max_lengths[name]
        if max_len is None:
            continue
        # Determine value length
        try:
            length = len(val)
        except Exception:
            # Attempt string conversion
            try:
                length = len(str(val))
            except Exception:
                continue  # If cannot obtain length, skip

        if length > max_len:
            raise ValueError(
                f"Argument '{name}' length {length} exceeds maximum allowed {max_len}"
            )

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # The maximum lengths that are allowed for arguments.  The attribute can
    # be a dictionary (mapping an argument name to a maximum size) or a list/
    # tuple (mapping a positional argument index to a maximum size).
    max_lengths = getattr(self, "max_lengths", None)
    if max_lengths is None:
        # Nothing to validate
        return True

    # Validate named arguments
    if isinstance(args, dict):
        for key, val in args.items():
            limit = max_lengths.get(key)
            if limit is None:
                continue  # no limit specified for this argument
            if val is None:
                continue  # ignore missing values
            try:
                length = len(val)
            except Exception:
                continue  # non-iterable values are ignored
            if length > limit:
                raise ValueError(
                    f"Argument '{key}' length {length} exceeds maximum allowed {limit}"
                )
        return True

    # Validate positional arguments
    if isinstance(args, (list, tuple)):
        if not isinstance(max_lengths, (list, tuple)):
            raise TypeError(
                "max_lengths must be a list or tuple when 'args' is a sequence"
            )
        for idx, val in enumerate(args):
            if idx >= len(max_lengths):
                break  # no more limits defined
            limit = max_lengths[idx]
            if limit is None:
                continue
            if val is None:
                continue
            try:
                length = len(val)
            except Exception:
                continue
            if length > limit:
                raise ValueError(
                    f"Argument at position {idx} length {length} exceeds maximum allowed {limit}"
                )
        return True

    # Unsupported type for arguments
    raise TypeError("args must be a dict or an iterable of values")

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Optional configuration: mapping of argument name to max length
    max_lengths = getattr(self, "max_lengths", {})
    default_max = getattr(self, "default_max_length", 255)

    def _check_value(name, value):
        max_len = max_lengths.get(name, default_max)
        if isinstance(value, (str, bytes)):
            if len(value) > max_len:
                raise ValueError(
                    f"Argument '{name}' exceeds maximum length of {max_len} "
                    f"characters."
                )
        elif isinstance(value, (list, tuple)):
            for idx, item in enumerate(value):
                if isinstance(item, (str, bytes)) and len(item) > max_len:
                    raise ValueError(
                        f"Element {idx} of argument '{name}' exceeds maximum "
                        f"length of {max_len} characters."
                    )
        # other types are ignored for length checking

    if isinstance(args, dict):
        for key, val in args.items():
            _check_value(key, val)
    elif isinstance(args, (list, tuple)):
        for idx, val in enumerate(args):
            _check_value(f"arg{idx}", val)
    else:
        # single value: treat as argument 'value'
        _check_value("value", args)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure ``args`` is a mapping
    if not isinstance(args, dict):
        raise TypeError("`args` must be a dict mapping argument names to values")

    # If the class does not define any choices, nothing to validate
    if not hasattr(self, "choices"):
        return

    choices = getattr(self, "choices")
    if not isinstance(choices, dict):
        raise ValueError("`self.choices` must be a dict mapping argument names to allowed values")

    for name, value in args.items():
        # Only validate keys that have a defined list of choices
        if name not in choices:
            continue

        allowed = choices[name]
        # Normalize allowed to an iterable
        if not isinstance(allowed, (list, tuple, set)):
            allowed = [allowed]

        # Allow None or empty values to bypass validation
        if value is None or value == "":
            continue

        # If the provided value is a collection (e.g., list/tuple) interpret it as a multi-select
        if isinstance(value, (list, tuple)):
            invalid = [v for v in value if v not in allowed]
            if invalid:
                raise ValueError(
                    f"Invalid values for argument '{name}': {invalid}. "
                    f"Expected values to be subset of {allowed}."
                )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value!r}. "
                    f"Expected one of {allowed}."
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments, expected to be a mapping of argument names to values.
    :raises TypeError: If ``args`` is not a mapping.
    :raises ValueError: If an argument value is not within its defined set of choices.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a dict of argument names to values")

    # Determine where to fetch allowed choices from.
    # Prefer an attribute named ``choices`` or ``arg_choices``.
    # Fallback to a callable ``get_choices`` that returns a mapping.
    choices_map = {}
    if hasattr(self, "choices"):
        choices_map = getattr(self, "choices")
    elif hasattr(self, "arg_choices"):
        choices_map = getattr(self, "arg_choices")
    elif hasattr(self, "get_choices") and callable(getattr(self, "get_choices")):
        try:
            choices_map = self.get_choices()
        except Exception:
            choices_map = {}

    # If there are no declared choices, nothing to validate.
    if not isinstance(choices_map, dict) or not choices_map:
        return

    for name, value in args.items():
        if name in choices_map:
            allowed = choices_map[name]
            # Ensure allowed is iterable; coerce single value to list.
            if not isinstance(allowed, (list, tuple, set)):
                allowed = [allowed]
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {value!r}. "
                    f"Expected one of {tuple(allowed)}"
                )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Retrieve the mapping of argument names to their allowed choices.
    # Subclasses can provide a 'choices' attribute; fall back to empty dict if absent.
    allowed_map = getattr(self, "choices", {})
    for name, val in args.items():
        allowed = allowed_map.get(name)
        if allowed is None:
            # No restrictions defined for this argument; skip validation.
            continue

        # If the supplied value is an iterable of values (list/tuple/set), validate each element.
        if isinstance(val, (list, tuple, set)):
            for item in val:
                if item not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {item}. "
                        f"Allowed values: {allowed}"
                    )
        else:
            if val not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{name}': {val}. "
                    f"Allowed values: {allowed}"
                )
    return True

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Subclasses should define a dictionary mapping argument names to an
    # iterable of allowed values, e.g. self.CHOICE_VALUES = {'lang': ['en', 'de', 'fr']}.
    choice_def = getattr(self, 'CHOICE_VALUES', {})
    for name, value in args.items():
        if name in choice_def:
            allowed = choice_def[name]
            # Support both single values and lists for multivalued attributes
            if isinstance(value, (list, tuple)):
                for v in value:
                    if v not in allowed:
                        raise ValueError(
                            f"Invalid value for argument '{name}': {v!r}. "
                            f"Allowed values are: {tuple(allowed)}."
                        )
            else:
                if value not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{name}': {value!r}. "
                        f"Allowed values are: {tuple(allowed)}."
                    )
    return  # validation succeeded (no exception raised)

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        if not isinstance(args, dict):
            raise TypeError(f"args must be a dict, got {type(args).__name__}")

        # Attempt to retrieve argument specifications that may contain choice lists.
        # The implementation assumes that specifications are stored in an attribute
        # called `arg_spec` (or similar) on the instance, where the value for a
        # particular argument is a mapping that may contain a 'choices' key.
        # If such metadata is not present, the function simply skips validation
        # for that argument, assuming it is not a choice-based argument.
        spec_dict = getattr(self, "arg_spec", None)

        for name, value in args.items():
            # Skip validation if we have no specification for this argument.
            if not spec_dict or name not in spec_dict:
                continue

            allowed_choices = spec_dict[name].get("choices")
            if allowed_choices is None:
                continue  # no choices defined for this argument

            if not isinstance(allowed_choices, (list, tuple, set)):
                # Ensure the choices are iterable.
                raise TypeError(f"Choices for argument '{name}' must be an iterable, got {type(allowed_choices).__name__}")

            # Support both singular values and iterables (lists, tuples, sets).
            if isinstance(value, (list, tuple, set)):
                invalid_vals = [v for v in value if v not in allowed_choices]
                if invalid_vals:
                    raise ValueError(
                        f"Invalid value(s) {invalid_vals} for argument '{name}'. Expected one of {allowed_choices}."
                    )
            else:
                if value not in allowed_choices:
                    raise ValueError(
                        f"Invalid value '{value}' for argument '{name}'. Expected one of {allowed_choices}."
                    )
        # If all values pass the checks, simply return True.
        return True

def validate_min_max_args(self, args):
        """Check if value of arguments is between minimum and maximum values.

        :param args: The received arguments.
        """
        if args is None:
            raise TypeError("Argument 'args' must not be None")
        try:
            iterator = iter(args)
        except TypeError:
            raise TypeError("Argument 'args' must be an iterable of values")

        # Minimum and maximum values may be defined as attributes of the instance.
        min_val = getattr(self, "min_value", None)
        max_val = getattr(self, "max_value", None)

        for arg in iterator:
            if arg is None:
                continue
            if not isinstance(arg, (int, float)):
                raise TypeError(f"Argument value {arg!r} must be numeric")
            if (min_val is not None) and (arg < min_val):
                raise ValueError(
                    f"Argument {arg!r} less than minimum allowed {min_val!r}"
                )
            if (max_val is not None) and (arg > max_val):
                raise ValueError(
                    f"Argument {arg!r} greater than maximum allowed {max_val!r}"
                )
        return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Check if min/max attributes exist on the instance
    min_val = getattr(self, 'min', None)
    max_val = getattr(self, 'max', None)

    # If no bounds are defined, nothing to validate
    if min_val is None and max_val is None:
        return

    # Allow either a mapping or an iterable of values
    if args is None:
        return
    values = args.values() if isinstance(args, dict) else args

    for val in values:
        # Skip None values (they are not comparable)
        if val is None:
            continue
        try:
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Value {val!r} is below the minimum of {min_val!r}"
                )
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Value {val!r} is above the maximum of {max_val!r}"
                )
        except TypeError as e:
            # The value is not comparable with the bounds
            raise TypeError(
                f"Unable to compare {val!r} with bounds {min_val!r} / {max_val!r}"
            ) from e
        except Exception as e:  # pragma: no cover
            # Catch-all for unexpected errors during validation
            raise ValueError(f"Argument validation failed: {e}") from e

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values."""
    try:
        # Handle dictionary of named arguments
        if isinstance(args, dict):
            # Attempt per-key min/max from attributes `min_args`, `max_args`
            min_map = getattr(self, "min_args", {})
            max_map = getattr(self, "max_args", {})
            for key, val in args.items():
                if not isinstance(val, (int, float)):
                    continue  # skip non-numeric values
                # Get specific limits if available, otherwise use generic ones
                key_min = min_map.get(key, getattr(self, "min", None))
                key_max = max_map.get(key, getattr(self, "max", None))
                if key_min is not None and val < key_min:
                    raise ValueError(
                        f'Argument "{key}" value {val} is below the minimum {key_min}'
                    )
                if key_max is not None and val > key_max:
                    raise ValueError(
                        f'Argument "{key}" value {val} is above the maximum {key_max}'
                    )
        else:
            # Assume a sequence of numeric values with generic min/max limits
            generic_min = getattr(self, "min", None)
            generic_max = getattr(self, "max", None)
            if generic_min is None and generic_max is None:
                return  # nothing to validate
            values = args if isinstance(args, (list, tuple)) else [args]
            for idx, val in enumerate(values):
                if not isinstance(val, (int, float)):
                    continue
                if generic_min is not None and val < generic_min:
                    raise ValueError(
                        f'Argument index {idx} value {val} is below the minimum {generic_min}'
                    )
                if generic_max is not None and val > generic_max:
                    raise ValueError(
                        f'Argument index {idx} value {val} is above the maximum {generic_max}'
                    )
    except Exception as exc:
        raise ValueError(f"Invalid argument values: {exc}") from exc

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Support dict or iterable of tuples.
    if isinstance(args, dict):
        for key, val in args.items():
            # Resolve min and max attributes on the object.
            min_name = f"{key.upper()}_MIN"
            max_name = f"{key.upper()}_MAX"
            min_val = getattr(self, min_name, None)
            max_val = getattr(self, max_name, None)
            if min_val is not None and val < min_val:
                raise ValueError(
                    f"Argument '{key}'={val} is below minimum {min_val}"
                )
            if max_val is not None and val > max_val:
                raise ValueError(
                    f"Argument '{key}'={val} exceeds maximum {max_val}"
                )
    elif isinstance(args, (list, tuple)):
        for item in args:
            if not isinstance(item, (list, tuple)):
                raise TypeError(
                    f"Each element in args must be a tuple, got {type(item).__name__}"
                )
            if len(item) == 3:
                key, val, bounds = item
                if not (isinstance(bounds, (tuple, list)) and len(bounds) == 2):
                    raise TypeError(
                        f"Bounds for argument '{key}' must be a tuple/list of (min, max)"
                    )
                min_val, max_val = bounds
                if min_val is not None and val < min_val:
                    raise ValueError(
                        f"Argument '{key}'={val} is below minimum {min_val}"
                    )
                if max_val is not None and val > max_val:
                    raise ValueError(
                        f"Argument '{key}'={val} exceeds maximum {max_val}"
                    )
            elif len(item) == 2:
                key, val = item
                min_name = f"{key.upper()}_MIN"
                max_name = f"{key.upper()}_MAX"
                min_val = getattr(self, min_name, None)
                max_val = getattr(self, max_name, None)
                if min_val is not None and val < min_val:
                    raise ValueError(
                        f"Argument '{key}'={val} is below minimum {min_val}"
                    )
                if max_val is not None and val > max_val:
                    raise ValueError(
                        f"Argument '{key}'={val} exceeds maximum {max_val}"
                    )
            else:
                raise TypeError(
                    f"Tuple for argument must be of length 2 or 3, got {len(item)}"
                )
    else:
        raise TypeError(
            f"args must be a dict or an iterable of tuples, got {type(args).__name__}"
        )
    return True

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Get global minimum and maximum constraints if they exist on the instance
    min_val = getattr(self, 'min_value', None)
    max_val = getattr(self, 'max_value', None)

    # If no constraints are defined, nothing to validate
    if min_val is None or max_val is None:
        return

    if args is None:
        return

    # Determine how to iterate over provided arguments
    # Treat dictionaries as mapping of names to values, otherwise assume iterable of values
    if isinstance(args, dict):
        iterable = args.items()
    else:
        # If args is a single value not iterable, put it in a list
        try:
            iterable = enumerate(args)
        except TypeError:
            iterable = [(None, args)]

    for key, val in iterable:
        # Skip values that are None or not comparable
        if val is None:
            continue
        try:
            if not (min_val <= val <= max_val):
                name_part = f" for key '{key}'" if isinstance(key, (str, int)) else ""
                raise ValueError(f"Argument{name_part} with value {val!r} falls outside the allowed range "
                                 f"[{min_val}, {max_val}].")
        except TypeError:
            name_part = f" for key '{key}'" if isinstance(key, (str, int)) else ""
            raise TypeError(f"Argument{name_part} with value {val!r} is not comparable to the defined "
                            "minimum and maximum values.")

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of input arguments
    if subcommand is None or type_name is None or option_name is None or spec_option is None:
        raise ValueError("All arguments must be provided and not None")
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    # spec_option may be any mapping; we accept dict or mapping-like objects
    if not isinstance(spec_option, dict):
        try:
            spec_option = dict(spec_option)
        except Exception:
            raise TypeError("spec_option must be a mapping (e.g., dict)")

    # Attempt to use a dedicated ComplexArgumentType class if available
    complex_type_cls = getattr(self, "ComplexArgumentType", None)
    if complex_type_cls and callable(complex_type_cls):
        try:
            return complex_type_cls(subcommand=subcommand,
                                    type_name=type_name,
                                    option_name=option_name,
                                    spec_option=spec_option)
        except Exception:
            # Fallback to a generic representation if instantiation fails
            pass

    # Fallback: return a dictionary representation of the complex type
    return {
        "subcommand": subcommand,
        "type_name": type_name,
        "option_name": option_name,
        "spec_option": spec_option
    }

def create_complex_argumet_type(self, subcommand, type_name, option_name, spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation
    if not isinstance(type_name, str) or not type_name:
        raise ValueError("type_name must be a non-empty string")
    if not isinstance(option_name, str):
        raise ValueError("option_name must be a string")
    if spec_option is not None and not isinstance(spec_option, dict):
        raise ValueError("spec_option must be a dict if provided")

    # Build a namespace object that holds the relevant data
    attrs = {
        'type_name': type_name,
        'subcommand': subcommand,
        'option_name': option_name,
        'spec_option': spec_option
    }
    try:
        from types import SimpleNamespace
        return SimpleNamespace(**attrs)
    except ImportError:
        # Fallback for older Python versions
        class Simple:
            def __init__(self, **kw):
                for k, v in kw.items():
                    setattr(self, k, v)
        return Simple(**attrs)

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file.
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    if args is None:
        return {}, {}

    # Accept either a dict or a list/tuple of key/value pairs
    if isinstance(args, dict):
        items = args.items()
    elif isinstance(args, (list, tuple)):
        # Expect alternating key/value pairs
        if len(args) % 2 != 0:
            raise ValueError("args list must contain an even number of elements (key/value pairs).")
        items = ((args[i], args[i + 1]) for i in range(0, len(args), 2))
    else:
        raise TypeError(f"Unsupported type for args: {type(args).__name__}")

    control_args = {}
    nested_args = {}
    # Define control keys – extend this set if needed
    CONTROL_KEY_PREFIXES = ('_', 'control_', 'ignore_', 'debug_')
    CONTROL_STRINGS = set(['dryrun', 'verbose', 'debug', 'quiet'])

    for key, value in items:
        # Normalize key to string for checking
        try:
            k_str = str(key).lower()
        except Exception:
            k_str = ''
        # Determine category
        if any(k_str.startswith(p) for p in CONTROL_KEY_PREFIXES) or k_str in CONTROL_STRINGS or key.startswith('--'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # initialise result dictionaries
        control_args = {}
        nested_args = {}

        # normalise the args to an iterable of (key, value) pairs
        items = []

        if isinstance(args, dict):
            # simply use dict items
            items = list(args.items())
        elif isinstance(args, (list, tuple)):
            for item in args:
                if isinstance(item, dict):
                    items.extend(item.items())
                elif isinstance(item, (list, tuple)):
                    if len(item) == 2:
                        items.append((item[0], item[1]))
                elif isinstance(item, str):
                    if '=' in item:
                        key, val = item.split('=', 1)
                        items.append((key.strip(), val.strip()))
                    else:
                        # treat bare strings as flag keys with value True
                        items.append((item.strip(), True))
                else:
                    # ignore unsupported types
                    continue
        else:
            # Unsupported args type, return empty dicts
            return control_args, nested_args

        # classify each key/value pair
        for key, value in items:
            # ensure key is a string
            if not isinstance(key, str):
                # try to convert to string
                try:
                    key = str(key)
                except Exception:
                    continue
            # case-insensitive check for control prefix
            if key.lower().startswith('control_'):
                control_args[key] = value
            else:
                nested_args[key] = value

        # flatten nested dictionaries if present
        def _flatten(src):
            flat = {}
            for k, v in src.items():
                if isinstance(v, dict):
                    for sub_k, sub_v in v.items():
                        flat[f'{k}_{sub_k}'] = sub_v
                else:
                    flat[k] = v
            return flat

        control_args = _flatten(control_args)
        nested_args = _flatten(nested_args)

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list or mapping of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Prepare storage
        control_args = {}
        nested_args = {}

        # Allow either a mapping (dict-like) or an iterable of (key, value) pairs
        if args is None:
            return control_args, nested_args

        if isinstance(args, dict):
            items = args.items()
        else:
            try:
                # Try to iterate directly
                items = args
            except TypeError:
                # Not iterable, cannot process
                raise ValueError("args must be a dict or iterable of (key, value) pairs")

        for key, value in items:
            if not isinstance(key, str):
                continue  # Skip non-string keys

            # Determine category
            # Control arguments: keys that are exactly 'control' or start with 'control_'
            if key == 'control' or key.startswith('control_'):
                control_args[key] = value
            # Custom arguments: start with 'custom_'; they map to nested keys
            elif key.startswith('custom_'):
                nested_key = key[len('custom_'):]
                nested_args[nested_key] = value
            else:
                # Default case: nested argument
                nested_args[key] = value

        return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args (dict or iterable of (key,value) pairs).
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Define which keys belong to control and custom groups.  Subclasses can
    # override these attributes.
    control_keys = set(getattr(self, "CONTROL_ARGS", []))
    custom_keys = set(getattr(self, "CUSTOM_ARGS", []))

    # Normalise the input argument list to a mapping
    if args is None:
        flat_args = {}
    elif isinstance(args, dict):
        flat_args = dict(args)
    else:
        try:
            # Assume iterable of (key, value) pairs
            flat_args = {k: v for k, v in args}
        except Exception as exc:
            raise TypeError("args must be a dict or an iterable of (key, value) pairs") from exc

    control_args = {}
    nested_args = {}

    for key, value in flat_args.items():
        if key in control_keys:
            control_args[key] = value
        elif key in custom_keys:
            # Custom arguments are treated like nested ones, but go
            # straight into the nested dictionary.  Subclasses may need
            # further processing, so we leave the key intact.
            nested_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Handle a None or non-iterable ``args`` gracefully
    if not args:
        return {}, {}

    # Determine which keys are considered control arguments.
    # If the class defines a CONTROL_ARGS list or set, use it;
    # otherwise assume there are no explicit control keys besides
    # those that start with '_' (common convention for internal use).
    control_keys = getattr(self, "CONTROL_ARGS", set())
    if isinstance(control_keys, (list, tuple)):
        control_keys = set(control_keys)

    control_args = {}
    nested_args = {}

    # Normalize ``args`` to a list of (key, value) tuples.
    # Accepts either a dict or an iterable of two-element tuples.
    if isinstance(args, dict):
        items = args.items()
    else:
        try:
            items = [(k, v) for k, v in args]
        except Exception:
            # If arg is not iterable of pairs, ignore it entirely.
            return {}, {}

    for key, value in items:
        # Keys starting with '_' or explicitly listed are control args.
        if key in control_keys or (isinstance(key, str) and key.startswith("_")):
            control_args[key] = value
            continue

        # If the value itself is a dict, flatten it into nested_args.
        # This covers nested structures that should appear in the spec.
        if isinstance(value, dict):
            # In case the nested dict shares keys, later values overwrite earlier ones.
            nested_args.update(value)
            continue

        # Any other key/value pair is treated as a nested argument.
        nested_args[key] = value

    # Apply any custom handling: in some contexts custom arguments may be
    # defined by a ``CUSTOM_ARGS`` attribute on the instance; treat those
    # as control arguments as they override normal nested usage.
    custom_keys = getattr(self, "CUSTOM_ARGS", set())
    if isinstance(custom_keys, (list, tuple)):
        custom_keys = set(custom_keys)
    custom_to_control = {k: v for k, v in nested_args.items() if k in custom_keys}
    for k, v in custom_to_control.items():
        control_args[k] = v
        del nested_args[k]

    return control_args, nested_args

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict

    # Prepare a dictionary of extra vars to merge
    extra_dict = {}
    try:
        if isinstance(extra_vars, dict):
            extra_dict = dict(extra_vars)
        elif isinstance(extra_vars, (list, tuple)):
            for item in extra_vars:
                if isinstance(item, dict):
                    extra_dict.update(item)
                elif isinstance(item, str) and "=" in item:
                    key, value = item.split("=", 1)
                    extra_dict[key.strip()] = value.strip()
                # ignore unexpected formats
    except Exception:
        # If anything goes wrong, just leave vars_dict unchanged
        return vars_dict

    if not extra_dict:
        return vars_dict

    # Merge into the base dict under the key 'extra-vars'
    if "extra-vars" in vars_dict:
        base = vars_dict["extra-vars"]
        if isinstance(base, dict):
            base.update(extra_dict)
        else:
            vars_dict["extra-vars"] = extra_dict
    else:
        vars_dict["extra-vars"] = extra_dict

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``

        :param vars_dict: Dictionary to merge extra-vars into
        :param extra_vars: List (or dict) of extra-vars
        """
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dict")

        if extra_vars is None:
            return vars_dict

        # Accept a plain dictionary of extra vars
        if isinstance(extra_vars, dict):
            vars_dict.update(extra_vars)
            return vars_dict

        # Try to interpret iterable of key/value pairs or string "key=value"
        try:
            for item in extra_vars:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                elif isinstance(item, str) and '=' in item:
                    key, value = item.split('=', 1)
                    vars_dict[key] = value
                else:
                    # Unknown format – ignore or raise an informative error
                    raise ValueError(
                        f"Unsupported extra_vars item type {type(item).__name__}: {item!r}"
                    )
        except Exception as exc:
            raise ValueError(
                "extra_vars must be a dict or an iterable of key/value pairs or \"key=value\" strings"
            ) from exc

        return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

    if extra_vars is None:
        return vars_dict

    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError(f"extra_vars must be a list or tuple, got {type(extra_vars).__name__}")

    for var in extra_vars:
        if isinstance(var, dict):
            vars_dict.update(var)
        elif isinstance(var, str):
            # accepted format: "key=value" or just "key"
            if "=" in var:
                key, value = var.split("=", 1)
                vars_dict[key] = value
            else:
                vars_dict[var] = None
        else:
            raise TypeError(
                f"Each extra_var must be a dict or str, got {type(var).__name__}"
            )

    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if extra_vars is None:
        return vars_dict
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        try:
            for item in extra_vars:
                if isinstance(item, (list, tuple)) and len(item) == 2:
                    key, value = item
                elif isinstance(item, str):
                    if '=' in item:
                        key, value = item.split('=', 1)
                    else:
                        continue
                else:
                    print(f"Warning: Unsupported extra_var item: {item!r}")
                    continue
                vars_dict[key] = value
        except TypeError:
            raise TypeError("extra_vars must be a dict or an iterable of key/value pairs")
    return vars_dict

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: Optional collection of extra-vars to add
    :returns: The updated dictionary (the same object as ``vars_dict``)
    """
    # Validate ``vars_dict`` input
    if vars_dict is None:
        raise ValueError("vars_dict cannot be None")
    if not isinstance(vars_dict, dict):
        raise TypeError(f"Expected vars_dict to be a dict, got {type(vars_dict).__name__}")

    if not extra_vars:
        # Nothing to merge – just return the original dictionary
        return vars_dict

    # If extra_vars is a dict, merge directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
    else:
        # Attempt to treat extra_vars as an iterable of key/value pairs.
        # Reject strings and byte sequences to avoid unintended character iteration.
        if hasattr(extra_vars, "__iter__") and not isinstance(extra_vars, (str, bytes)):
            try:
                for item in extra_vars:
                    # Each item should be a two‑item iterable: (key, value)
                    if not isinstance(item, (list, tuple)) or len(item) != 2:
                        raise ValueError(
                            f"Each element of extra_vars must be a (key, value) pair, got {item!r}"
                        )
                    key, value = item
                    vars_dict[key] = value
            except TypeError:
                # ``extra_vars`` is not actually iterable
                raise TypeError(f"Unable to iterate over extra_vars of type {type(extra_vars).__name__}")
        else:
            raise TypeError(
                f"Unsupported type for extra_vars: {type(extra_vars).__name__}. "
                "Expected a dict or an iterable of (key, value) pairs."
            )

    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    subprocess = __import__('subprocess')
    json = __import__('json')
    os = __import__('os')

    # Validate playbook path
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook '{playbook_path}' does not exist.")

    cmd = ['ansible-playbook', playbook_path]

    # Verbosity handling
    if verbose is not None:
        if isinstance(verbose, int):
            if verbose < 0 or verbose > 5:
                raise ValueError("verbose level must be between 0 and 5")
            cmd.extend(['-v'] * verbose)
        elif isinstance(verbose, str):
            # Accept strings like 'v', 'vv', 'vvv', etc.
            v_count = len([c for c in verbose if c == 'v'])
            if v_count > 5:
                raise ValueError("verbose level string too long")
            cmd.extend(['-v'] * v_count)
        else:
            raise TypeError("verbose must be int, str, or None")

    # Extra variables
    if extra_vars is not None:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dictionary")
        cmd.extend(['--extra-vars', json.dumps(extra_vars)])

    # Additional ansible args
    if ansible_args is not None:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dictionary")
        for key, val in ansible_args.items():
            if not isinstance(key, str):
                continue
            arg_key = key if key.startswith('-') else '--' + key.replace('_', '-')
            if isinstance(val, bool):
                if val:
                    cmd.append(arg_key)
                else:
                    continue
            elif val is None:
                continue
            else:
                cmd.append(arg_key)
                cmd.append(str(val))

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=True)
        return result.stdout
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"ansible-playbook failed with exit code {exc.returncode}:\n{exc.stderr}") from exc
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook command not found. Make sure Ansible is installed and in PATH.")

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import json

    # Build base command
    cmd = ['ansible-playbook', playbook_path]

    # Add verbosity
    if verbose is not None:
        try:
            v = int(verbose)
        except (ValueError, TypeError):
            v = 0
        if v > 0:
            # Usage: -v, -vv, -vvv, -vvvv
            cmd.append('-' + 'v' * min(v, 4))

    # Add extra_vars if provided
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        # Convert dict to JSON string
        try:
            ev_json = json.dumps(extra_vars, separators=(',', ':'))
        except (TypeError, ValueError) as exc:
            raise ValueError(f"Failed to encode extra_vars to JSON: {exc}") from exc
        cmd.extend(['--extra-vars', ev_json])

    # Add additional ansible_args
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError(f"Argument key {key!r} must be a string")
            if value is True or value is None:
                cmd.append(key)
            elif value is False:
                # Skip false flags
                continue
            else:
                cmd.extend([key, str(value)])

    # Logging: use plugin's logger if available
    logger = getattr(ir_plugin, "logger", None)
    if logger:
        logger.debug(f"Executing ansible command: {' '.join(cmd)}")

    # Execute command
    try:
        result = subprocess.run(
            cmd,
            cwd=ir_workspace.path if hasattr(ir_workspace, "path") else None,
            text=True,
            capture_output=True,
            check=False
        )
    except FileNotFoundError as exc:
        raise RuntimeError("ansible-playbook command not found") from exc
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

    # Log output
    if logger:
        if result.stdout:
            logger.debug("ansible-playbook stdout:\n%s", result.stdout)
        if result.stderr:
            logger.debug("ansible-playbook stderr:\n%s", result.stderr)

    # Raise error on non-zero exit unless ignore
    if result.returncode != 0:
        msg = (
            f"ansible-playbook exited with status {result.returncode}\n"
            f"Command: {' '.join(cmd)}\n"
            f"stdout:\n{result.stdout}\n"
            f"stderr:\n{result.stderr}"
        )
        raise RuntimeError(msg)

    return result

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

    :param ir_workspace: An Infrared Workspace object representing the active
        workspace.
    :param ir_plugin: An InfraredPlugin object of the current plugin.
    :param playbook_path: Path to the playbook to invoke.
    :param verbose: Ansible verbosity level (int 1–4 or string like '-v', '--vvv').
    :param extra_vars: dict. Passed to Ansible as ``--extra-vars``.
    :param ansible_args: dict of ansible-playbook arguments to plumb down
        directly to Ansible.
    """
    import os
    import json
    import subprocess
    from pathlib import Path

    # Resolve playbook path: if relative, interpret it from the workspace root
    play_path = Path(playbook_path)
    if not play_path.is_absolute():
        root = getattr(ir_workspace, "root", None)
        if root is None:
            root = getattr(ir_workspace, "_root", None)
        if root is None:
            root = Path(".")
        play_path = Path(root) / play_path

    if not play_path.is_file():
        raise FileNotFoundError(f"Playbook '{play_path}' does not exist")

    cmd = ["ansible-playbook", str(play_path)]

    # Verbosity handling
    if verbose is not None:
        if isinstance(verbose, int):
            if 1 <= verbose <= 4:
                cmd.append("-" + "v" * verbose)
            elif verbose > 4 or verbose < 1:
                raise ValueError("verbose int must be in 1–4")
        elif isinstance(verbose, str):
            if verbose.startswith("-"):
                cmd.append(verbose)
            else:
                # allow plain 'v', 'vv', etc.
                cmd.append("-" + verbose)

    # Append additional ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            key_str = key if key.startswith("--") or key.startswith("-") else f"--{key}"
            cmd.append(key_str)
            if value is not None:
                cmd.append(str(value))

    # Extra vars
    if extra_vars:
        try:
            json_str = json.dumps(extra_vars)
        except Exception as exc:
            raise ValueError(f"extra_vars must be JSON serialisable: {exc}") from exc
        cmd.extend(["--extra-vars", json_str])

    # Run the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=True,
            cwd=str(play_path.parent),
        )
    except subprocess.CalledProcessError as exc:
        # If the plugin has a reporting mechanism, use it.
        report = getattr(ir_plugin, "report", None)
        if callable(report):
            report(
                f"Ansible playbook '{play_path}' failed: {exc.returncode}",
                "error",
            )
        raise RuntimeError(
            f"Ansible playbook '{play_path}' failed with exit code {exc.returncode}\n"
            f"Stdout: {exc.stdout}\nStderr: {exc.stderr}"
        ) from exc

    # Optionally log success if the plugin supports it
    report = getattr(ir_plugin, "report", None)
    if callable(report):
        report(f"Ansible playbook '{play_path}' executed successfully.", "info")

    return result

def _run_playbook(cli_args, vars_dict, ir_workspace, ir_plugin):
    """Runs ansible cli with vars dict

    :param vars_dict: dict, Will be passed as Ansible extra-vars
    :param cli_args: the list  of command line arguments
    :param ir_workspace: An Infrared Workspace object represents the active
     workspace
    :param ir_plugin: An InfraredPlugin object of the current plugin
    :return: ansible results
    """
    import subprocess
    import json
    import shlex

    # Ensure arguments are lists
    if cli_args is None:
        cli_args = []
    elif not isinstance(cli_args, (list, tuple)):
        raise TypeError("cli_args must be a list or tuple of command line arguments")

    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")

    # Prepare the ansible-playbook command
    cmd = ["ansible-playbook"]
    try:
        cmd += list(cli_args)
    except Exception as exc:
        raise ValueError("Failed to process cli_args: %s" % exc)

    # Pass the extra-vars dictionary as JSON string
    try:
        extra_vars = json.dumps(vars_dict, default=str)
    except Exception as exc:
        raise ValueError("Failed to serialize vars_dict to JSON: %s" % exc)

    cmd += ["--extra-vars", extra_vars]

    # Attempt to execute the command
    try:
        result = subprocess.run(
            cmd,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError as exc:
        # ansible-playbook command not found
        raise RuntimeError(
            "ansible-playbook command not found. Ensure Ansible is installed and "
            "available in your PATH."
        ) from exc
    except Exception as exc:
        raise RuntimeError("Failed to run ansible-playbook: %s" % exc) from exc

    # If the user wants to see the output on console, push it to the plugin logger
    if ir_plugin and hasattr(ir_plugin, "logger"):
        if result.stdout:
            ir_plugin.logger.info("\n--- Ansible STDOUT ---\n%s", result.stdout)
        if result.stderr:
            ir_plugin.logger.warning("\n--- Ansible STDERR ---\n%s", result.stderr)

    # Provide a useful return value
    output = {
        "returncode": result.returncode,
        "stdout": result.stdout,
        "stderr": result.stderr,
    }

    # Try to parse JSON output if ansible was run in json format
    try:
        output["json"] = json.loads(result.stdout)
    except Exception:
        output["json"] = None

    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with return code {result.returncode}"
        )

    return output

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict parameter.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dictionary of arguments
    """
    # Resolve any predefined type mapping for this parser
    types_map = {}
    try:
        # Expecting an attribute like `self.arg_types` to hold type info
        types_map = getattr(self, 'arg_types', {}).get(parser_name, {})
    except Exception:
        # If any issue occurs, fall back to heuristic conversion
        types_map = {}

    # Iterate over a copy of keys to allow mutation
    for key, val in list(values_dict.items()):
        if val is None:
            continue

        # Attempt explicit conversion based on defined mapping
        target_type = types_map.get(key)
        if target_type:
            try:
                # Handle special case for bool conversion via target_type
                if target_type is bool:
                    values_dict[key] = bool(val)
                else:
                    values_dict[key] = target_type(val)
                continue
            except Exception:
                pass  # fall back to heuristic conversion

        # Heuristic conversion only for string values
        if not isinstance(val, str):
            continue

        raw = val.strip()
        if raw == '':
            values_dict[key] = None
            continue

        lowered = raw.lower()
        # Boolean
        if lowered in ('true', 'false', 'yes', 'no', '1', '0', 'on', 'off'):
            values_dict[key] = lowered in ('true', 'yes', '1', 'on')
            continue

        # Integer
        try:
            if '.' not in raw:
                values_dict[key] = int(raw)
                continue
        except ValueError:
            pass

        # Float
        try:
            values_dict[key] = float(raw)
            continue
        except ValueError:
            pass

        # List (comma separated)
        if ',' in raw:
            try:
                values_dict[key] = [item.strip() for item in raw.split(',')]
                continue
            except Exception:
                pass

        # Fallback: keep as string
        values_dict[key] = raw

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Try to use a predefined conversion map if available
    conv_map = getattr(self, "_ARG_TYPE_MAP", {}).get(parser_name, {})

    # First apply any explicit conversions from the map
    for key, val in list(values_dict.items()):
        if key in conv_map and val is not None:
            try:
                values_dict[key] = conv_map[key](val)
            except Exception as exc:
                raise ValueError(
                    f"Could not convert argument '{key}' ({val!r}) "
                    f"to expected type for parser '{parser_name}'."
                ) from exc

    # Apply reasonable generic conversions for remaining string values
    for key, val in list(values_dict.items()):
        if isinstance(val, str) and val:
            lowered = val.strip().lower()

            # Boolean conversion
            if lowered in {"true", "yes", "1"}:
                values_dict[key] = True
                continue
            if lowered in {"false", "no", "0"}:
                values_dict[key] = False
                continue

            # Integer conversion
            int_str = val.strip()
            if int_str.lstrip("-").isdigit():
                try:
                    values_dict[key] = int(int_str)
                    continue
                except Exception:
                    pass  # fall back to leave as string

            # Float conversion
            try:
                float_val = float(val)
                # Ensure we don't convert ints silently; check if float string actually has a decimal point or exponent
                if "." in val or "e" in val.lower():
                    values_dict[key] = float_val
                else:
                    # If value is like "10" which passed int branch, just keep the int; otherwise keep float
                    values_dict[key] = float_val
                continue
            except Exception:
                pass  # leave as original string

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dict")
    if not isinstance(parser_name, str):
        raise TypeError("parser_name must be a string")

    # Try to obtain the parser object.  The exact attribute storage
    # convention may vary, so we check a few common possibilities.
    parser = getattr(self, f"{parser_name}_parser", None)
    if parser is None:
        parser = getattr(self, "parsers", {}).get(parser_name)

    if parser is None:
        # No parser found – nothing to convert.
        return

    # Build a lookup from the option string (without leading dashes)
    # to its corresponding argparse Action object.
    action_map = {}
    for action in getattr(parser, "_actions", []):
        for opt in action.option_strings:
            key = opt.lstrip("-").replace("-", "_")
            action_map[key] = action

    # Iterate over the supplied values and attempt to cast them.
    for key, val in list(values_dict.items()):
        if val is None or isinstance(val, bool):
            # None and bool values are already acceptable.
            continue

        # Get the action that defines the target type for this key.
        action = action_map.get(key)
        if action is None or action.type is None:
            # No type information available; leave the value as-is.
            continue

        native_type = action.type

        try:
            if native_type is bool:
                # Special handling for booleans – accept common string
                # representations as well as the types that Python treats
                # truthy/falsey for.
                if isinstance(val, str):
                    lowered = val.lower()
                    if lowered in ("true", "yes", "y", "1"):
                        cast_value = True
                    elif lowered in ("false", "no", "n", "0"):
                        cast_value = False
                    else:
                        # If it doesn't match a known pattern, treat as
                        # the default boolean conversion.
                        cast_value = bool(val)
                else:
                    cast_value = bool(val)
            else:
                # Use the native typing function directly.
                cast_value = native_type(val)
            values_dict[key] = cast_value
        except Exception:
            # If conversion fails, keep the original value (string).
            pass

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
        """
        import ast

        def cast_val(v):
            # Skip None values
            if v is None:
                return None
            # If bytes, decode to string
            if isinstance(v, (bytes, bytearray)):
                try:
                    v = v.decode()
                except Exception:
                    return v
            # Only attempt conversion on string types
            if not isinstance(v, str):
                return v

            s = v.strip()
            # Preserve quotes around strings
            if (s.startswith('"') and s.endswith('"')) or (s.startswith("'") and s.endswith("'")):
                return s[1:-1]
            # Try literal eval to catch numbers and lists
            try:
                return ast.literal_eval(s)
            except Exception:
                pass

            # Boolean conversion
            low = s.lower()
            if low in ("true", "yes", "1"):
                return True
            if low in ("false", "no", "0"):
                return False

            # Attempt int conversion
            try:
                return int(s, 0)
            except Exception:
                pass
            # Attempt float conversion
            try:
                return float(s)
            except Exception:
                pass

            # Fall back to original string
            return s

        for key, value in values_dict.items():
            if isinstance(value, (list, tuple)):
                values_dict[key] = [cast_val(v) for v in value]
            else:
                values_dict[key] = cast_val(value)

        return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
        """Casts arguments to correct types by modifying values_dict param.

        By default all the values are strings.

        :param parser_name: The command name, e.g. main, virsh, ospd, etc
        :param values_dict: The dict of with arguments
       """
        # Helper function to convert a single value string to its appropriate type
        def _convert_value(val):
            if not isinstance(val, str):
                return val
            val = val.strip()
            # Handle comma-separated lists
            if ',' in val:
                return [_convert_value(v.strip()) for v in val.split(',')]
            # Boolean values
            lowered = val.lower()
            if lowered == 'true':
                return True
            if lowered == 'false':
                return False
            # Integer value
            if val.isdigit() or (val.startswith('-') and val[1:].isdigit()):
                try:
                    return int(val)
                except ValueError:
                    pass
            # Float value
            try:
                fval = float(val)
                return fval
            except ValueError:
                pass
            # Default: keep as string
            return val

        # Try to apply any parser-specific custom conversion functions first
        # e.g., self._convert_<parser_name>_<argname>(value)
        for key, raw_val in list(values_dict.items()):
            # Attempt custom conversion method if it exists
            custom_method_name = f"_convert_{parser_name}_{key}"
            custom_func = getattr(self, custom_method_name, None)
            if callable(custom_func):
                try:
                    new_val = custom_func(raw_val)
                except Exception:
                    # fall back to generic conversion on failure
                    new_val = _convert_value(raw_val)
            else:
                new_val = _convert_value(raw_val)
            values_dict[key] = new_val
        return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Helper to flatten nested dictionaries
    def _flatten(d, parent_key='', sep='.'):
        items = {}
        for k, v in d.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            else:
                items[new_key] = v
        return items

    # Validate plugin_dir
    if not isinstance(plugin_dir, str):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory does not exist: {plugin_dir}")

    # Find spec file
    spec_file = None
    for fname in ('plugin.json', 'plugin.yaml', 'plugin.yml', 'spec.json', 'spec.yaml', 'spec.yml'):
        potential = os.path.join(plugin_dir, fname)
        if os.path.isfile(potential):
            spec_file = potential
            break

    if not spec_file:
        # No spec file found, return empty dict
        return {}

    # Load spec
    spec_data = {}
    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith('.json'):
                spec_data = json.load(f)
            else:
                try:
                    import yaml
                    spec_data = yaml.safe_load(f)
                except Exception as e:
                    # If yaml import fails or parsing fails, treat as empty
                    spec_data = {}
    except Exception as e:
        # Any error reading or parsing fallback to empty dict
        spec_data = {}

    # If not a dict, cannot flatten
    if not isinstance(spec_data, dict):
        return {}

    return _flatten(spec_data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    def _flatten(item, parent_key='', sep='.', out=None):
        """Recursively flatten a nested dictionary."""
        if out is None:
            out = {}
        if isinstance(item, dict):
            for k, v in item.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                _flatten(v, new_key, sep, out)
        elif isinstance(item, list):
            # Include lists as is; for deeper structures you could flatten each element with an index
            out[parent_key] = item
        else:
            out[parent_key] = item
        return out

    if not isinstance(plugin_dir, (str, bytes)):
        raise TypeError("plugin_dir must be a string path")
    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Directory {plugin_dir!r} does not exist")

    # Determine spec file path
    spec_file = None
    for fname in ("plugin.json", "plugin.yaml", "plugin_spec.json", "plugin_spec.yaml"):
        fpath = os.path.join(plugin_dir, fname)
        if os.path.isfile(fpath):
            spec_file = fpath
            break
    if spec_file is None:
        raise FileNotFoundError("No plugin spec file found in directory")

    # Load spec
    with open(spec_file, "r", encoding="utf-8") as fp:
        if spec_file.endswith(".json"):
            try:
                spec_data = json.load(fp)
            except json.JSONDecodeError as e:
                raise ValueError(f"Error parsing JSON spec file: {e}") from e
        else:
            # No yaml support by default; raise error
            raise ValueError("YAML spec files are not supported in this implementation")

    if not isinstance(spec_data, dict):
        raise ValueError("Plugin spec must be a dictionary at the top level")

    flat_dict = _flatten(spec_data)
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    spec_path = os.path.join(plugin_dir, "plugin.json")
    if not os.path.exists(spec_path):
        raise FileNotFoundError(f"plugin.json not found in {plugin_dir}")

    try:
        with open(spec_path, "r", encoding="utf-8") as f:
            spec = json.load(f)
    except json.JSONDecodeError as e:
        raise ValueError(f"Error decoding JSON in {spec_path}: {e}") from e

    result = {}

    def _flatten(d, parent_key=""):
        if not isinstance(d, dict):
            # If the root is not a dict, store it under the provided key
            result[parent_key] = d
            return
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key)
            else:
                result[new_key] = v

    _flatten(spec)
    return result

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Find the spec file
    spec_filenames = [
        'plugin.json', 'plugin.yaml', 'plugin.yml',
        'spec.json', 'spec.yaml', 'spec.yml'
    ]
    spec_path = None
    for name in spec_filenames:
        path = os.path.join(plugin_dir, name)
        if os.path.isfile(path):
            spec_path = path
            break
    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin specification file found in {plugin_dir}. "
            f"Tried: {', '.join(spec_filenames)}"
        )

    # Load JSON or YAML
    if spec_path.lower().endswith(('.yaml', '.yml')):
        try:
            import yaml
        except ImportError as exc:
            raise ImportError(
                "PyYAML is required to parse YAML plugin specifications."
            ) from exc
        with open(spec_path, 'r', encoding='utf-8') as f:
            try:
                spec = yaml.safe_load(f)
            except Exception as exc:
                raise ValueError(f"Error parsing YAML file {spec_path}: {exc}") from exc
    else:
        with open(spec_path, 'r', encoding='utf-8') as f:
            try:
                spec = json.load(f)
            except Exception as exc:
                raise ValueError(f"Error parsing JSON file {spec_path}: {exc}") from exc

    if not isinstance(spec, dict):
        raise ValueError(f"Plugin specification root must be a dictionary. Got {type(spec).__name__}")

    # Flatten the dictionary
    def _flatten(obj, prefix=''):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                key = f"{prefix}.{k}" if prefix else k
                items.update(_flatten(v, key))
        else:
            items[prefix] = obj
        return items

    flat_spec = _flatten(spec)
    return flat_spec

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json
    from pathlib import Path

    def _flatten(dict_obj, parent_key='', sep='.'):
        items = {}
        for k, v in dict_obj.items():
            new_key = f"{parent_key}{sep}{k}" if parent_key else k
            if isinstance(v, dict):
                items.update(_flatten(v, new_key, sep=sep))
            elif isinstance(v, list):
                # Convert lists to comma‑separated strings for flat representation
                items[new_key] = ','.join(str(i) for i in v)
            else:
                items[new_key] = v
        return items

    # Resolve plugin_dir to a Path object
    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        raise ValueError(f"Provided plugin_dir '{plugin_dir}' is not a directory")

    # Supported spec filenames (JSON)
    spec_names = [
        'plugin_spec.json',
        'plugin.json',
        'spec.json',
        'plugin_spec.yaml',
        'plugin.yaml',
        'spec.yaml',
    ]

    spec_file = None
    for name in spec_names:
        candidate = plugin_path / name
        if candidate.is_file():
            spec_file = candidate
            break

    if spec_file is None:
        raise FileNotFoundError(
            f"No plugin spec file found in {plugin_dir}. "
            f"Expected one of: {', '.join(spec_names)}"
        )

    # Load the spec (JSON only for safety; YAML requires PyYAML)
    try:
        if spec_file.suffix.lower() in {'.yaml', '.yml'}:
            # Attempt to load YAML if available
            import yaml  # type: ignore
            with open(spec_file, 'r', encoding='utf-8') as f:
                raw_spec = yaml.safe_load(f)
        else:
            with open(spec_file, 'r', encoding='utf-8') as f:
                raw_spec = json.load(f)
    except Exception as exc:
        raise ValueError(f"Failed to parse plugin spec '{spec_file}': {exc}") from exc

    if not isinstance(raw_spec, dict):
        raise ValueError(f"Plugin spec file must contain a top‑level JSON object, got {type(raw_spec)}")

    return _flatten(raw_spec)

def inject_config(self):
